@dataclass
class PipelineConfig:
    input_dir: Path
    output_path: Path
    total_chapters: Optional[int] = None
    bgm_path: Optional[Path] = None
    work_dir: Path = Path("./work")
    voice: str = "en-US-ChristopherNeural"
    openai_model: str = "gpt-4o-mini"
    openai_api_key: Optional[str] = None
    keep_temp: bool = False
    groq_api_key: Optional[str] = None
    groq_model: str = os.environ.get("GROQ_TEXT_MODEL", "qwen/qwen3.8-27b")
    translate: bool = True
    narration_provider: str = "auto"  # auto|openai|groq|ollama|none
    narration_model: Optional[str] = None  # override model for narration
    narration_style: str = "verbatim"  # verbatim = raw OCR words, in order, nothing added
                                       # cleanup  = same words, fixed reading order + OCR typos (needs LLM)
                                       # recap    = first-person retell (needs LLM)
    observer: bool = False             # verbatim-only: let a tiny local LLM (ollama
                                       # llama3.2:3b) repair garbled OCR tokens in place,
                                       # hard-guarded so it can only fix spelling
    # OPTIONAL: describe each panel's VISUAL action with a vision model and fold
    # that into the narration, so silent/action panels aren't just silence.
    # Off by default. Engine order: ollama (local, free, unlimited) unless a
    # cloud key makes another provider available.
    describe_visuals: bool = False
    visual_provider: str = "auto"      # auto|ollama|groq|gemini|openrouter|none
    visual_model: Optional[str] = None
    gemini_api_key: Optional[str] = None
    openrouter_api_key: Optional[str] = None
    # OPTIONAL: subtle camera motion instead of a hard slideshow. "none"
    # (default) keeps the fast static render; "kenburns" adds a slow drift.
    motion: str = "none"               # none|kenburns
    progress_file: Optional[Path] = None  # JSON file the Node service polls
    slice_only: bool = False  # if True, only run panel slicing then exit (used by the Node orchestrator so VLM can read individual sliced panels)
    production_mode: bool = False
    job_id: str = "local"
    recap_title: Optional[str] = None   # series title for the intro card; defaults to input-dir name
    intro: bool = True                  # prepend the spoken intro + title card
    watermark: Optional[str] = None     # small on-frame watermark text (e.g. channel name)
    min_free_disk_gb: float = 2.0  # ResourceGuard threshold — see run_pipeline()
    min_available_ram_mb: float = 300.0

    @property
    def temp_audio_dir(self) -> Path:
        return self.work_dir / "temp_audio"

    @property
    def temp_chapters_dir(self) -> Path:
        return self.work_dir / "temp_chapters"

    @property
    def temp_slices_dir(self) -> Path:
        return self.work_dir / "temp_slices"

    @property
    def temp_scripts_dir(self) -> Path:
        return self.work_dir / "temp_scripts"

    @property
    def state_file(self) -> Path:
        return self.work_dir / "pipeline_state.json"

    def ensure_dirs(self) -> None:
        for d in (
            self.temp_audio_dir,
            self.temp_chapters_dir,
            self.temp_slices_dir,
            self.temp_scripts_dir,
        ):
            d.mkdir(parents=True, exist_ok=True)

    def write_progress(self, stage: str, chapter_index: int, total_chapters: int,
                       message: str, status: str = "running", frac: float = 0.0,
                       substage: str = "") -> None:
        """Write a small JSON status file the Node orchestrator polls.

        `frac` (0..1) is progress WITHIN the current chapter — lets the bar
        move smoothly through a long chapter instead of only jumping at
        chapter boundaries. `substage` is a short machine tag for the UI
        stage rail (e.g. 'frame', 'ocr', 'visual', 'tts', 'encode')."""
        if not self.progress_file:
            return
        try:
            done = chapter_index + max(0.0, min(1.0, frac))
            pct = (done / max(1, total_chapters)) * 100.0 if total_chapters else 0.0
            payload = {
                "stage": stage,
                "substage": substage,
                "chapter_index": chapter_index,
                "chapter_frac": round(max(0.0, min(1.0, frac)), 3),
                "total_chapters": total_chapters,
                "progress": round(pct, 1),
                "message": message,
                "status": status,
                "updated_at": time.time(),
            }
            tmp = self.progress_file.with_suffix(".tmp")
            tmp.write_text(json.dumps(payload), encoding="utf-8")
            tmp.replace(self.progress_file)
        except Exception:
            pass


class OcrStatus:
    SUCCESS = "SUCCESS"
    UNCERTAIN = "UNCERTAIN"
    FAILED = "FAILED"
    NO_TEXT = "NO_TEXT"


def parse_narration_item(raw_item: object) -> dict:
    """Parse narration item into a structured dict with text, status, and confidence.
    Backward-compatible with string values, legacy list dicts, and richer upstream formats.
    """
    if raw_item is None:
        return {"text": "", "status": OcrStatus.NO_TEXT, "confidence": 0.0}

    if isinstance(raw_item, str):
        text = raw_item.strip()
        if text == "[transcription unavailable]":
            return {"text": "", "status": OcrStatus.FAILED, "confidence": 0.0}
        status = OcrStatus.SUCCESS if text else OcrStatus.NO_TEXT
        return {"text": text, "status": status, "confidence": 1.0 if text else 0.0}

    if isinstance(raw_item, dict):
        text = str(raw_item.get("text") or "").strip()
        if text == "[transcription unavailable]":
            return {"text": "", "status": OcrStatus.FAILED, "confidence": 0.0}

        raw_status = raw_item.get("status")
        if raw_status:
            status = str(raw_status).upper()
            if status not in (OcrStatus.SUCCESS, OcrStatus.UNCERTAIN, OcrStatus.FAILED, OcrStatus.NO_TEXT):
                status = OcrStatus.SUCCESS if text else OcrStatus.NO_TEXT
        else:
            status = OcrStatus.SUCCESS if text else OcrStatus.NO_TEXT

        conf = raw_item.get("confidence")
        try:
            confidence = float(conf) if conf is not None else (1.0 if status == OcrStatus.SUCCESS else 0.0)
        except (ValueError, TypeError):
            confidence = 1.0 if status == OcrStatus.SUCCESS else 0.0

        return {"text": text, "status": status, "confidence": confidence}

    return {"text": "", "status": OcrStatus.NO_TEXT, "confidence": 0.0}


@dataclass
class Chapter:
    index: int
    name: str
    folder: Path
    panel_paths: List[Path] = field(default_factory=list)
    image_narrations: dict = field(default_factory=dict)  # filename -> narration entry (from narration.json)

    @property
    def tag(self) -> str:
        return f"chap_{self.index:03d}"


