MANIFEST_VERSION = "2.0"


@dataclass
class FrameEntry:
    frame_id: str
    filename: str
    path: str
    source_page: str
    source_index: int
    frame_kind: str = "panel"  # "panel" | "scroll_frame" | "full_page"
    scroll_group: Optional[str] = None  # shared id for scroll_frame siblings sliced from one tall UI card
    ocr_path: str = ""  # tight raw-pixel crop to OCR (falls back to `path` — the composed canvas — when empty)
    ocr_status: str = "NONE"
    ocr_text: str = ""
    narration_text: str = ""
    audio_path: Optional[str] = None
    duration: Optional[float] = None
    # [x1,y1,x2,y2] of this frame's crop within its source_page, in that page's
    # native pixels — recorded for offline panel-detector training. None when
    # the crop spans a page seam (cross-page stitch). Purely informational:
    # nothing in the render path reads it.
    source_box: Optional[list] = None

    def to_dict(self) -> dict:
        return {
            "frame_id": self.frame_id,
            "filename": self.filename,
            "path": self.path,
            "source_page": self.source_page,
            "source_index": self.source_index,
            "frame_kind": self.frame_kind,
            "scroll_group": self.scroll_group,
            "ocr_status": self.ocr_status,
            "ocr_text": self.ocr_text,
            "narration_text": self.narration_text,
            "audio_path": self.audio_path,
            "duration": self.duration,
            "source_box": self.source_box,
        }

    @classmethod
    def from_dict(cls, data: dict, default_chapter_tag: str = "chap_000") -> "FrameEntry":
        fname = str(data.get("filename") or "")
        fpath = str(data.get("path") or "")
        if not fname and fpath:
            fname = Path(fpath).name

        fid = str(data.get("frame_id") or "")
        if not fid:
            if fname:
                stem = Path(fname).stem
                fid = f"{default_chapter_tag}_{stem}"
            else:
                fid = f"{default_chapter_tag}_frame_00000"

        return cls(
            frame_id=fid,
            filename=fname,
            path=fpath,
            source_page=str(data.get("source_page") or ""),
            source_index=int(data.get("source_index", 0)),
            frame_kind=str(data.get("frame_kind") or "panel"),
            scroll_group=data.get("scroll_group"),
            source_box=data.get("source_box"),
            ocr_status=str(data.get("ocr_status") or "NONE"),
            ocr_text=str(data.get("ocr_text") or ""),
            narration_text=str(data.get("narration_text") or ""),
            audio_path=data.get("audio_path"),
            duration=float(data["duration"]) if data.get("duration") is not None else None,
        )


@dataclass
class CanonicalManifest:
    manifest_version: str
    job_id: str
    chapter_tag: str
    source_pages: List[str]
    frames: List[FrameEntry]

    def to_dict(self) -> dict:
        return {
            "manifest_version": self.manifest_version,
            "job_id": self.job_id,
            "chapter_tag": self.chapter_tag,
            "source_pages": self.source_pages,
            "frames": [f.to_dict() for f in self.frames],
            "legacy_frames": [f.path for f in self.frames],
            "sources": [f.source_index for f in self.frames],
        }

    def save(self, manifest_path: Path) -> None:
        manifest_path.parent.mkdir(parents=True, exist_ok=True)
        tmp_path = manifest_path.with_suffix(".tmp")
        tmp_path.write_text(json.dumps(self.to_dict(), indent=2), encoding="utf-8")
        tmp_path.replace(manifest_path)


def load_or_migrate_manifest(
    manifest_path: Path,
    chapter: Optional[Chapter] = None,
    job_id: str = "local",
) -> Optional[CanonicalManifest]:
    """Load a manifest file. If legacy v1 format, migrate explicitly to v2.0."""
    if not manifest_path.exists():
        return None

    try:
        data = json.loads(manifest_path.read_text(encoding="utf-8"))
    except Exception as exc:
        log.warning("Manifest %s is invalid JSON: %s", manifest_path, exc)
        return None

    chapter_tag = chapter.tag if chapter else str(data.get("chapter_tag") or "chap_000")
    source_pages = []
    if "source_pages" in data and isinstance(data["source_pages"], list):
        source_pages = [str(sp) for sp in data["source_pages"]]
    elif chapter:
        source_pages = [p.name for p in chapter.panel_paths]

    raw_frames = data.get("frames")
    if not isinstance(raw_frames, list):
        return None

    if data.get("manifest_version") == MANIFEST_VERSION and raw_frames and isinstance(raw_frames[0], dict):
        entries = [FrameEntry.from_dict(f, chapter_tag) for f in raw_frames]
        manifest = CanonicalManifest(
            manifest_version=MANIFEST_VERSION,
            job_id=str(data.get("job_id") or job_id),
            chapter_tag=chapter_tag,
            source_pages=source_pages or [str(sp) for sp in data.get("source_pages", [])],
            frames=entries,
        )
        return manifest

    sources = data.get("sources") or []
    entries = []
    for idx, f_item in enumerate(raw_frames):
        if isinstance(f_item, str):
            fpath = f_item
            fname = Path(f_item).name
            src_idx = sources[idx] if idx < len(sources) and isinstance(sources[idx], int) else 0
            src_page = source_pages[src_idx] if src_idx < len(source_pages) else f"page_{src_idx:03d}.jpg"
            frame_id = f"{chapter_tag}_frame_{idx:05d}"
            entries.append(
                FrameEntry(
                    frame_id=frame_id,
                    filename=fname,
                    path=fpath,
                    source_page=src_page,
                    source_index=src_idx,
                    frame_kind="panel",
                )
            )
        elif isinstance(f_item, dict):
            entries.append(FrameEntry.from_dict(f_item, chapter_tag))

    migrated = CanonicalManifest(
        manifest_version=MANIFEST_VERSION,
        job_id=str(data.get("job_id") or job_id),
        chapter_tag=chapter_tag,
        source_pages=source_pages,
        frames=entries,
    )
    try:
        migrated.save(manifest_path)
        log.info("[%s] Migrated legacy manifest to v2.0 format (%d frames)", chapter_tag, len(entries))
    except Exception as exc:
        log.warning("[%s] Failed to save migrated manifest: %s", chapter_tag, exc)

    return migrated


def validate_canonical_manifest(
    manifest_path: Path,
    chapter: Chapter,
    job_id: str = "local",
) -> tuple[bool, Optional[CanonicalManifest], str]:
    """Strictly validate existing manifest for resume behavior.

    Returns (is_valid, canonical_manifest_obj, reason).
    Checks:
    1. Manifest file exists and is valid JSON/schema.
    2. All expected frame files exist on disk and are non-empty.
    3. Frame IDs are consistent and unique.
    4. Source page relationships match the current chapter's panel paths.
    """
    manifest = load_or_migrate_manifest(manifest_path, chapter=chapter, job_id=job_id)
    if not manifest:
        return False, None, "Manifest missing or unparseable"

    if not manifest.frames:
        return False, None, "Manifest contains zero frames"

    frame_ids = [f.frame_id for f in manifest.frames]
    if len(frame_ids) != len(set(frame_ids)):
        return False, None, "Manifest contains duplicate frame IDs"

    expected_sources = [p.name for p in chapter.panel_paths]
    if manifest.source_pages and manifest.source_pages != expected_sources:
        return False, None, f"Source pages mismatch: expected {expected_sources}, manifest has {manifest.source_pages}"

    slice_dir = manifest_path.parent
    for frame in manifest.frames:
        target = Path(frame.path)
        if not target.exists():
            target = slice_dir / frame.filename
        if not target.exists() or target.stat().st_size < 100:
            return False, None, f"Frame file missing or invalid on disk: {frame.filename}"

    return True, manifest, "Valid manifest"


# ---------------------------------------------------------------------------
# 1. INGESTION
# ---------------------------------------------------------------------------

def natural_sort_key(p: Path):
    return [int(t) if t.isdigit() else t.lower() for t in re.split(r"(\d+)", p.stem)]


def discover_chapters(cfg: PipelineConfig) -> List[Chapter]:
    """Scan input_dir for chapter_XXX folders, sort numerically, load panels + narrations."""
    if not cfg.input_dir.exists():
        raise FileNotFoundError(f"Input directory not found: {cfg.input_dir}")

    chapter_dirs = sorted(
        [d for d in cfg.input_dir.iterdir() if d.is_dir()],
        key=natural_sort_key,
    )
    if not chapter_dirs:
        raise FileNotFoundError(f"No chapter subfolders found in {cfg.input_dir}")

    if cfg.total_chapters:
        chapter_dirs = chapter_dirs[: cfg.total_chapters]

    chapters: List[Chapter] = []
    for i, d in enumerate(chapter_dirs, start=1):
        panels = sorted(
            [p for p in d.iterdir() if p.suffix.lower() in IMAGE_EXTS],
            key=natural_sort_key,
        )
        if not panels:
            log.warning("Chapter folder %s has no images — skipping", d.name)
            continue

        # Load per-image narrations from narration.json.
        narration_file = d / "narration.json"
        image_narrations: dict = {}
        if narration_file.exists():
            try:
                narr_data = json.loads(narration_file.read_text(encoding="utf-8"))
                if isinstance(narr_data, list):
                    for item in narr_data:
                        if isinstance(item, dict) and "image" in item:
                            image_narrations[item["image"]] = item
                elif isinstance(narr_data, dict):
                    for k, v in narr_data.items():
                        image_narrations[k] = v
                log.info("[%s] loaded %d per-image narrations from narration.json", d.name, len(image_narrations))
            except Exception as e:
                log.warning("[%s] failed to parse narration.json: %s", d.name, e)
        else:
            log.warning("No narration.json in %s — chapters will have no narration text", d.name)

        chapters.append(
            Chapter(
                index=i, name=d.name, folder=d, panel_paths=panels,
                image_narrations=image_narrations,
            )
        )

    log.info("Discovered %d chapters (%d total panel images)", len(chapters), sum(len(c.panel_paths) for c in chapters))
    return chapters


# ---------------------------------------------------------------------------
# 2. UNIFORM CANVAS SLICING ENGINE (gutter-aware)
# ---------------------------------------------------------------------------


# ---------------------------------------------------------------------------
# 2a. BUBBLE-SAFE GUTTER DETECTION
#
# Guarantee: a horizontal cut is only ever placed on a row that is 100%
# free of "content" (art, line-work, text glyphs, bubble borders) across
# the ENTIRE width of the page, measured on a lightly-dilated content mask.
# Dilation bridges anti-aliasing gaps in bubble outlines and the small gaps
# between individual glyphs/letters so a bubble or text line is always seen
# as one solid blob — it is structurally impossible for a cut chosen this
# way to slice through the middle of a bubble, a line of text, or artwork,
# because any row that touches such a blob anywhere along its width is
# disqualified as a cut candidate.
# ---------------------------------------------------------------------------

def _get_text_detector():
    """Lazily load and cache the comic text/bubble detector (RT-DETR-v2,
    see TEXT_DETECTOR_MODEL_ID above). Loaded at most once per process;
    returns (None, None) cheaply on every subsequent call if it's missing
    or fails to load, so callers can unconditionally check the return
    value rather than needing their own separate "is this available"
    flag. Returns (model, image_processor) since RT-DETR-v2 inference via
    transformers needs both."""
    global _text_detector_model, _text_detector_processor, _text_detector_load_attempted
    if _text_detector_load_attempted:
        return _text_detector_model, _text_detector_processor
    _text_detector_load_attempted = True
    if not TEXT_DETECTOR_LOCAL_DIR.exists():
        log.info("Comic text/bubble detector not found at %s — skipping (pixel-only mask still applies)", TEXT_DETECTOR_LOCAL_DIR)
        return None, None
    try:
        _cap_torch_threads()
        from transformers import RTDetrImageProcessor, RTDetrV2ForObjectDetection
        _text_detector_processor = RTDetrImageProcessor.from_pretrained(str(TEXT_DETECTOR_LOCAL_DIR))
        _text_detector_model = RTDetrV2ForObjectDetection.from_pretrained(str(TEXT_DETECTOR_LOCAL_DIR))
        _text_detector_model.eval()
        log.info("Loaded comic text/bubble detector from %s", TEXT_DETECTOR_LOCAL_DIR)
    except Exception as exc:
        log.warning("Failed to load comic text/bubble detector (%s) — continuing without it", exc)
        _text_detector_model = None
        _text_detector_processor = None
    return _text_detector_model, _text_detector_processor


def _get_text_detector_onnx():
    """The small INT8 RT-DETR-v2 ONNX (TEXT_DETECTOR_ONNX_PATH). onnxruntime
    only, no torch. (None) if absent / fails."""
    global _text_detector_onnx, _text_detector_onnx_attempted
    if _text_detector_onnx_attempted:
        return _text_detector_onnx
    _text_detector_onnx_attempted = True
    if not TEXT_DETECTOR_ONNX_PATH.exists():
        return None
    try:
        _text_detector_onnx = _ort_session(TEXT_DETECTOR_ONNX_PATH, "text-bubble")
        log.info("Loaded comic text/bubble detector (INT8 ONNX) from %s", TEXT_DETECTOR_ONNX_PATH)
    except Exception as exc:  # pragma: no cover
        log.warning("text/bubble ONNX load failed (%s) — falling back to torch path", exc)
        _text_detector_onnx = None
    return _text_detector_onnx


def _detect_text_boxes_raw(img_gray) -> List[tuple]:
    """Run the text/bubble detector on ONE image as-is (no tall-image
    splitting -- see _detect_text_boxes for that), returning only its
    text_bubble and text_free class detections (both represent real,
    readable text; text_free specifically covers caption/narration boxes
    outside any speech bubble, which a plain bubble-only detector
    wouldn't distinguish from the empty bubble class) as (x1,y1,x2,y2)
    boxes in the image's own pixel coordinates. Empty list if the model
    is unavailable or detects nothing.
    """
    sess = _get_text_detector_onnx()
    if sess is not None:
        try:
            rgb = cv2.cvtColor(img_gray, cv2.COLOR_GRAY2RGB) if img_gray.ndim == 2 else img_gray
            h, w = rgb.shape[:2]
            S = TEXT_DETECTOR_ONNX_INPUT
            x = cv2.resize(rgb, (S, S)).transpose(2, 0, 1)[None].astype(np.float32) / 255.0
            labels, boxes, scores = sess.run(
                None, {"images": x, "orig_target_sizes": np.array([[h, w]], dtype=np.int64)})
            out = []
            for lab, box, sc in zip(labels[0], boxes[0], scores[0]):
                if float(sc) < 0.35 or int(lab) not in (1, 2):   # 1=text_bubble 2=text_free
                    continue
                x1, y1, x2, y2 = (int(round(float(v))) for v in box)
                if x2 - x1 >= 4 and y2 - y1 >= 4:
                    out.append((max(0, x1), max(0, y1), min(w, x2), min(h, y2)))
            return out
        except Exception as exc:  # pragma: no cover
            log.warning("text/bubble ONNX inference failed (%s) — trying torch path", exc)
    model, processor = _get_text_detector()
    if model is None:
        return []
    try:
        import torch
        from PIL import Image as PILImage
        img_rgb = cv2.cvtColor(img_gray, cv2.COLOR_GRAY2RGB) if img_gray.ndim == 2 else img_gray
        pil_img = PILImage.fromarray(img_rgb)
        inputs = processor(images=pil_img, return_tensors="pt")
        with torch.no_grad():
            outputs = model(**inputs)
        results = processor.post_process_object_detection(
            outputs, target_sizes=torch.tensor([(pil_img.height, pil_img.width)]), threshold=0.3,
        )
        boxes = []
        for result in results:
            for label_id, box in zip(result["labels"], result["boxes"]):
                label = int(label_id.item())
                if label not in (1, 2):  # 1=text_bubble, 2=text_free
                    continue
                x1, y1, x2, y2 = [round(float(v)) for v in box.tolist()]
                boxes.append((x1, y1, x2, y2))
        return boxes
    except Exception as exc:
        log.warning("Text/bubble detection failed (%s) — continuing with pixel-only mask", exc)
        return []


def _detect_text_boxes(img_gray) -> List[tuple]:
    """Run text/bubble detection on `img_gray`, splitting it into
    overlapping vertical bands first if it's unusually tall.

    Directly mirrors this model's own training preprocessing
    ("Tall Webtoons were split vertically", per its model card) rather
    than feeding it a single extreme-aspect-ratio image its training
    distribution didn't contain examples of -- a real, tall vertical
    manhwa page (or a merged multi-panel crop) fed in whole is out of
    distribution for a detector trained on pre-split, more reasonably-
    proportioned bands, which is a very plausible reason detections were
    still missing important text on this pipeline's actual webtoon
    content even after switching to a webtoon-inclusive model.

    Bands overlap by 20% of the band height so a text box that would
    otherwise straddle a band boundary is fully visible in at least one
    band. Detections from each band are offset back into the original
    image's coordinates and merged, de-duplicating boxes that show up
    in more than one overlapping band (by simple bounding-box containment
    rather than a full NMS pass -- adequate here since overlapping bands
    of the same source image produce near-identical, not just similar,
    duplicate detections).
    """
    h, w = img_gray.shape[:2]
    # Content cache — the same page is text-detected up to 3x per run
    # (_detect_page_panels enrichment, _compose_canvas, _should_scroll_fragment).
    # A cheap subsampled digest keys them together. Bounded to the last 64 pages.
    try:
        _k = (w, h, hash(img_gray[::37, ::37].tobytes()))
        _c = _detect_text_boxes._cache
        if _k in _c:
            return _c[_k]
    except Exception:
        _k = None

    if w == 0 or h / max(1, w) <= TALL_IMAGE_SPLIT_ASPECT_RATIO:
        _r = _detect_text_boxes_raw(img_gray)
        if _k is not None:
            _detect_text_boxes._cache[_k] = _r
        return _r

    band_h = w * TALL_IMAGE_SPLIT_ASPECT_RATIO
    overlap = band_h * 0.2
    step = band_h - overlap
    all_boxes = []  # type: List[tuple]
    y = 0.0
    while y < h:
        band_top = int(y)
        band_bot = int(min(h, y + band_h))
        band = img_gray[band_top:band_bot, :]
        for (x1, y1, x2, y2) in _detect_text_boxes_raw(band):
            all_boxes.append((x1, y1 + band_top, x2, y2 + band_top))
        if band_bot >= h:
            break
        y += step

    # De-duplicate: drop any box that's near-fully contained within an
    # already-kept box from an earlier (overlapping) band.
    deduped = []  # type: List[tuple]
    for box in all_boxes:
        x1, y1, x2, y2 = box
        area = max(1, (x2 - x1) * (y2 - y1))
        is_dup = False
        for kx1, ky1, kx2, ky2 in deduped:
            ix1, iy1 = max(x1, kx1), max(y1, ky1)
            ix2, iy2 = min(x2, kx2), min(y2, ky2)
            if ix2 > ix1 and iy2 > iy1:
                inter = (ix2 - ix1) * (iy2 - iy1)
                if inter / area > 0.8:
                    is_dup = True
                    break
        if not is_dup:
            deduped.append(box)
    if _k is not None:
        _c = _detect_text_boxes._cache
        _c[_k] = deduped
        if len(_c) > 64:
            _c.pop(next(iter(_c)))
    return deduped


_detect_text_boxes._cache = {}


# ---------------------------------------------------------------------------
# Face + bubble detectors — fused into the slicer as NO-CUT ZONES.
# ---------------------------------------------------------------------------

def _get_face_session():
    global _face_session, _face_load_attempted
    if _face_load_attempted:
        return _face_session
    _face_load_attempted = True
    face_path = _resolve_model(*FACE_ONNX_CANDIDATES)
    if face_path is None:
        log.info("anime-face detector not found (%s) — skipping face no-cut zones", FACE_ONNX_PATH)
        return None
    try:
        _face_session = _ort_session(face_path, "anime-face")
        log.info("Loaded anime-face detector (ONNX) from %s", face_path.name)
    except Exception as exc:  # pragma: no cover
        log.warning("anime-face detector load failed (%s)", exc)
        _face_session = None
    return _face_session


def _get_bubble_model():
    global _bubble_model, _bubble_load_attempted
    if _bubble_load_attempted:
        return _bubble_model
    _bubble_load_attempted = True
    bubble_path = _resolve_model(*BUBBLE_MODEL_CANDIDATES)
    if bubble_path is None:
        return None
    try:
        _cap_torch_threads()
        from ultralytics import YOLO
        # YOLO() loads .pt and .onnx alike (onnxruntime backend, Results API
        # unchanged), so a YOLO26n ONNX export is a drop-in — and faster on CPU.
        _bubble_model = YOLO(str(bubble_path))
        log.info("Loaded comic speech-bubble detector from %s", bubble_path.name)
    except Exception as exc:  # pragma: no cover
        log.warning("bubble detector load failed (%s)", exc)
        _bubble_model = None
    return _bubble_model


def _nms(boxes, iou=0.45):
    boxes = sorted(boxes, key=lambda b: -b[4])
    keep = []
    for b in boxes:
        ab = max(1, (b[2] - b[0]) * (b[3] - b[1]))
        if all((max(0, min(b[2], k[2]) - max(b[0], k[0])) *
                max(0, min(b[3], k[3]) - max(b[1], k[1]))) / ab < iou for k in keep):
            keep.append(b)
    return keep


def _detect_faces_raw(rgb, imgsz=640, conf=0.30):
    sess = _get_face_session()
    if sess is None:
        return []
    h, w = rgb.shape[:2]
    s = imgsz / max(h, w)
    nw, nh = max(1, int(round(w * s))), max(1, int(round(h * s)))
    canvas = np.full((imgsz, imgsz, 3), 114, np.uint8)
    canvas[:nh, :nw] = cv2.resize(rgb, (nw, nh))
    x = canvas.transpose(2, 0, 1)[None].astype(np.float32) / 255.0
    try:
        inp = sess.get_inputs()[0].name
        out = np.asarray(sess.run(None, {inp: x})[0])
    except Exception:
        return []
    while out.ndim > 2:
        out = out[0]
    if out.ndim != 2 or out.size == 0:
        return []
    res = []
    if out.shape[1] == 6 and out.shape[0] != 6:
        # YOLO26 end-to-end head: (N, 6) = [x1, y1, x2, y2, score, cls] in
        # letterbox pixels — no cx/cy/wh decode, no NMS needed.
        for row in out:
            x1b, y1b, x2b, y2b, sc = (float(row[0]), float(row[1]),
                                      float(row[2]), float(row[3]), float(row[4]))
            if sc < conf:
                continue
            res.append((max(0.0, x1b / s), max(0.0, y1b / s),
                        min(float(w), x2b / s), min(float(h), y2b / s), sc))
        return _nms(res)
    # Classic v8/v11 head: (4+nc, A) or (A, 4+nc), boxes as cx, cy, bw, bh.
    if out.shape[0] < out.shape[1]:
        out = out.T
    for row in out:
        cx, cy, bw, bh = row[:4]
        sc = float(row[4:].max()) if row.shape[0] > 4 else float(row[4])
        if sc < conf:
            continue
        res.append((max(0.0, (cx - bw / 2) / s), max(0.0, (cy - bh / 2) / s),
                    min(float(w), (cx + bw / 2) / s), min(float(h), (cy + bh / 2) / s), sc))
    return _nms(res)


def _detect_regions_tallsafe(rgb, fn, band_ratio=2.0):
    """Run detector `fn(rgb)->[(x1,y1,x2,y2,score)]` on `rgb`, splitting a tall
    image into 20%-overlapping vertical bands first (offset detections back)."""
    h, w = rgb.shape[:2]
    if w == 0 or h / max(1, w) <= band_ratio:
        return fn(rgb)
    band_h = int(w * band_ratio)
    step = max(1, int(band_h * 0.8))
    out, y = [], 0
    while y < h:
        b0, b1 = int(y), int(min(h, y + band_h))
        for (x1, y1, x2, y2, sc) in fn(rgb[b0:b1]):
            out.append((x1, y1 + b0, x2, y2 + b0, sc))
        if b1 >= h:
            break
        y += step
    return _nms(out)


def _detect_faces(rgb):
    try:
        return _detect_regions_tallsafe(rgb, _detect_faces_raw)
    except Exception as exc:  # pragma: no cover
        log.debug("face detection skipped (%s)", exc)
        return []


def _detect_bubbles(rgb):
    m = _get_bubble_model()
    if m is None:
        return []
    def _one(sub):
        try:
            r = m.predict(sub, imgsz=1024, conf=0.30, verbose=False)[0]
        except Exception:
            return []
        if r.boxes is None:
            return []
        xy = r.boxes.xyxy.cpu().numpy()
        cf = r.boxes.conf.cpu().numpy()
        return [(float(a), float(b), float(c), float(d), float(s)) for (a, b, c, d), s in zip(xy, cf)]
    try:
        return _detect_regions_tallsafe(rgb, _one)
    except Exception as exc:  # pragma: no cover
        log.debug("bubble detection skipped (%s)", exc)
        return []


def _face_row_mask(rgb, H, dilate=20):
    """Boolean per-row: True where a horizontal cut is HARD-forbidden — inside
    a detected face (+`dilate` px). Faces are the only true no-cut zone: a
    speech bubble floating in a gutter must be ASSIGNED to a panel, not skipped
    (skipping it merges the two panels). RECAP_NOCUT_ZONES=0 disables."""
    mask = np.zeros(int(H), dtype=bool)
    if os.environ.get("RECAP_NOCUT_ZONES", "1").lower() in ("0", "false", "no"):
        return mask
    regions = []
    try:
        regions += [b[:4] for b in _detect_faces(rgb)]
    except Exception:
        pass
    if os.environ.get("RECAP_BUBBLE_DETECT", "0").lower() in ("1", "true", "yes"):
        try:
            regions += [b[:4] for b in _detect_bubbles(rgb)]
        except Exception:
            pass
    for (_x1, y1, _x2, y2) in regions:
        a = max(0, int(y1) - dilate)
        b = min(int(H), int(y2) + dilate)
        if b > a:
            mask[a:b] = True
    return mask


def _add_text_boxes_to_mask(mask, img_gray) -> "np.ndarray":
    """Fill each detected text box into `mask` as a solid rectangle.

    This is what actually fixes multi-line captions getting sliced into
    single-line fragments: _build_dilated_content_mask's pixel threshold
    correctly protects a single line of ink, but the white space *between*
    two lines of the same caption box reads identically to a real
    inter-panel gutter, since there's no concept of "these separate lines
    belong to one logical block" at the pixel level. Filling in the
    model's own text bounding box turns the whole caption -- gaps
    included -- into one solid, connected blob, so the existing
    _check_bubble_union/gutter-scan logic (unchanged) naturally treats it
    as one indivisible unit. A small inward margin is trimmed off each
    box edge so an over-generous detection box doesn't accidentally
    swallow a genuine gutter running right alongside it.
    """
    text_boxes = _detect_text_boxes(img_gray)
    if not text_boxes:
        return mask
    h, w = mask.shape[:2]
    margin = 2
    for (x1, y1, x2, y2) in text_boxes:
        x1 = max(0, x1 + margin)
        y1 = max(0, y1 + margin)
        x2 = min(w, x2 - margin)
        y2 = min(h, y2 - margin)
        if x2 > x1 and y2 > y1:
            mask[y1:y2, x1:x2] = 255
    return mask


def _build_dilated_content_mask(img_gray, dark_thresh: int = 200) -> "np.ndarray":
    """Binary mask (255 = content) of everything that isn't near-white
    background, lightly dilated/closed so speech-bubble outlines, thin text
    strokes, and screentone dots merge into solid blobs instead of leaving
    tiny gaps that a naive row-scan could mistake for a safe gutter."""
    _, mask = cv2.threshold(img_gray, dark_thresh, 255, cv2.THRESH_BINARY_INV)
    # Bridge small horizontal gaps (letter spacing, bubble outline breaks)
    # without merging across a real gutter — kernel stays modest vertically.
    close_kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (9, 5))
    mask = cv2.morphologyEx(mask, cv2.MORPH_CLOSE, close_kernel, iterations=1)
    mask = cv2.dilate(mask, np.ones((3, 3), np.uint8), iterations=1)
    return mask


def _label_content_components(mask) -> List[tuple]:
    """Connected components of a content mask → list of (y1, y2, x1, x2, area)
    bounding boxes, used to sanity-check that no cut straddles a real blob
    (bubble, text line, character, etc.)."""
    n, _labels, stats, _ = cv2.connectedComponentsWithStats(mask, connectivity=8)
    comps = []
    for i in range(1, n):
        x, y, w, h, area = stats[i]
        if area < 6:
            continue
        comps.append((int(y), int(y + h), int(x), int(x + w), int(area)))
    return comps


def _detect_panels_gutter_aware(img_gray) -> List[tuple]:
    """Bubble-safe panel detector for webtoon-style tall strips.

    Unlike percentage/variance-based gutter heuristics, a row is only ever
    classified as a valid cut if it is checked across N independent
    width-slices of the DILATED content mask and is completely empty in
    every one of them. This is a strictly stronger guarantee than "mostly
    white" — a bubble tail, a caption box, or a stray character sitting in
    an otherwise-white gap will keep that row (and the whole band around it,
    once merged with neighbours) out of consideration.

    Returns list of (x1, y1, x2, y2) tuples, full page width, sorted by y.
    """
    h, w = img_gray.shape
    if h < 10 or w < 10:
        return [(0, 0, w, h)]

    mask = _build_dilated_content_mask(img_gray)
    mask = _add_text_boxes_to_mask(mask, img_gray)
    components = _label_content_components(mask)

    n_slices = 8
    slice_w = max(1, w // n_slices)
    row_has_any_content = np.any(mask > 0, axis=1)
    is_gutter_row = np.zeros(h, dtype=bool)
    for y in range(h):
        if not row_has_any_content[y]:
            is_gutter_row[y] = True
            continue
        clear = True
        for s in range(n_slices):
            x0 = s * slice_w
            x1 = w if s == n_slices - 1 else (s + 1) * slice_w
            if np.any(mask[y, x0:x1] > 0):
                clear = False
                break
        is_gutter_row[y] = clear

    # Smooth to reject single-row noise (e.g. one stray dead pixel briefly
    # flipping a row to "gutter" inside dense artwork), but never smooth
    # enough to let a real gutter get swallowed.
    is_gutter_row = cv2.blur(
        is_gutter_row.astype(np.float32).reshape(-1, 1), (5, 1)
    ).flatten() > 0.6

    min_band_h = max(12, h // 350)
    bands: List[tuple] = []
    run_start = None
    for i, g in enumerate(is_gutter_row):
        if g and run_start is None:
            run_start = i
        elif not g and run_start is not None:
            if i - run_start >= min_band_h:
                bands.append((run_start, i))
            run_start = None
    if run_start is not None and h - run_start >= min_band_h:
        bands.append((run_start, h))

    if not bands:
        return [(0, 0, w, h)]

    # Cut at the safest row within each band — the row farthest from any
    # component that comes close to (but, by construction, never crosses)
    # the band's edges — then double-checked against every component so a
    # cut can never land inside a bbox that happens to graze the band.
    cut_points: List[int] = []
    for (s, e) in bands:
        cut = (s + e) // 2
        for (cy1, cy2, _cx1, _cx2, area) in components:
            if area < 40 or cy2 <= s or cy1 >= e:
                continue
            top_gap, bot_gap = cy1 - s, e - cy2
            if top_gap > bot_gap and top_gap > 4:
                cut = min(cut, s + max(2, top_gap // 2))
            elif bot_gap > 4:
                cut = max(cut, e - max(2, bot_gap // 2))
        cut_points.append(cut)

    boundaries = [0] + cut_points + [h]
    min_panel_h = max(30, h // 100)
    raw_panels = []
    for i in range(len(boundaries) - 1):
        top, bot = boundaries[i], boundaries[i + 1]
        if bot - top >= min_panel_h:
            raw_panels.append((0, top, w, bot))

    content_panels = [p for p in raw_panels if np.any(mask[p[1]:p[3], :] > 0)]
    if not content_panels:
        return [(0, 0, w, h)]

    # Merge runs of small adjacent fragments (e.g. a caption strip that got
    # isolated by a thin gutter) so they read as one coherent frame.
    merged = [list(content_panels[0])]
    for (x1, y1, x2, y2) in content_panels[1:]:
        prev = merged[-1]
        if (y2 - y1) < 150 and (prev[3] - prev[1]) < 200:
            prev[2], prev[3] = x2, y2
        else:
            merged.append([x1, y1, x2, y2])

    return [(p[0], p[1], p[2], p[3]) for p in merged if (p[3] - p[1]) >= min_panel_h]


def _check_bubble_union(mask, cut_y: int, img_shape: tuple) -> int:
    """Bubble Union Check:
    If a horizontal cut line intersects a content blob (speech bubble, text glyph, ascender, descender, or sound effect tail),
    move the cut line below (or above) the entire speech bubble component to keep dialogue intact in a single frame.
    """
    h, w = img_shape[:2]
    cut_y = max(0, min(h - 1, cut_y))
    if not np.any(mask[cut_y, :] > 0):
        return cut_y

    # Label connected components directly on binary mask
    n_labels, labels, stats, centroids = cv2.connectedComponentsWithStats(mask, connectivity=8)
    intersected_bottoms = []
    intersected_tops = []
    for i in range(1, n_labels):
        cy1 = stats[i, cv2.CC_STAT_TOP]
        ch = stats[i, cv2.CC_STAT_HEIGHT]
        cy2 = cy1 + ch
        area = stats[i, cv2.CC_STAT_AREA]
        if area < 6:
            continue
        if cy1 <= cut_y < cy2:
            intersected_bottoms.append(cy2)
            intersected_tops.append(cy1)

    if intersected_bottoms:
        # Move cut line below the max bottom of intersected speech bubbles
        target_y = max(intersected_bottoms) + 5
        if target_y < h:
            return target_y
        # If moving below exceeds image height, move above the min top
        target_y = max(0, min(intersected_tops) - 5)
        return target_y

    return cut_y


def _apply_dynamic_padding(panel_box: tuple, mask, img_shape: tuple, padding_px: int = 30) -> tuple:
    """Minimum Vertical Padding & Speech Bubble Protection:
    When a panel slice contains text contours or speech bubbles near its top or bottom borders,
    automatically expand the slice bounding box by 30 pixels vertically (clamped to image height).
    """
    x1, y1, w, h = panel_box
    img_h, img_w = img_shape[:2]
    y2 = y1 + h

    # Check top boundary region (y1 to y1 + padding_px)
    top_region = mask[max(0, y1):min(img_h, y1 + padding_px), max(0, x1):min(img_w, x1 + w)]
    # Check bottom boundary region (y2 - padding_px to y2)
    bot_region = mask[max(0, y2 - padding_px):min(img_h, y2), max(0, x1):min(img_w, x1 + w)]

    new_y1 = y1
    new_y2 = y2

    if np.any(top_region > 0):
        new_y1 = max(0, y1 - padding_px)
    if np.any(bot_region > 0):
        new_y2 = min(img_h, y2 + padding_px)

    return (x1, new_y1, w, new_y2 - new_y1)


def _snap_cut_to_safe_row(mask, y: int, window: int = 24) -> int:
    """Nudge a candidate horizontal edge to the nearest row that is
    completely clear of content across the full width, within +/- window
    px. Applied as a final safety net to panel boxes from ANY detector
    (YOLO, contour, gutter-aware) so an edge can never clip a bubble tail
    or a line of text even if the upstream detector placed it a few pixels
    off. Returns the original y if no safe row is found nearby (better to
    keep the original box than snap arbitrarily far away)."""
    h = mask.shape[0]
    y = max(0, min(h - 1, y))

    # Perform Bubble Union check if cut intersects speech bubble
    y = _check_bubble_union(mask, y, (h, mask.shape[1]))

    if not np.any(mask[y, :] > 0):
        return y
    for d in range(1, window + 1):
        for cand in (y + d, y - d):  # Prefer moving down below text
            if 0 <= cand < h and not np.any(mask[cand, :] > 0):
                return cand
    return y


def _detect_panels_for_page(img_gray) -> tuple:
    """Top-level panel detector for one source page/strip image.

    Webtoon/manhwa raws are dominated by tall, single-column strips — for
    those, the bubble-safe gutter-aware detector gives the strongest
    guarantee (cuts can never cross a content pixel). For roughly
    page-shaped images (traditional multi-panel grid layouts), fall back to
    the existing YOLO/contour auto-detector, which understands multi-column
    layouts that a pure horizontal-gutter scan can't.

    Returns (panels, method_name) where panels is a list of (x, y, w, h)
    tuples and method_name is one of "gutter_aware", "yolo", "contour", or
    "whole_page" — identifying which detector actually produced the result,
    so callers can log an accurate summary instead of assuming one method
    ran for the whole chapter.
    """
    h, w = img_gray.shape
    if h / max(w, 1) > 1.3:
        strip_panels = _detect_panels_gutter_aware(img_gray)
        if strip_panels:
            return ([(x1, y1, x2 - x1, y2 - y1) for (x1, y1, x2, y2) in strip_panels], "gutter_aware")
    panels, method = _detect_panels_auto(img_gray)
    return panels, method


def _is_blank_crop(arr_gray) -> bool:
    """Check if a cropped panel image is blank (no real content).

    A panel is considered blank if it's nearly uniform — e.g. pure white,
    pure black, or a flat color with no artwork. We use pixel standard
    deviation: a real manga/manhwa panel has lots of detail (lines, shading,
    text) so its std is high (>15). Blank panels have std < 8.

    Also catches near-white panels (mean > 245 AND std < 15) which are the
    most common blank type in webtoons (white gutters caught as "panels").
    """
    if arr_gray is None or arr_gray.size == 0:
        return True
    mean_val = float(np.mean(arr_gray))
    std_val = float(np.std(arr_gray))
    # Very low std = uniform/blank regardless of color.
    if std_val < 8.0:
        return True
    # Near-white with low detail = blank white panel.
    if mean_val > 245.0 and std_val < 15.0:
        return True
    # A pure vertical gradient (scene-transition wipe): EVERY row is nearly
    # flat across its width, and the row means march monotonically from one
    # tone to another. No lines, no art, no text — nothing to show. (A dark
    # caption box or figure breaks the "every row flat" test.)
    if arr_gray.ndim == 2 and arr_gray.shape[0] >= 24:
        row_mean = arr_gray.mean(axis=1)
        row_span = float(row_mean.max() - row_mean.min())
        row_std_max = float(arr_gray.std(axis=1).max())
        if row_std_max < 12.0 and row_span > 40.0:
            d = np.diff(row_mean)
            if np.mean(d >= -0.5) > 0.98 or np.mean(d <= 0.5) > 0.98:
                return True
    return False


def _looks_like_credits_panel(arr_rgb) -> bool:
    """A publisher / scanlation credits or translator's-note panel: a mostly
    white page carrying only rows of small text and NO artwork. Defined by
    what it lacks — colour and drawn art — so it catches the block whatever
    language the credits are in (these raw scans stamp the staff list in
    Chinese, which an English OCR head then can't even flag as text).

    Conservative on purpose: story panels in this genre are always coloured
    and/or full of linework, so the "bright + greyscale + a little ink"
    signature is specific to a text box. Used only on the first/last pages
    of a chapter, where front/back-matter lives.
    """
    if arr_rgb is None or getattr(arr_rgb, "size", 0) < 900:
        return False
    g = cv2.cvtColor(arr_rgb, cv2.COLOR_RGB2GRAY)
    bright = float((g >= 228).mean())          # page is mostly white
    ink = float((g < 110).mean())              # a little dark text
    hsv = cv2.cvtColor(arr_rgb, cv2.COLOR_RGB2HSV)
    sat = float(hsv[..., 1].mean())            # ~0 => no colour art
    edges = cv2.Canny(g, 60, 160)
    edge_frac = float((edges > 0).mean())      # art/linework => many edges
    if not (bright >= 0.72 and sat <= 12.0):
        return False
    # small greyscale credits block: a little ink, few edges
    if 0.003 <= ink <= 0.16 and edge_frac <= 0.08:
        return True
    # BOLD credits card ("Translator: … / Editor: …" in big type): more ink
    # and edges, but the ink still forms a HANDFUL of clean horizontal text
    # rows on white — no filled artwork region anywhere.
    if ink <= 0.34 and edge_frac <= 0.16:
        row_ink = (g < 110).mean(axis=1)
        inked_rows = row_ink >= 0.02
        bands, run = 0, 0
        for v in inked_rows:
            if v:
                run += 1
            else:
                if run:
                    bands += 1
                run = 0
        if run:
            bands += 1
        # a real drawn panel fills a big contiguous vertical region with ink;
        # a credits card is <= ~12 slim text bands and never densely inked
        if 1 <= bands <= 12 and float(inked_rows.mean()) <= 0.55:
            return True
    return False


def _looks_like_scanlator_card(arr_rgb) -> bool:
    """A scanlation studio credits / chapter-title card — the COLOURED kind
    that `_looks_like_credits_panel` (tuned for white translator-note pages)
    misses: a mostly flat poster-colour fill (few large uniform regions,
    little drawn linework) carrying a logo + a line or two of text. Used only
    on the first/last frame of a chapter, and only when OCR already returned
    no narratable text — so a false positive can at worst drop one silent
    boundary frame, never a narrated story panel. F3."""
    if arr_rgb is None or getattr(arr_rgb, "size", 0) < 900:
        return False
    g = cv2.cvtColor(arr_rgb, cv2.COLOR_RGB2GRAY)
    edges = cv2.Canny(g, 60, 160)
    edge_frac = float((edges > 0).mean())
    # a real drawn panel is dense with linework; a logo card is not
    if edge_frac > 0.11:
        return False
    # how much of the frame is a handful of flat colours? quantise to 3-bit/chan
    q = (arr_rgb.astype(np.uint16) >> 5)
    codes = (q[..., 0] << 6) | (q[..., 1] << 3) | q[..., 2]
    vals, counts = np.unique(codes, return_counts=True)
    counts = np.sort(counts)[::-1]
    top3 = float(counts[:3].sum()) / float(codes.size)
    return top3 >= 0.72


# Near-duplicate frame detection (webtoons reuse panels in "previously on…"
# recap strips and flashbacks — on a multi-hour recap that's real repetition).
# 512-bit combined dHash+vHash on a 16x16 grey — hashed on the TIGHT panel
# content (the *_ocr.jpg crop), not the composed canvas: the blurred backdrop
# on the canvas is low-entropy and makes unrelated frames look alike. Pure numpy.
_RECAP_SEEN_HASHES: List[int] = []


def _frame_dhash(path) -> Optional[int]:
    try:
        from PIL import Image
        p = Path(path)
        ocr = p.with_name(p.stem + "_ocr" + p.suffix)
        src = ocr if ocr.exists() else p
        a = np.asarray(Image.open(src).convert("L").resize((17, 16), Image.BILINEAR), dtype=np.int16)
        b = a[:16, :16]
        dh = (a[:16, 1:] > a[:16, :-1]).flatten()           # 256 horizontal-gradient bits
        vv = np.asarray(Image.open(src).convert("L").resize((16, 17), Image.BILINEAR), dtype=np.int16)
        dv = (vv[1:, :16] > vv[:-1, :16]).flatten()          # 256 vertical-gradient bits
        bits = 0
        for v in np.concatenate([dh, dv]):
            bits = (bits << 1) | int(v)
        return bits
    except Exception:
        return None


def _ham64(a: int, b: int) -> int:
    return bin(a ^ b).count("1")


def _is_lines_only_crop(arr_gray) -> bool:
    """Check if a cropped panel contains ONLY lines/borders (no text, no art).

    These are panels that have some content (so they pass the blank check) but
    the content is just thin lines, borders, dividers, or frame outlines — no
    actual text or artwork. These should be removed from the video because they
    add no narrative value.

    Detection method: analyze connected components of dark pixels.
    - TEXT = many small, non-elongated components (characters)
    - ART = large components with high pixel area (artwork, shading)
    - LINES = medium components that are very elongated (high aspect ratio)

    A panel is "lines only" if it has NO text-like components AND NO art-like
    components, but DOES have line-like components.

    Returns True if the panel should be REMOVED (lines/borders only).
    """
    if arr_gray is None or arr_gray.size == 0:
        return False  # let _is_blank_crop handle empty

    h, w = arr_gray.shape
    if h < 5 or w < 5:
        return False

    # Threshold to find dark pixels (content)
    _, binary = cv2.threshold(arr_gray, 180, 255, cv2.THRESH_BINARY_INV)
    n_labels, labels, stats, _ = cv2.connectedComponentsWithStats(binary, connectivity=8)

    if n_labels <= 1:
        return False  # no content at all (blank check handles this)

    text_components = 0
    art_components = 0
    line_components = 0

    for i in range(1, n_labels):
        area = int(stats[i, cv2.CC_STAT_AREA])
        cw = int(stats[i, cv2.CC_STAT_WIDTH])
        ch = int(stats[i, cv2.CC_STAT_HEIGHT])
        min_dim = max(1, min(cw, ch))
        max_dim = max(cw, ch)
        aspect = max_dim / min_dim

        # Skip tiny noise (< 5px)
        if area < 5:
            continue

        # TEXT-like: small area, low aspect ratio (roughly square = characters)
        # Characters are typically 5-500px and aspect < 3.5
        if area < 600 and aspect < 3.5:
            text_components += 1
        # ART-like: large area (big artwork blobs, shading regions)
        elif area > 1500:
            art_components += 1
        # LINE-like: very elongated (aspect > 4) — borders, dividers, frame outlines
        elif aspect > 4.0:
            line_components += 1
        else:
            # Medium, non-elongated — could be text or small art, count as text
            if area < 600:
                text_components += 1

    # The panel is "lines only" if it has line-like components but
    # NO text and NO art. We require at least 1 line component to classify
    # as lines-only (otherwise it's just a sparse panel).
    has_text = text_components >= 8  # need at least 8 char-like blobs for real text
    has_art = art_components >= 1
    has_lines = line_components >= 1

    return has_lines and not has_text and not has_art


def _is_featureless_vfx(arr_gray) -> bool:
    """Check if a panel slice candidate is a featureless background, visual effect,
    gradient, speed line, ice shard, or light aura region lacking character faces,
    dialogue bubbles, or structural story focal points.

    Detection criteria:
    - Structural contour density (Canny edges)
    - Presence of text glyphs (small bounded edge components) or distinct story focal points
    """
    if arr_gray is None or arr_gray.size == 0:
        return True

    h, w = arr_gray.shape
    if h < 20 or w < 20:
        return True

    edges = cv2.Canny(arr_gray, 50, 150)
    edge_density = float(np.count_nonzero(edges)) / float(arr_gray.size)

    # Analyze connected components of Canny edge contours
    n_labels, labels, stats, _ = cv2.connectedComponentsWithStats(edges, connectivity=8)

    text_components = 0
    substantive_contours = 0

    for i in range(1, n_labels):
        area = int(stats[i, cv2.CC_STAT_AREA])
        cw = int(stats[i, cv2.CC_STAT_WIDTH])
        ch = int(stats[i, cv2.CC_STAT_HEIGHT])

        if area < 10:
            continue
        # Text characters in edge domain are small bounded glyph components (e.g. 5 <= cw, ch <= 60)
        if 5 <= cw <= 60 and 5 <= ch <= 60 and area >= 15:
            text_components += 1
        elif area > 800 and (cw > 80 or ch > 80):
            substantive_contours += 1

    # Featureless visual effects (ice shards, speed lines, light aura) have < 4 text glyphs and low substantive contours
    if text_components < 4 and substantive_contours == 0:
        return True
    if text_components < 4 and edge_density < 0.02:
        return True

    return False


def _crops_are_near_duplicate(arr_gray_a, arr_gray_b, corr_thresh: float = 0.985) -> bool:
    """Cheap perceptual check for whether two panel crops are near-identical.

    Catches a single panel that a gutter cut has spuriously sliced into two
    (or more) near-duplicate pieces — e.g. a bright VFX/light-aura band
    inside one continuous panel getting misread as an inter-panel gutter —
    which otherwise ships as two adjacent frames showing what looks like
    the same panel twice, each padded out to MIN_FRAME_DURATION regardless
    of how little unique content (or narration) it actually has.

    Downsamples both crops to a small fixed size and compares via
    normalized cross-correlation, which is robust to the crops' differing
    source dimensions and tolerant of the minor rescale artifacts that
    fixed-size downsampling introduces.
    """
    if arr_gray_a is None or arr_gray_b is None or arr_gray_a.size == 0 or arr_gray_b.size == 0:
        return False
    small_a = cv2.resize(arr_gray_a, (32, 32), interpolation=cv2.INTER_AREA).astype(np.float32)
    small_b = cv2.resize(arr_gray_b, (32, 32), interpolation=cv2.INTER_AREA).astype(np.float32)
    a = small_a - small_a.mean()
    b = small_b - small_b.mean()
    denom = float(np.sqrt((a * a).sum()) * np.sqrt((b * b).sum()))
    if denom < 1e-6:
        # Both crops are essentially flat/uniform — treat as duplicate only
        # if they're also close in brightness (two different flat colors,
        # e.g. one white gutter fragment and one black panel, are not the
        # same content).
        return bool(abs(float(small_a.mean()) - float(small_b.mean())) < 3.0)
    corr = float((a * b).sum() / denom)
    return corr >= corr_thresh


def _clean_panel_boundary_edges(arr_rgb, arr_gray, max_scan_px: int = 15):
    """Clean panel boundary edge fragments (dual-panel overlap bug fix).

    Enhances horizontal gutter detection by looking for continuous black/white pixel rows
    or distinct edge color transitions between adjacent panels. Trims stray top/bottom edge fragments
    from adjacent panels (such as fire panel top bleed) before finalizing slice output.
    """
    h, w = arr_gray.shape
    if h < 30 or w < 30:
        return arr_rgb, arr_gray

    # Scan top rows for stray edge fragments from previous panel
    top_trim = 0
    for y in range(min(max_scan_px, h // 4)):
        row = arr_gray[y, :]
        mean_v = float(np.mean(row))
        # Continuous black border row (<10) or white gutter row (>245)
        if mean_v > 245 or mean_v < 10:
            top_trim = y + 1
        else:
            break

    # Scan bottom rows for stray edge fragments from next panel
    bot_trim = h
    for y in range(h - 1, max(h - max_scan_px - 1, h - h // 4), -1):
        row = arr_gray[y, :]
        mean_v = float(np.mean(row))
        if mean_v > 245 or mean_v < 10:
            bot_trim = y
        else:
            break

    if top_trim > 0 or bot_trim < h:
        if (bot_trim - top_trim) >= 20:
            arr_rgb = arr_rgb[top_trim:bot_trim, :]
            arr_gray = arr_gray[top_trim:bot_trim, :]

    return arr_rgb, arr_gray


def _detect_panels_yolo(img_gray) -> List[tuple]:
    """Detect panels using YOLOv5/v8 comic panel detection model.

    Uses a pretrained YOLO model (mosesb/best-comic-panel-detection) that
    was trained specifically on comic/manga panels. This is more accurate
    than CV-based detection for pages with complex layouts, splash panels,
    and non-rectangular panel shapes.

    Falls back gracefully if the model or torch is unavailable.

    Returns list of (x, y, w, h) tuples sorted by y position.
    """
    try:
        _cap_torch_threads()
        from ultralytics import YOLO
    except ImportError:
        return []

    model_path = str(Path(__file__).parent / "models" / "comic-panel-yolo" / "best.pt")
    if not Path(model_path).exists():
        log.info("Comic panel YOLO model not found at %s — falling back to CV/contour detection", model_path)
        return []

    try:
        model = YOLO(model_path)
        # Convert grayscale to 3-channel for YOLO (it expects BGR)
        if img_gray.ndim == 2:
            img_bgr = cv2.cvtColor(img_gray, cv2.COLOR_GRAY2BGR)
        else:
            img_bgr = img_gray

        results = model.predict(img_bgr, conf=0.25, iou=0.45, verbose=False)
        if not results or results[0].boxes is None:
            return []

        h, w = img_gray.shape[:2]
        page_area = w * h
        panels = []
        for box in results[0].boxes:
            x1, y1, x2, y2 = box.xyxy[0].cpu().numpy()
            x1, y1, x2, y2 = int(x1), int(y1), int(x2), int(y2)
            bw, bh = x2 - x1, y2 - y1
            area = bw * bh
            # Filter: min 2% area, max 98% area (looser than CV)
            if area < 0.02 * page_area or area > 0.98 * page_area:
                continue
            # Expand by 10px margin to avoid tight crops that clip artwork
            margin = 10
            x1 = max(0, x1 - margin)
            y1 = max(0, y1 - margin)
            bw = min(w - x1, bw + 2 * margin)
            bh = min(h - y1, bh + 2 * margin)
            panels.append((x1, y1, bw, bh))

        # NMS to remove near-duplicates (keep insets)
        panels = _suppress_nested(panels, iou_thresh=0.65)
        panels = _order_panels_reading_order(panels)
        return panels
    except Exception as e:
        log.warning("YOLO panel detection failed: %s", e)
        return []


def _order_panels_reading_order(panels: List[tuple]) -> List[tuple]:
    """Order panel boxes (x, y, w, h) into natural top-to-bottom,
    left-to-right reading order for LTR-read manhwa/comic grid pages.

    A naive sort purely by top-y coordinate (p[1], p[0]) breaks whenever
    panels in the same visual row are staggered or have different heights
    — extremely common in dynamic comic layouts with diagonal panel cuts
    or a tall splash panel next to two stacked smaller ones. That naive
    sort can place a panel from the NEXT row before the second panel of
    the CURRENT row, silently narrating story events out of order. This
    clusters panels into rows by vertical overlap first, then sorts each
    row left-to-right, before ordering rows top-to-bottom.
    """
    if not panels:
        return panels

    remaining = sorted(panels, key=lambda p: p[1])
    rows: List[List[tuple]] = []
    for p in remaining:
        x, y, w, h = p
        y2 = y + h
        placed = False
        for row in rows:
            ry1 = min(rp[1] for rp in row)
            ry2 = max(rp[1] + rp[3] for rp in row)
            overlap = min(y2, ry2) - max(y, ry1)
            min_h = min(h, ry2 - ry1)
            if min_h > 0 and overlap / min_h > 0.4:
                row.append(p)
                placed = True
                break
        if not placed:
            rows.append([p])

    rows.sort(key=lambda row: min(rp[1] for rp in row))
    ordered: List[tuple] = []
    for row in rows:
        row.sort(key=lambda rp: rp[0])
        ordered.extend(row)
    return ordered


def _detect_panels_auto(img_gray) -> tuple:
    """Auto-mode panel detection: run YOLO first, fall back to CV if weak.

    This is the cbxy "auto" engine approach:
    1. Run YOLO (most accurate for complex layouts)
    2. If YOLO returns 0 panels or 1 panel covering ≥70% of page (weak),
       run CV detection and use whichever produced more panels.
    3. If CV also looks weak, use the whole page as one panel.

    Returns (panels, method_name): panels is a list of (x, y, w, h) tuples;
    method_name is "yolo", "contour", or "whole_page" — whichever actually
    produced the returned panels.
    """
    h, w = img_gray.shape
    page_area = w * h

    # Try YOLO first
    yolo_panels = _detect_panels_yolo(img_gray)

    # Check if YOLO looks weak
    yolo_weak = (
        len(yolo_panels) == 0
        or (len(yolo_panels) == 1 and yolo_panels[0][2] * yolo_panels[0][3] >= 0.70 * page_area)
    )

    if not yolo_weak and len(yolo_panels) >= 2:
        # YOLO found multiple panels — use it
        log.debug("YOLO detected %d panels (strong)", len(yolo_panels))
        return yolo_panels, "yolo"

    # YOLO was weak — try CV
    cv_panels = _detect_panels_contour(img_gray)

    # Use whichever found more panels
    if len(cv_panels) > len(yolo_panels):
        log.debug("CV fallback: %d panels (YOLO found %d)", len(cv_panels), len(yolo_panels))
        return cv_panels, "contour"

    # Both weak — use whole page
    if not yolo_panels and not cv_panels:
        return [(0, 0, w, h)], "whole_page"

    if yolo_panels:
        return yolo_panels, "yolo"
    return cv_panels, "contour"


def _suppress_nested(panels: List[tuple], iou_thresh: float = 0.55) -> List[tuple]:
    """Drop boxes mostly contained in a larger panel (from cbxy).

    Greedy by descending area: a candidate is dropped if >=55% of its
    own area is contained in an already-kept larger panel. This removes
    speech bubbles and small insets that survived the area filter.
    """
    if not panels:
        return panels

    kept: List[tuple] = []
    by_area = sorted(panels, key=lambda p: p[2] * p[3], reverse=True)
    for candidate in by_area:
        cx, cy, cw, ch = candidate
        cx2, cy2 = cx + cw, cy + ch
        is_nested = False
        for kept_panel in kept:
            kx, ky, kw, kh = kept_panel
            kx2, ky2 = kx + kw, ky + kh
            # Compute containment: fraction of candidate inside kept_panel
            ix1 = max(cx, kx)
            iy1 = max(cy, ky)
            ix2 = min(cx2, kx2)
            iy2 = min(cy2, ky2)
            if ix2 <= ix1 or iy2 <= iy1:
                continue
            inter = (ix2 - ix1) * (iy2 - iy1)
            candidate_area = max(cw * ch, 1)
            if inter / candidate_area >= iou_thresh:
                is_nested = True
                break
        if not is_nested:
            kept.append(candidate)
    return kept


THIN_STRIP_MAX_HEIGHT_FRAC = 0.10  # a detected box shorter than this fraction of the
# page height AND much wider than it is tall is almost always a detached
# caption/onomatopoeia strip, not a real panel. On its own it renders as a
# near-empty blur-fill frame (a sliver of text blown up to fill 1080p) and
# still eats a MIN_FRAME_DURATION slot in the timeline.
THIN_STRIP_MIN_ASPECT = 4.0


def _consolidate_panel_boxes(boxes: List[tuple], page_w: int, page_h: int,
                             max_boxes: int) -> List[tuple]:
    """Post-process the per-page merged panel boxes before canvas composition.

    Two problems this fixes, both seen in real jobs:
      1. Detached thin text strips (a caption or a "BOOM"/"POW" sound-effect
         band that the detector split off from its panel) get emitted as
         standalone frames — each one is a sliver of text upscaled onto a
         1920x1080 blur-fill canvas, and each one still occupies a full
         narrated-frame time slot. Merge every such strip into the panel it
         is vertically adjacent to (previous if any, else next).
      2. Over-segmentation: a busy page detected as many small panels turns
         one source page into 6-10 frames, and the
         `len(frames) * MIN_FRAME_DURATION` audio floor then pads a short
         caption out to 15-25s of mostly-silent video. Enforce
         MAX_FRAMES_PER_PANEL (previously a defined-but-unused constant) by
         repeatedly merging the vertically-adjacent pair with the smallest
         combined area until the page is within budget.

    Boxes are assumed to already be in reading order (top-to-bottom for the
    single-column webtoon strips this pipeline targets). Returns a new list
    of (x, y, w, h) boxes, order preserved.
    """
    if not boxes:
        return boxes

    def _union(a, b):
        ax, ay, aw, ah = a
        bx, by, bw, bh = b
        x1, y1 = min(ax, bx), min(ay, by)
        x2, y2 = max(ax + aw, bx + bw), max(ay + ah, by + bh)
        return (x1, y1, x2 - x1, y2 - y1)

    work = list(boxes)

    # Pass 1: fold thin strips into a neighbour.
    consolidated: List[tuple] = []
    for box in work:
        _, _, bw, bh = box
        is_thin_strip = (
            bh < page_h * THIN_STRIP_MAX_HEIGHT_FRAC
            and bw >= bh * THIN_STRIP_MIN_ASPECT
        )
        if is_thin_strip and consolidated:
            consolidated[-1] = _union(consolidated[-1], box)
        elif is_thin_strip:
            consolidated.append(box)  # first box; may be merged forward below
        else:
            if consolidated:
                _, _, pw, ph = consolidated[-1]
                if ph < page_h * THIN_STRIP_MAX_HEIGHT_FRAC and pw >= ph * THIN_STRIP_MIN_ASPECT:
                    # previous kept box was itself an unmergeable leading strip
                    consolidated[-1] = _union(consolidated[-1], box)
                    continue
            consolidated.append(box)

    # Pass 2: enforce the per-page frame budget by merging adjacent pairs.
    while len(consolidated) > max_boxes:
        best_i, best_area = 0, None
        for i in range(len(consolidated) - 1):
            merged = _union(consolidated[i], consolidated[i + 1])
            area = merged[2] * merged[3]
            if best_area is None or area < best_area:
                best_area, best_i = area, i
        consolidated[best_i] = _union(consolidated[best_i], consolidated[best_i + 1])
        del consolidated[best_i + 1]

    return consolidated


def _detect_panels_contour(img_gray) -> List[tuple]:
    """Detect panels using improved contour-based detection (CV fallback).

    This is the CV fallback used when YOLO is unavailable or returns weak
    results. Combines techniques from comic-manga-narrator + cbxy.
    """
    h, w = img_gray.shape
    page_area = w * h

    # Step 1: threshold (gutters are white ≥200, panels are dark <200)
    _, binary = cv2.threshold(img_gray, 200, 255, cv2.THRESH_BINARY)

    # Step 2: morphological close to bridge text/art gaps within panels
    # Invert so panels are white blobs on black background
    panels_mask = cv2.bitwise_not(binary)
    kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (5, 5))
    panels_mask = cv2.morphologyEx(panels_mask, cv2.MORPH_CLOSE, kernel, iterations=2)

    # Step 3: flood-fill from 4 corners to mark page background (cbxy technique)
    # This prevents the entire page from being detected as one giant panel
    gutters = binary.copy()
    ff_mask = np.zeros((h + 2, w + 2), np.uint8)
    for seed in [(0, 0), (w - 1, 0), (0, h - 1), (w - 1, h - 1)]:
        if gutters[seed[1], seed[0]] > 0:
            cv2.floodFill(gutters, ff_mask, seed, 128)

    # Step 4: subtract background
    background = gutters == 128
    content = panels_mask.copy()
    content[background] = 0

    # Step 5: find external contours
    contours, _ = cv2.findContours(content, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

    # Step 6-7: filter by area, dimensions, and aspect ratio
    panels = []
    for cnt in contours:
        area = cv2.contourArea(cnt)
        if area < 0.03 * page_area or area > 0.85 * page_area:
            continue
        x, y, bw, bh = cv2.boundingRect(cnt)
        # Reject thin slivers (cbxy thresholds)
        if bw < 0.08 * w or bh < 0.05 * h:
            continue
        ar = bw / max(bh, 1)
        if ar > 8.0 or ar < 0.15:
            continue
        # Small margin expansion
        margin = 5
        x = max(0, x - margin)
        y = max(0, y - margin)
        bw = min(w - x, bw + 2 * margin)
        bh = min(h - y, bh + 2 * margin)
        panels.append((x, y, bw, bh))

    # Step 8: nested suppression (cbxy technique)
    panels = _suppress_nested(panels, iou_thresh=0.55)

    # Step 9: weak detection fallback (cbxy heuristic)
    # If 0 panels or 1 panel covering ≥70% of page, use whole page
    if not panels:
        return [(0, 0, w, h)]
    if len(panels) == 1 and panels[0][2] * panels[0][3] >= 0.70 * page_area:
        return [(0, 0, w, h)]

    # Sort into natural reading order: rows by vertical overlap (handles
    # staggered/diagonal layouts), then left-to-right within each row.
    panels = _order_panels_reading_order(panels)
    return panels


# ---------------------------------------------------------------------------
# Reference-style page framing (default). The recap videos this pipeline
# targets (e.g. the "Asura Chronicles" style) do NOT chop each page into
# individual bubble-sized panels — that produces frames that are just a
# strip of text blown up over a blur. Instead each on-screen view is a
# whole comic panel (or a short vertical run of panels) with its speech
# bubbles intact, contain-fit onto the canvas over a blurred copy of
# itself. This mode reproduces that: one frame per source page, splitting
# small, and always cutting on a gutter row so a bubble is never sliced.
# Set RECAP_FRAME_MODE=panel to fall back to the old per-panel slicer.
PANEL_MIN_AREA_FRAC = 0.010   # a component smaller than this fraction of the
                              # page is a stray mark / floating SFX, not a panel
PANEL_BUBBLE_AREA_FRAC = 0.045  # a component below this AND with a bright (white)
                              # interior is a speech bubble that overflowed its
                              # panel's border — reattach it to the nearest panel


def _get_panel_yolo():
    global _panel_yolo_session, _panel_yolo_load_attempted
    if _panel_yolo_load_attempted:
        return _panel_yolo_session
    _panel_yolo_load_attempted = True
    if not PANEL_YOLO_PATH.exists():
        log.info("Manga panel YOLO not found at %s — using flood-fill panel detection", PANEL_YOLO_PATH)
        return None
    try:
        _panel_yolo_session = _ort_session(PANEL_YOLO_PATH, "panel-yolo")
        log.info("Loaded manga panel detector (YOLO26n) from %s", PANEL_YOLO_PATH)
    except Exception as e:  # pragma: no cover
        log.warning("panel YOLO load failed (%s) — using flood-fill fallback", e)
        _panel_yolo_session = None
    return _panel_yolo_session


def _yolo_detect_page(img_rgb, panel_conf: float = 0.20, text_conf: float = 0.25):
    """Run the Manga109-trained YOLO on a page. Returns (panels, texts) as
    lists of (x1, y1, x2, y2, score) in the page's own pixels, or (None, None)
    if the model isn't available."""
    sess = _get_panel_yolo()
    if sess is None:
        return None, None
    from PIL import Image
    W, H = img_rgb.size
    S = PANEL_YOLO_INPUT
    scale = min(S / W, S / H)
    nw, nh = int(round(W * scale)), int(round(H * scale))
    ox, oy = (S - nw) // 2, (S - nh) // 2
    canvas = Image.new("RGB", (S, S), (114, 114, 114))
    canvas.paste(img_rgb.resize((nw, nh), Image.BILINEAR), (ox, oy))
    x = np.asarray(canvas, dtype=np.float32).transpose(2, 0, 1)[None] / 255.0
    try:
        out = sess.run(None, {sess.get_inputs()[0].name: x})[0][0]  # (N, 6)
    except Exception as e:  # pragma: no cover
        log.warning("panel YOLO inference failed (%s)", e)
        return None, None
    panels, texts = [], []
    for row in out:
        x1, y1, x2, y2, sc, cl = float(row[0]), float(row[1]), float(row[2]), float(row[3]), float(row[4]), int(round(row[5]))
        bx1 = max(0.0, (x1 - ox) / scale); by1 = max(0.0, (y1 - oy) / scale)
        bx2 = min(float(W), (x2 - ox) / scale); by2 = min(float(H), (y2 - oy) / scale)
        if bx2 - bx1 < 4 or by2 - by1 < 4:
            continue
        if cl == 0 and sc >= panel_conf:
            panels.append((bx1, by1, bx2, by2, sc))
        elif cl == 1 and sc >= text_conf:
            texts.append((bx1, by1, bx2, by2, sc))
    return panels, texts


def _split_borderless_column(box, gray, texts) -> "List[list]":
    """Split one tall panel box into the individual webtoon beats stacked
    inside it.

    Borderless webtoon hosts serve a chapter as fixed-height chunk images and
    every panel is full-width with a generous light (occasionally flat-black)
    gutter between them; the border-trained YOLO detector collapses a whole
    column of stacked panels into one giant box. This finds those internal
    gutters — full-width bands of near-uniform page background — cuts there,
    trims each sub-panel to its OWN content (so half a blank gutter never
    rides along as dead space), and folds only genuinely tiny caption strips
    into a neighbour. A lone speech bubble is fused with the panel it
    introduces ONLY when it sits right against it — a bubble separated from
    every panel by a wide blank gap is kept as its own beat instead of
    dragging a far-away panel up into one long strip.

    A box not much taller than it is wide, or with no clean internal gutter,
    is returned unchanged. A gutter a YOLO text box straddles is never cut.
    """
    x1, y1, x2, y2 = (int(v) for v in box)
    W = max(1, x2 - x1)
    H = y2 - y1
    if H <= 1.35 * W or H < 320:
        return [list(box)]
    col = gray[max(0, y1):y2, max(0, x1):x2]
    if col.size == 0 or col.shape[0] < 120:
        return [list(box)]
    ci = col.astype(np.int16)
    Hc = col.shape[0]

    # "text on black" dramatic column vs normal light page — the gutter (and
    # the definition of 'ink') is inverted between the two.
    dark_page = float((col <= 40).mean()) > 0.45

    row_std = col.std(axis=1)
    dark_frac = (col <= 26).mean(axis=1)
    if dark_page:
        bg = 0.0
        # gutter row: a near-uniform full-width near-black band
        quiet = (dark_frac >= 0.90) & (row_std <= 20)
    else:
        # Robust page-background tone — median of the brightest ~30% of
        # pixels. Works for pure white, cream scanlations and grey paper
        # alike (the old fixed ">= 232" test silently failed on every
        # slightly-off-white source).
        flat = ci.ravel()
        bright_vals = flat[flat >= np.percentile(flat, 70)]
        bg = float(np.median(bright_vals)) if bright_vals.size else 245.0
        near_bg = (np.abs(ci - bg) <= 16).mean(axis=1)
        # a genuine inter-panel gutter is a clean full-width background band.
        # bg-tone (above) is what makes this robust on off-white sources; the
        # fraction stays fairly tight so a bright sky / white shirt inside a
        # panel doesn't read as a cut.
        quiet = ((near_bg >= 0.945) & (row_std <= 18)) | ((dark_frac >= 0.955) & (row_std <= 15))

    def _ink_rows(sub):
        """boolean per-row: does this row carry drawn content?"""
        si = sub.astype(np.int16)
        if dark_page:
            return (si > 55).mean(axis=1) > 0.010
        r = (np.abs(si - bg) > 22).mean(axis=1) > 0.010
        if r.sum() < 8:
            r = (si <= max(30.0, bg - 45)).mean(axis=1) > 0.05
        return r

    bands, i, n = [], 0, len(quiet)
    while i < n:
        if not quiet[i]:
            i += 1
            continue
        j = i
        while j < n and quiet[j]:
            j += 1
        if j - i >= 26:          # a real inter-panel gap is a generous band
            bands.append([i, j])
        i = j
    if not bands:
        return [list(box)]

    def _text_straddles(row_y):
        for (tx1, ty1, tx2, ty2, _s) in (texts or []):
            if ty1 < row_y - 3 and ty2 > row_y + 3 and min(tx2, x2) - max(tx1, x1) > 0.2 * W:
                return True
        return False

    def _clear_subrun(a, b):
        """Largest sub-range of column-local band [a, b] that NO wide text box
        overlaps — the true gutter once a caption floating in the blank space
        is carved out. Returns None only when a box spans the whole band (a
        bubble taller than the gap — never cut there). Without this, a single
        narration caption dropped into an otherwise-clean 400px gutter made
        the band's midpoint 'straddle text', so the WHOLE band was discarded
        and three stacked beats stayed glued into one 16-second frame."""
        span = max(1, b - a)
        blocked = np.zeros(span, dtype=bool)
        for (tx1, ty1, tx2, ty2, _s) in (texts or []):
            if min(tx2, x2) - max(tx1, x1) <= 0.2 * W:
                continue
            u = max(a, int(ty1) - y1 - 4)
            v = min(b, int(ty2) - y1 + 4)
            if v > u:
                blocked[u - a:v - a] = True
        if blocked.all():
            return None
        best, i = (0, 0), 0
        while i < span:
            if blocked[i]:
                i += 1
                continue
            j = i
            while j < span and not blocked[j]:
                j += 1
            if j - i > best[1] - best[0]:
                best = (i, j)
            i = j
        return (a + best[0], a + best[1])

    # Content segments live BETWEEN the gutter bands. A fat gutter (>= 60px)
    # is dropped whole (its blank rows belong to no beat) — but only the part
    # of it clear of any floating caption; a thin one is split at its midpoint.
    spans, prev = [], 0
    for (a, b) in bands:
        if b - a >= 60 and _GUTTER_CARVE:
            cr = _clear_subrun(a, b)
            if cr is None:
                continue
            lo, hi = cr
        elif b - a >= 60:
            lo, hi = a, b
            if _text_straddles(y1 + (a + b) // 2):
                continue
        else:
            mid = (a + b) // 2
            if _text_straddles(y1 + mid):
                continue
            lo = hi = mid
        if lo <= prev:
            continue
        spans.append((prev, lo))
        prev = hi
    spans.append((prev, Hc))

    # text/bubble boxes overlapping this column, in column-local y (ints)
    col_texts = []
    for (tx1, ty1, tx2, ty2, _s) in (texts or []):
        if min(tx2, x2) - max(tx1, x1) > 0.12 * W:
            col_texts.append((int(ty1) - y1, int(ty2) - y1))

    def _snap_out_to_text(t0, t1):
        """grow [t0,t1] so it never bisects a speech bubble the detector saw."""
        for (a, b) in col_texts:
            if b <= t0 or a >= t1:
                continue                       # text box entirely outside — fine
            if a < t0:
                t0 = int(a) - 4
            if b > t1:
                t1 = int(b) + 4
        return int(t0), int(t1)

    def _trim_span(lo, hi):
        sub = ci[lo:hi]
        if sub.shape[0] < 8:
            return None
        rr = np.where(_ink_rows(sub))[0]
        if rr.size < 8:
            return None
        # generous padding so a bubble's faint rounded top/bottom isn't shaved
        t0 = int(rr[0]) - 12
        t1 = int(rr[-1]) + 13
        t0, t1 = _snap_out_to_text(lo + t0, lo + t1)
        t0 = max(0, t0)
        t1 = min(Hc, t1)
        return [x1, y1 + t0, x2, y1 + t1]

    segs = [s for s in (_trim_span(lo, hi) for (lo, hi) in spans) if s is not None]
    if len(segs) <= 1:
        return [list(box)]
    # de-overlap: two segments the text-snap pushed into each other are one beat
    segs.sort(key=lambda s: s[1])
    merged = [segs[0]]
    for s in segs[1:]:
        if s[1] < merged[-1][3] - 6:
            merged[-1][3] = max(merged[-1][3], s[3])
        else:
            merged.append(s)
    segs = merged
    if len(segs) <= 1:
        return [list(box)]

    def _is_thin_strip(s):
        h = s[3] - s[1]
        return h < 0.42 * W and h < 360

    def _is_lone_bubble(s):
        sg = gray[max(0, s[1]):s[3], max(0, s[0]):s[2]].astype(np.int16)
        if sg.size == 0:
            return False
        h, w = sg.shape
        if h > 0.62 * W or h > 470:         # a tall segment is never "just a bubble"
            return False
        ink = np.abs(sg - bg) > 40
        rr = np.where(ink.mean(axis=1) > 0.02)[0]
        cc = np.where(ink.mean(axis=0) > 0.02)[0]
        if rr.size == 0 or cc.size == 0:
            return False
        span_v = (rr[-1] - rr[0]) / max(1, h)
        cx = (cc[0] + cc[-1]) / 2.0 / max(1, w)
        fill = float(ink[rr[0]:rr[-1] + 1, cc[0]:cc[-1] + 1].mean())
        # ink confined to a compact, roughly-centred block = a speech balloon
        return span_v <= 0.9 and 0.18 <= cx <= 0.82 and fill >= 0.10

    def _ink_area(s):
        sg = gray[max(0, s[1]):s[3], max(0, s[0]):s[2]].astype(np.int16)
        if sg.size == 0:
            return 0.0
        return float((np.abs(sg - bg) > 40).mean()) if not dark_page else float((sg > 55).mean())

    # A short sub-panel (a caption strip, a lone bubble, a sliver of art) reads
    # better fused with the panel it sits next to than held as its own beat —
    # UNLESS it carries real text and is a long way from any panel (then it is
    # a deliberate standalone caption). This is the same "fuse downward"
    # behaviour as before the rewrite; the bg-tone fix above is what stopped
    # the giant slivers, not aggressive splitting.
    def _fold_pass(segs):
        changed = True
        while changed and len(segs) > 1:
            changed = False
            for k, s in enumerate(segs):
                if not (_is_thin_strip(s) or _is_lone_bubble(s)):
                    continue
                cand = []
                if k + 1 < len(segs):
                    cand.append((k + 1, segs[k + 1][1] - s[3]))
                if k - 1 >= 0:
                    cand.append((k - 1, s[1] - segs[k - 1][3]))
                if not cand:
                    continue
                j, gap = min(cand, key=lambda t: t[1])
                if gap > 1.0 * W:
                    # far from anything: keep only a real caption block, else
                    # it's scan noise / a stray mark — drop it
                    if _ink_area(s) < 0.045:
                        del segs[k]
                        changed = True
                        break
                    continue
                lo, hi = min(k, j), max(k, j)
                segs[lo] = [x1, min(segs[lo][1], segs[hi][1]), x2, max(segs[lo][3], segs[hi][3])]
                del segs[hi]
                changed = True
                break
        # any segment still shorter than ~0.42x width folds into its nearest
        # neighbour (no beat is worth a thin strip)
        changed = True
        while changed and len(segs) > 1:
            changed = False
            segs.sort(key=lambda s: s[1])
            for k, s in enumerate(segs):
                if (s[3] - s[1]) >= 0.42 * W:
                    continue
                j = k + 1 if k == 0 else (k - 1 if k == len(segs) - 1 else
                                          (k - 1 if (s[1] - segs[k - 1][3]) <= (segs[k + 1][1] - s[3]) else k + 1))
                lo, hi = min(k, j), max(k, j)
                segs[lo] = [x1, min(segs[lo][1], segs[hi][1]), x2, max(segs[lo][3], segs[hi][3])]
                del segs[hi]
                changed = True
                break
        return segs

    segs = _fold_pass(segs)

    # Text-cluster pass: a tall segment with no clean gutter but two or more
    # vertically-separated blocks of dialogue (a webtoon "conversation" page —
    # bubbles scattered over one continuous background) is really that many
    # beats. Cut in the clear gap BETWEEN bubble clusters (never through one).
    # This is what stops a whole page of dialogue landing on one 16-second
    # static frame.
    col_tb = sorted(((a, b) for (a, b) in ((int(t[1]) - y1, int(t[3]) - y1)
                     for t in (texts or []) if min(t[2], x2) - max(t[0], x1) > 0.12 * W)
                     if 0 <= a < Hc and 0 < b <= Hc + 40), key=lambda p: p[0])
    if col_tb and len(segs) < 40:
        clustered: "List[list]" = []
        for s in segs:
            sh = s[3] - s[1]
            # a compact single panel (roughly square or wider) is one beat even
            # with two bubbles; only look to split something meaningfully tall.
            if sh <= 1.15 * W:
                clustered.append(s)
                continue
            local = [(a, b) for (a, b) in col_tb if a >= s[1] - y1 - 8 and b <= s[3] - y1 + 8]
            if len(local) < 2:
                clustered.append(s)
                continue
            # group boxes into clusters (a clear vertical gap between them)
            groups = [[local[0]]]
            for (a, b) in local[1:]:
                if a - groups[-1][-1][1] > max(38, 0.09 * W):
                    groups.append([(a, b)])
                else:
                    groups[-1].append((a, b))
            if len(groups) < 2:
                clustered.append(s)
                continue
            cuts = [s[1]]
            for g0, g1 in zip(groups, groups[1:]):
                gap_lo = y1 + max(gg[1] for gg in g0)
                gap_hi = y1 + min(gg[0] for gg in g1)
                # the gap must be genuinely clear of any text box (not just of
                # THESE two groups' boxes) before we cut in it
                if (gap_hi - gap_lo >= 28
                        and not any(tb_a < gap_hi - 4 and tb_b > gap_lo + 4 for (tb_a, tb_b) in col_tb)):
                    cuts.append((gap_lo + gap_hi) // 2)
            cuts.append(s[3])
            cuts = sorted(set(cuts))
            if len(cuts) > 2:
                for c0, c1 in zip(cuts, cuts[1:]):
                    if c1 - c0 >= 28:
                        # trim each sub-beat to its own content so the fold
                        # pass below can recognise a caption-only slice
                        t = _trim_span(int(c0) - y1, int(c1) - y1)
                        clustered.append(t if t is not None else [s[0], c0, s[2], c1])
            else:
                clustered.append(s)
        segs = _fold_pass(clustered)   # fuse any caption-only slice into its panel

    # Second pass: a segment still MUCH taller than wide probably holds two
    # beats the uniform-gutter test was too strict to see. Cut it once at its
    # widest internal low-ink band — but only when that band is unambiguous
    # (real content well clear on both sides, no text across it).
    out: "List[list]" = []
    for s in segs:
        sh, sw = s[3] - s[1], s[2] - s[0]
        if sh <= 2.8 * sw or sh < 240:
            out.append(s)
            continue
        sub = gray[max(0, s[1]):s[3], max(0, s[0]):s[2]]
        ink = _ink_rows(sub)
        low = ~ink
        m0, m1 = int(0.12 * sub.shape[0]), int(0.88 * sub.shape[0])
        best, i = None, m0
        while i < m1:
            if low[i]:
                j = i
                while j < m1 and low[j]:
                    j += 1
                if best is None or (j - i) > (best[1] - best[0]):
                    best = (i, j)
                i = j
            else:
                i += 1
        # only accept the cut when real content sits on BOTH sides of the gap
        if (best and (best[1] - best[0]) >= 16
                and ink[:best[0]].sum() >= 12 and ink[best[1]:].sum() >= 12
                and not _text_straddles(s[1] + (best[0] + best[1]) // 2)):
            mid = s[1] + (best[0] + best[1]) // 2
            out.append([s[0], s[1], s[2], mid])
            out.append([s[0], mid, s[2], s[3]])
        else:
            out.append(s)
    return out


def _detect_page_panels(img_rgb) -> "List[tuple]":
    """Detect the comic panels on a page, in reading order, as (x1,y1,x2,y2).

    Primary: a YOLO26-nano panel+text detector fine-tuned on Manga109-s
    (see PANEL_YOLO_PATH). Each detected text box is attached to the panel it
    overlaps most (nearest if it overlaps none), and the emitted panel region
    is the union of the panel box with its text boxes — so a speech bubble
    that overflows the panel border into the gutter is still fully inside the
    frame. Panels are ordered by recursive XY-cut (top-to-bottom, and left
    bubble/panel first for side-by-side layouts). Every panel is kept as its
    own frame — no merging.

    Fallback (model file absent / inference fails): white-background flood
    fill + connected components.
    """
    W, H = img_rgb.size

    panels_y, texts_y = _yolo_detect_page(img_rgb)
    if panels_y is not None and (panels_y or texts_y):
        pg_area = float(W * H)
        # Enrich the text boxes with the RT-DETR comic text/bubble detector
        # (webtoon-trained, far better recall than the Manga109 YOLO's text
        # class). These drive every "never cut through a bubble" guard
        # downstream (_split_borderless_column, the contiguity merge's
        # _text_bridges, the seam stitch) and let the splitter cut BETWEEN
        # bubble clusters where there is no clean gutter.
        if os.environ.get("RECAP_TEXT_DET_SPLIT", "1").lower() not in ("0", "false", "no"):
            try:
                _tb = _detect_text_boxes(cv2.cvtColor(np.array(img_rgb), cv2.COLOR_RGB2GRAY))
                _existing = list(texts_y or [])
                for (tx1, ty1, tx2, ty2) in _tb:
                    if not any(min(tx2, e[2]) - max(tx1, e[0]) > 0 and
                               min(ty2, e[3]) - max(ty1, e[1]) > 0.5 * (ty2 - ty1)
                               for e in _existing):
                        _existing.append((int(tx1), int(ty1), int(tx2), int(ty2), 0.9))
                texts_y = _existing
            except Exception as _e:  # pragma: no cover
                log.debug("text-detector enrichment skipped (%s)", _e)
        # drop detector noise: a box too small to be a panel, or a thin
        # sliver that's really just a promoted text box (NOT a merge — these
        # are false positives, never real panels).
        panels_y = [
            b for b in panels_y
            if (b[2] - b[0]) * (b[3] - b[1]) > 0.025 * pg_area
            and (b[3] - b[1]) > 0.07 * H
            # a short box hugging the page top/bottom edge is a header /
            # footer / publisher watermark strip, not a story panel
            and not ((b[3] - b[1]) < 0.11 * H and (b[1] < 0.02 * H or b[3] > 0.98 * H))
        ]
        # drop panels almost entirely contained in a bigger one (nested inset
        # misfires) — keep the larger.
        panels_y.sort(key=lambda b: (b[2] - b[0]) * (b[3] - b[1]), reverse=True)
        kept = []
        for (x1, y1, x2, y2, sc) in panels_y:
            a = (x2 - x1) * (y2 - y1)
            nested = False
            for (kx1, ky1, kx2, ky2) in kept:
                ix = max(0.0, min(x2, kx2) - max(x1, kx1))
                iy = max(0.0, min(y2, ky2) - max(y1, ky1))
                if a > 0 and (ix * iy) / a > 0.80:
                    nested = True
                    break
            if not nested:
                # grow the tight border-hugging box a touch so an adjacent
                # bubble edge / border line isn't clipped
                gx, gy = 0.012 * W, 0.010 * H
                kept.append([max(0.0, x1 - gx), max(0.0, y1 - gy),
                             min(float(W), x2 + gx), min(float(H), y2 + gy)])

        _gray = cv2.cvtColor(np.array(img_rgb), cv2.COLOR_RGB2GRAY)
        yolo_boxes = [list(b) for b in kept]   # snapshot before gap-fill

        # 1) fill vertical spans the border-trained model left uncovered
        #    (full-bleed / borderless panels). Candidate boxes only — step 2
        #    decides new-panel vs continuation.
        row_ink = (_gray < 238).mean(axis=1)
        dark_row = (_gray < 205).mean(axis=1)
        covered = np.zeros(H, dtype=bool)
        for (x1, y1, x2, y2) in kept:
            covered[max(0, int(y1)):min(H, int(y2))] = True
        y = 0
        while y < H:
            if covered[y]:
                y += 1
                continue
            y0 = y
            while y < H and not covered[y]:
                y += 1
            nz = np.where(row_ink[y0:y] >= 0.05)[0]
            if not nz.size or (nz[-1] - nz[0]) < 0.05 * H:
                continue
            t0, t1 = y0 + int(nz[0]), y0 + int(nz[-1]) + 1
            if dark_row[t0:t1].mean() < 0.05:
                continue
            cols = (_gray[t0:t1] < 238).mean(axis=0)
            cnz = np.where(cols >= 0.02)[0]
            cx0, cx1 = (int(cnz[0]), int(cnz[-1]) + 1) if cnz.size else (0, W)
            kept.append([float(cx0), float(t0), float(cx1), float(t1)])

        # 2) CONTIGUITY MERGE — run on the still-TIGHT boxes (before bubbles
        #    are folded in and make panels overlap). Two vertically-adjacent
        #    boxes are the SAME panel unless a true gutter separates them: a
        #    horizontal band that reaches the page background (flood-filled
        #    from the edges — a bright spot INSIDE a panel does not count, and
        #    a speech bubble sitting in the gutter leaves most of the row as
        #    background so it still reads as a gutter). Full-bleed panels the
        #    model split, and gap-fill fragments, are glued back whole. No max
        #    height — a long panel is shown long, never cut through its art.
        white = (_gray >= 244).astype(np.uint8) * 255
        ff = white.copy()
        ffm = np.zeros((H + 2, W + 2), np.uint8)
        st = max(1, W // 24)
        for sx in range(0, W, st):
            for sy in (0, H - 1):
                if white[sy, sx]:
                    cv2.floodFill(ff, ffm, (sx, sy), 128)
        for sy in range(0, H, st):
            for sx in (0, W - 1):
                if white[sy, sx]:
                    cv2.floodFill(ff, ffm, (sx, sy), 128)
        bg_row = (ff == 128).mean(axis=1)
        # dark-mode webtoon pages (Solo Leveling's intro etc.) have NO white
        # to flood-fill — their gutters are flat black bands. Treat a row that
        # is almost entirely near-black with near-zero variance as background
        # too, so stacked "text on black" beats still separate.
        _dark_gutter = ((_gray <= 24).mean(axis=1) >= 0.95) & (_gray.std(axis=1) <= 14)
        bg_row = np.maximum(bg_row, _dark_gutter.astype(np.float32))

        def _text_bridges(a, b):
            # a speech bubble that straddles the boundary between two panels
            # ties them into one frame — splitting there would cut the bubble
            bl, bh = min(a[3], b[3]), max(a[1], b[1])
            mid = (a[3] + b[1]) / 2.0
            for (tx1, ty1, tx2, ty2, _s) in (texts_y or []):
                if ty1 < mid - 4 and ty2 > mid + 4:      # crosses the seam
                    if min(tx2, max(a[2], b[2])) - max(tx1, min(a[0], b[0])) > 0:
                        return True
            return False

        def _clean_gutter(a, b):
            # a CLEAN gutter = a full-width run of page background between the
            # two boxes with nothing (not even a bubble) crossing it. Only
            # then are the panels genuinely separate beats.
            c0 = int((a[1] + a[3]) / 2.0)
            c1 = int((b[1] + b[3]) / 2.0)
            lo, hi = min(c0, c1), max(c0, c1)
            if hi - lo < 4:
                return False
            return bool(float(bg_row[lo:hi].max()) >= 0.80)

        changed = True
        while changed and len(kept) > 1:
            changed = False
            kept.sort(key=lambda b: b[1])
            for i in range(len(kept) - 1):
                a, b = kept[i], kept[i + 1]
                x_ov = min(a[2], b[2]) - max(a[0], b[0])
                if x_ov < 0.25 * min(a[2] - a[0], b[2] - b[0]):
                    continue
                far = a[3] < b[1] - 0.22 * H
                merge = (not far and not _clean_gutter(a, b)) or _text_bridges(a, b)
                if merge:
                    kept[i] = [min(a[0], b[0]), min(a[1], b[1]),
                               max(a[2], b[2]), max(a[3], b[3])]
                    del kept[i + 1]
                    changed = True
                    break

        # 3) attach each text box to the panel it overlaps most (nearest if it
        #    overlaps none) — the emitted panel is the UNION of the panel box
        #    and its text boxes, so a bubble that overflows the border into the
        #    gutter is still wholly inside the frame.
        for (tx1, ty1, tx2, ty2, _s) in (texts_y or []):
            ta = max(1.0, (tx2 - tx1) * (ty2 - ty1))
            tcx = (tx1 + tx2) / 2.0
            best, best_ov = None, 0.0
            for i, (x1, y1, x2, y2) in enumerate(kept):
                ix = max(0.0, min(tx2, x2) - max(tx1, x1))
                iy = max(0.0, min(ty2, y2) - max(ty1, y1))
                ov = (ix * iy) / ta
                if ov > best_ov:
                    best, best_ov = i, ov
            if best is None or best_ov < 0.08:
                # No overlap: attach to the nearest panel DIRECTLY above or
                # below whose x-range contains the bubble's centre and which
                # has no other panel between it and the bubble. A bubble is
                # often placed well outside its panel's border.
                best, bd = None, 1e18
                for i, (x1, y1, x2, y2) in enumerate(kept):
                    if not (x1 - 0.03 * W <= tcx <= x2 + 0.03 * W):
                        continue
                    if ty1 >= y2:            # bubble below panel i
                        gap = ty1 - y2
                        blocked = any(k != i and kept[k][3] > y2 + 2 and kept[k][1] < ty1 - 2
                                      and kept[k][0] - 0.03 * W <= tcx <= kept[k][2] + 0.03 * W
                                      for k in range(len(kept)))
                    elif ty2 <= y1:          # bubble above panel i
                        gap = y1 - ty2
                        blocked = any(k != i and kept[k][1] < y1 - 2 and kept[k][3] > ty2 + 2
                                      and kept[k][0] - 0.03 * W <= tcx <= kept[k][2] + 0.03 * W
                                      for k in range(len(kept)))
                    else:
                        gap, blocked = 0.0, False
                    if not blocked and gap < bd:
                        best, bd = i, gap
                if best is None or bd > 0.22 * H:
                    continue
            b = kept[best]
            b[0], b[1] = min(b[0], tx1), min(b[1], ty1)
            b[2], b[3] = max(b[2], tx2), max(b[3], ty2)

        # 4) final tidy of thin bubble/text-only strips (NOT panels): a short,
        #    low-art-density box is an overflow bubble or a page-edge bleed /
        #    publisher watermark, never a story panel. Fold it into the
        #    vertically-nearest real panel; drop it only if there is none.
        def _yolo_backed(bx):
            a = max(1.0, (bx[2] - bx[0]) * (bx[3] - bx[1]))
            for (yx1, yy1, yx2, yy2) in yolo_boxes:
                ix = max(0.0, min(bx[2], yx2) - max(bx[0], yx1))
                iy = max(0.0, min(bx[3], yy2) - max(bx[1], yy1))
                if (ix * iy) / a > 0.55:
                    return True
            return False

        # A box is a real panel if the model saw it AND it's tall enough to
        # be a beat, OR (gap-fill origin) it's a genuine full-bleed panel the
        # model missed. A short full-width box — a floating dialogue bubble, a
        # gutter fragment, a bleed strip — is folded into its neighbour so
        # the bubble rides along with a panel and no beat is wasted on it.
        real, strips = [], []
        for b in kept:
            hfrac = (b[3] - b[1]) / H
            if hfrac < 0.15:
                strips.append(b)
            elif _yolo_backed(b) or hfrac >= 0.26:
                real.append(b)
            else:
                strips.append(b)
        if not real and kept:
            real = [max(kept, key=lambda b: (b[2] - b[0]) * (b[3] - b[1]))]
            strips = [b for b in kept if b is not real[0]]
        for s in strips:
            scy = (s[1] + s[3]) / 2.0
            host, hd = None, 1e18
            for r in real:
                if s[2] < r[0] - 0.05 * W or s[0] > r[2] + 0.05 * W:
                    continue
                d = 0.0 if r[1] <= scy <= r[3] else min(abs(scy - r[1]), abs(scy - r[3]))
                if d < hd:
                    host, hd = r, d
            if host is not None and hd < 0.28 * H:
                host[0], host[1] = min(host[0], s[0]), min(host[1], s[1])
                host[2], host[3] = max(host[2], s[2]), max(host[3], s[3])
            # else: dropped (edge bleed / watermark with no panel to belong to)
        kept = real

        # 5) BORDERLESS-WEBTOON SPLIT — the YOLO detector (trained on
        #    bordered print manga) collapses a tall webtoon column of
        #    full-width stacked panels into one giant box. Break any box
        #    much taller than it is wide at its internal clean gutter rows
        #    (a full-width band of page background between two panels).
        if kept:
            split_kept = []
            for b in kept:
                split_kept.extend(_split_borderless_column(b, _gray, texts_y))
            kept = split_kept

        if kept:
            ordered = _reading_order_boxes([tuple(b) for b in kept])
            return [(int(x1), int(y1), int(x2), int(y2)) for (x1, y1, x2, y2) in ordered]

    # ---- fallback: white-background flood fill ----
    arr = np.array(img_rgb)
    gray = cv2.cvtColor(arr, cv2.COLOR_RGB2GRAY)
    h, w = gray.shape
    page_area = float(h * w)

    white = (gray >= 244).astype(np.uint8)
    ff = (white * 255).astype(np.uint8)
    ff_mask = np.zeros((h + 2, w + 2), np.uint8)
    step = max(1, w // 24)
    seeds = [(0, 0), (w - 1, 0), (0, h - 1), (w - 1, h - 1)]
    seeds += [(x, 0) for x in range(0, w, step)] + [(x, h - 1) for x in range(0, w, step)]
    seeds += [(0, y) for y in range(0, h, step)] + [(w - 1, y) for y in range(0, h, step)]
    for (sx, sy) in seeds:
        if 0 <= sx < w and 0 <= sy < h and ff[sy, sx] == 255:
            cv2.floodFill(ff, ff_mask, (sx, sy), 128)
    background = (ff == 128)

    panel_mask = np.where(background, 0, 255).astype(np.uint8)
    # solidify panels (bridge internal white bubbles / gaps to their panel)
    # without merging across a normal inter-panel gutter
    panel_mask = cv2.morphologyEx(
        panel_mask, cv2.MORPH_CLOSE,
        cv2.getStructuringElement(cv2.MORPH_RECT, (max(9, w // 90), max(9, h // 160))),
        iterations=1,
    )

    n, labels, stats, _ = cv2.connectedComponentsWithStats(panel_mask, connectivity=8)
    panels, bubbles = [], []
    for i in range(1, n):
        x, y, bw, bh, area = stats[i]
        if area < 24:
            continue
        box = (int(x), int(y), int(x + bw), int(y + bh))
        frac = area / page_area
        if frac >= PANEL_MIN_AREA_FRAC and bw > 0.18 * w and bh > 0.03 * h:
            panels.append(box)
        elif frac < PANEL_BUBBLE_AREA_FRAC:
            comp = (labels[y:y + bh, x:x + bw] == i)
            if comp.any() and gray[y:y + bh, x:x + bw][comp].mean() > 150:
                bubbles.append(box)

    if not panels:
        return [(0, 0, w, h)]

    # reattach overflow bubbles to the nearest panel (vertically)
    for (bx1, by1, bx2, by2) in bubbles:
        bcy = (by1 + by2) / 2.0
        best, best_d = None, 1e18
        for idx, (px1, py1, px2, py2) in enumerate(panels):
            if bx2 < px1 - w * 0.05 or bx1 > px2 + w * 0.05:
                continue
            d = (py1 - bcy) if bcy < py1 else (bcy - py2 if bcy > py2 else 0.0)
            d = abs(d) - (0.5 if bcy < py1 else 0.0)  # tie -> panel below
            if d < best_d:
                best, best_d = idx, d
        if best is not None and best_d < h * 0.08:
            px1, py1, px2, py2 = panels[best]
            panels[best] = (min(px1, bx1), min(py1, by1), max(px2, bx2), max(py2, by2))

    # merge panels that heavily overlap (a bubble bridged two detections)
    panels.sort(key=lambda b: (b[1], b[0]))
    merged: List[tuple] = []
    for b in panels:
        placed = False
        for j, m in enumerate(merged):
            ix = max(0, min(b[2], m[2]) - max(b[0], m[0]))
            iy = max(0, min(b[3], m[3]) - max(b[1], m[1]))
            inter = ix * iy
            amin = min((b[2] - b[0]) * (b[3] - b[1]), (m[2] - m[0]) * (m[3] - m[1]))
            if amin > 0 and inter / amin > 0.45:
                merged[j] = (min(b[0], m[0]), min(b[1], m[1]), max(b[2], m[2]), max(b[3], m[3]))
                placed = True
                break
        if not placed:
            merged.append(tuple(b))

    # Refine: a big bubble that spilled across a gutter can still bridge two
    # panels into one blob. Split any tall box at an internal "gutter row" —
    # a row that is mostly page background even though a bubble pokes through
    # part of its width.
    bg_row_frac = background.mean(axis=1)  # per-row fraction that is background
    refined: List[tuple] = []
    for (x1, y1, x2, y2) in merged:
        stack = [(y1, y2)]
        while stack:
            a, b = stack.pop()
            if (b - a) < h * 0.10 or (b - a) < (x2 - x1) * 1.15:
                refined.append((x1, a, x2, b))
                continue
            m0 = a + int((b - a) * 0.14)
            m1 = b - int((b - a) * 0.14)
            band = bg_row_frac[m0:m1]
            if band.size and band.max() > 0.62:
                cut = m0 + int(np.argmax(band))
                # widen to the middle of the contiguous gutter run
                lo = hi = cut
                while lo > m0 and bg_row_frac[lo] > 0.55:
                    lo -= 1
                while hi < m1 and bg_row_frac[hi] > 0.55:
                    hi += 1
                cut = (lo + hi) // 2
                stack.append((cut, b))
                stack.append((a, cut))
            else:
                refined.append((x1, a, x2, b))

    refined = [box for box in refined
               if (box[3] - box[1]) > h * 0.03 and
               not _is_blank_crop(gray[box[1]:box[3], box[0]:box[2]])]
    if not refined:
        refined = merged

    ordered = _reading_order_boxes([(x1, y1, x2, y2) for (x1, y1, x2, y2) in refined])
    return [(int(x1), int(y1), int(x2), int(y2)) for (x1, y1, x2, y2) in ordered]


def _reading_order_boxes(boxes: "List[tuple]") -> "List[tuple]":
    """Order (x1,y1,x2,y2) panel boxes into LTR reading order via a recursive
    XY-cut: split on the widest gap NO box crosses — horizontally first
    (rows), then vertically (side-by-side panels, left first). Handles
    staggered / diagonal layouts a plain (y,x) sort gets wrong."""
    if len(boxes) <= 1:
        return list(boxes)

    def _split(bs, depth=0):
        if len(bs) <= 1 or depth > 60:
            return sorted(bs, key=lambda b: (b[1], b[0]))
        # horizontal cut
        ys = sorted(bs, key=lambda b: b[1])
        cur = ys[0][3]
        gap, at = 0.0, None
        for b in ys[1:]:
            g = b[1] - cur
            if g > gap:
                gap, at = g, (cur + b[1]) / 2.0
            cur = max(cur, b[3])
        if at is not None and gap > 1.0:
            top = [b for b in bs if (b[1] + b[3]) / 2.0 < at]
            bot = [b for b in bs if (b[1] + b[3]) / 2.0 >= at]
            if top and bot:
                return _split(top, depth + 1) + _split(bot, depth + 1)
        # vertical cut
        xs = sorted(bs, key=lambda b: b[0])
        cur = xs[0][2]
        gap, at = 0.0, None
        for b in xs[1:]:
            g = b[0] - cur
            if g > gap:
                gap, at = g, (cur + b[0]) / 2.0
            cur = max(cur, b[2])
        if at is not None and gap > 1.0:
            left = [b for b in bs if (b[0] + b[2]) / 2.0 < at]
            right = [b for b in bs if (b[0] + b[2]) / 2.0 >= at]
            if left and right:
                return _split(left, depth + 1) + _split(right, depth + 1)
        return sorted(bs, key=lambda b: (b[1], b[0]))

    return _split(list(boxes))


def _pages_are_webtoon_chunks(page_paths: "List[Path]") -> bool:
    """True when the 'pages' are really one long vertical webtoon strip that
    the source host sliced into fixed-height chunks at ARBITRARY pixel rows
    (not panel/scene boundaries). Signature: uniform width, and a good share
    of page-to-page seams land in the middle of artwork (ink on both sides of
    the seam) instead of on a white gutter. Gates the seam-stitch in
    _frame_pages_reference_style — a properly paginated comic never needs it."""
    from PIL import Image
    if len(page_paths) < 3:
        return False
    widths, seam_hits, seams = [], 0, 0
    prev_bottom = None
    for p in page_paths:
        try:
            with Image.open(p) as im:
                g = np.asarray(im.convert("L"))
        except Exception:
            return False
        widths.append(g.shape[1])
        top_ink = float((g[:6] < 235).mean())
        if prev_bottom is not None:
            seams += 1
            # both sides of the seam carry ink => the cut is mid-artwork
            if prev_bottom > 0.05 and top_ink > 0.05:
                seam_hits += 1
        prev_bottom = float((g[-6:] < 235).mean())
    if max(widths) - min(widths) > 3:
        return False
    return seams > 0 and seam_hits / seams >= 0.34


def _pages_are_webtoon_strip(page_paths: "List[Path]") -> bool:
    """True when the 'pages' are a long vertical webtoon chapter served as
    several tall, uniform-width strip images — whether the host cut them at
    arbitrary rows (mid-art, → _pages_are_webtoon_chunks) OR politely on a
    gutter (AsuraScans, Webtoons mirrors, …). Either way each 'page' is a
    multi-panel column, not a single comic page, so the right move is to glue
    them and cut the whole strip with the conservative gutter rule instead of
    running per-page panel detection (which orphans every floating bubble).

    Signature: ≥3 pages, near-uniform width, and the typical page is TALL
    (median aspect ≥ 2.2) — a normally paginated comic page is ~1.3–1.6."""
    from PIL import Image
    if len(page_paths) < 3:
        return False
    widths, aspects = [], []
    for p in page_paths:
        try:
            with Image.open(p) as im:
                w, h = im.size
        except Exception:
            return False
        if w <= 0 or h <= 0:
            return False
        widths.append(w)
        aspects.append(h / w)
    if max(widths) - min(widths) > max(4, 0.02 * float(np.median(widths))):
        return False
    return float(np.median(aspects)) >= 2.2


def _seam_is_midart(bottom_gray: "np.ndarray", top_gray: "np.ndarray") -> bool:
    """A page boundary that cuts THROUGH artwork — ink right up to the bottom
    edge of page N and the top edge of page N+1, with no white gutter band.
    A panel straddling such a seam is physically split between the two files
    and per-page detection can only ever show half of it."""
    b = float((bottom_gray[-6:] < 235).mean())
    t = float((top_gray[:6] < 235).mean())
    # a clean gutter shows as a run of near-white rows at the edge
    b_white = int(np.argmax((bottom_gray[::-1] >= 243).mean(axis=1) < 0.97)) if bottom_gray.size else 99
    t_white = int(np.argmax((top_gray >= 243).mean(axis=1) < 0.97)) if top_gray.size else 99
    return b > 0.05 and t > 0.05 and b_white < 4 and t_white < 4


def _pages_are_presliced_tiles(page_paths: "List[Path]") -> bool:
    """True when the source 'pages' are already individual panel tiles — the
    shape many aggregators (mgeko, toonily, mangapill, …) serve instead of a
    raw 800x10000 webtoon strip. Signature: uniform width, modest heights
    (never a tall strip), aspect ratio close to a single panel, and enough of
    them that the chapter was clearly served pre-cut. On tiles the panel
    detector + borderless split + edge-trim machinery (all tuned for tall
    strips) does more harm than good — it fragments clean panels, emits
    atmosphere-only slivers, and crops through faces. RECAP_TILE_PASSTHROUGH=0
    forces the full detection path anyway."""
    if os.environ.get("RECAP_TILE_PASSTHROUGH", "1").lower() in ("0", "false", "no"):
        return False
    from PIL import Image
    if len(page_paths) < 12:
        return False
    dims = []
    for p in page_paths[:40]:
        try:
            with Image.open(p) as im:
                dims.append(im.size)  # (w, h)
        except Exception:
            return False
    if len(dims) < 12:
        return False
    ws = sorted(w for w, _ in dims)
    med_w = ws[len(ws) // 2]
    # tolerate a handful of odd pages (title card, wide splash): most tiles
    # share a width, few are tall, typical single-panel aspect on the median.
    same_w = sum(1 for w, _ in dims if abs(w - med_w) <= max(6, 0.06 * med_w))
    tall = sum(1 for w, h in dims if h > 2200 or h / max(1, w) > 2.6)
    ratios = sorted(h / max(1, w) for w, h in dims)
    med_ratio = ratios[len(ratios) // 2]
    return (same_w >= 0.8 * len(dims)
            and tall <= 0.12 * len(dims)
            and med_ratio <= 2.2
            and med_w <= 1600)


def _border_trim_amounts(rgb: "np.ndarray", max_frac: float = 0.10):
    """(top, bottom, left, right) rows/cols of pure letterbox to drop —
    near-white (>=246) OR near-black (<=12) across >=98.5% of the span,
    contiguous from each edge, capped at `max_frac` per side. Never touches
    coloured art or a bubble edge (the old `< 234` ink trim did — that was
    the 'cuts through content' bug)."""
    if rgb.ndim != 3 or rgb.shape[0] < 20 or rgb.shape[1] < 20:
        return 0, 0, 0, 0
    g = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY)
    H, W = g.shape
    row_bar = ((g >= 246).mean(axis=1) >= 0.985) | ((g <= 12).mean(axis=1) >= 0.985)
    col_bar = ((g >= 246).mean(axis=0) >= 0.985) | ((g <= 12).mean(axis=0) >= 0.985)
    def _run(mask, limit):
        n = 0
        while n < limit and n < len(mask) and mask[n]:
            n += 1
        return n
    t = _run(row_bar, int(H * max_frac))
    b = _run(row_bar[::-1], int(H * max_frac))
    l = _run(col_bar, int(W * max_frac))
    r = _run(col_bar[::-1], int(W * max_frac))
    if t + b >= H - 20 or l + r >= W - 20:
        return 0, 0, 0, 0
    return t, b, l, r


def _safe_border_trim(rgb: "np.ndarray", max_frac: float = 0.10) -> "np.ndarray":
    t, b, l, r = _border_trim_amounts(rgb, max_frac)
    if t or b or l or r:
        return rgb[t:rgb.shape[0] - b, l:rgb.shape[1] - r]
    return rgb


_INCLUSIVE_SLICE = os.environ.get("RECAP_SLICE_INCLUSIVE", "0").lower() not in ("0", "false", "no")


def _inclusive_crop_box(gray, box, prev_y2, next_y1, W, H):
    """Inclusive slicing (RECAP_SLICE_INCLUSIVE=1). Expand the panel box into
    the gutters — capped at ~45 % of a gutter so it can never reach the
    neighbour's art — then a bounded cropper re-finds the exact gutter cut
    inside that safe band, correcting a detector edge that landed a little
    inside the panel. When there's no clean gutter to cut at (borderless
    bleed) it keeps the loose edge: the panel is always whole; a wrong
    gutter estimate costs a thin gutter sliver, never a truncated panel."""
    x1, y1, x2, y2 = (int(v) for v in box)
    OV = int(os.environ.get("RECAP_SLICE_OVERLAP_PX", "90"))
    FR = float(os.environ.get("RECAP_SLICE_OVERLAP_FRAC", "0.45"))
    RCH = int(os.environ.get("RECAP_SLICE_CORRECT_PX", "24"))  # max correction PAST the detector edge
    inf_up = min(OV, max(0, int(FR * (y1 - prev_y2))))
    inf_dn = min(OV, max(0, int(FR * (next_y1 - y2))))
    ly1, ly2 = max(0, y1 - inf_up), min(H, y2 + inf_dn)

    row_ink = (gray < 200).mean(axis=1)          # fraction of dark px per row

    def _gutter_cut(lo, hi):
        """emptiest row in [lo, hi) if it's a genuine gutter (<=3% ink),
        widened to the middle of the low-ink run; else None."""
        lo, hi = max(0, int(lo)), min(H, int(hi))
        if hi - lo < 4:
            return None
        seg = row_ink[lo:hi]
        k = int(np.argmin(seg))
        if seg[k] > 0.03:
            return None
        a = b = k
        while a > 0 and seg[a - 1] <= 0.03:
            a -= 1
        while b < len(seg) - 1 and seg[b + 1] <= 0.03:
            b += 1
        return lo + (a + b) // 2

    # Search ONLY the inflation band (pure gutter) plus a tiny fixed reach past
    # the detector edge — the cropper can pull a frame in to a clean gutter but
    # can NEVER carve into the panel body looking for a gutter that isn't there.
    top = _gutter_cut(ly1, y1 + RCH) if inf_up > 0 or ly1 < y1 else None
    bot = _gutter_cut(y2 - RCH, ly2) if inf_dn > 0 or ly2 > y2 else None
    ny1 = top if top is not None else ly1
    ny2 = bot if bot is not None else ly2
    # hard floors: never past the detector edge by more than RCH
    ny1 = min(max(ny1, y1 - inf_up), y1 + RCH)
    ny2 = max(min(ny2, y2 + inf_dn), y2 - RCH)
    if ny2 - ny1 < 0.6 * (y2 - y1):
        ny1, ny2 = ly1, ly2
    return max(0, x1 - 4), ny1, min(W, x2 + 4), ny2


def _frame_presliced_tiles(cfg: "PipelineConfig", chapter: "Chapter",
                           out_dir: Path) -> "List[FrameEntry]":
    """Passthrough framing for chapters served as individual panel tiles.
    Each tile becomes ONE frame — no panel detection, no splitting, no
    aggressive cropping. Pure letterbox bars are trimmed; a run of very short
    tiles is merged so a 1-line caption strip isn't its own 2-second beat."""
    from PIL import Image
    entries: List[FrameEntry] = []
    counter = 0
    total = len(chapter.panel_paths)

    def _emit_tile(rgb, page_idx, page_name):
        nonlocal counter
        g = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY)
        if _is_blank_crop(g) or rgb.shape[0] < 24 or rgb.shape[1] < 24:
            return
        if (page_idx <= 1 or page_idx >= total - 2) and _looks_like_credits_panel(rgb):
            log.info("[%s] tile passthrough: skipped credits panel on page %d", chapter.tag, page_idx + 1)
            return
        fp = out_dir / f"frame_{counter:05d}.jpg"
        _compose_canvas(Image.fromarray(rgb)).save(fp, quality=92)
        ocr_path = ""
        if _OCR_FRAMES_ENABLED:
            ocr_fp = out_dir / f"frame_{counter:05d}_ocr.jpg"
            try:
                oc = rgb
                target = int(os.environ.get("RECAP_OCR_MAX_SIDE", "1100"))
                m = max(oc.shape[:2])
                if m > 0 and abs(m - target) / target > 0.05:
                    s = target / m
                    interp = cv2.INTER_AREA if s < 1 else cv2.INTER_CUBIC
                    oc = cv2.resize(oc, (max(1, int(oc.shape[1] * s)), max(1, int(oc.shape[0] * s))), interpolation=interp)
                Image.fromarray(oc).save(ocr_fp, quality=94)
                ocr_path = str(ocr_fp.resolve())
            except Exception:
                ocr_path = ""
        entries.append(FrameEntry(
            frame_id=f"{chapter.tag}_frame_{counter:05d}",
            filename=fp.name, path=str(fp.resolve()), ocr_path=ocr_path,
            source_page=page_name, source_index=page_idx, frame_kind="panel",
            source_box=[0, 0, int(rgb.shape[1]), int(rgb.shape[0])],
        ))
        counter += 1

    pending = None  # (rgb, page_idx, name) — a short tile waiting to merge downward
    MIN_H = int(os.environ.get("RECAP_TILE_MIN_H", "190"))
    for page_idx, p in enumerate(chapter.panel_paths):
        try:
            with Image.open(p) as im:
                rgb = _safe_border_trim(np.array(im.convert("RGB")))
        except Exception as exc:
            log.warning("[%s] tile passthrough: unreadable %s (%s)", chapter.tag, p.name, exc)
            continue
        if pending is not None:
            prg, pidx, pnm = pending
            if prg.shape[1] == rgb.shape[1]:
                rgb = np.concatenate([prg, rgb], axis=0)
            else:
                _emit_tile(prg, pidx, pnm)
            pending = None
        if rgb.shape[0] < MIN_H:
            pending = (rgb, page_idx, p.name)
            continue
        _emit_tile(rgb, page_idx, p.name)
    if pending is not None:
        _emit_tile(*pending)

    log.info("[%s] tile passthrough: %d tiles -> %d panel frames", chapter.tag, total, len(entries))
    _slice_qa_check(chapter.tag, entries, [])
    return entries


# ---------------------------------------------------------------------------
# Strip reconstruction (RECAP_STRIP_RECONSTRUCT / _pages_are_webtoon_chunks)
#
# Aggregators serve a webtoon as fixed-height chunks cut at ARBITRARY pixel
# rows — usually mid-panel. Slicing each chunk alone means the cutter keeps
# seeing "half a panel + whitespace + half a panel" and guesses wrong. Glue
# the chunks back into the original strip first, de-dup the seams, then cut
# the whole thing — every panel is complete. Tiles (mgeko etc.) skip this:
# they're already single panels, reconstruction would be wasted work.
# ---------------------------------------------------------------------------

def _reconstruct_strip(page_paths):
    """Concatenate chunk images into one tall RGB array. Cross-correlates each
    seam to drop duplicated rows (some CDNs repeat a strip of pixels across the
    join); a genuine gutter gap is left alone. Returns (strip_rgb, spans) where
    spans = [(page_name, y0, y1)] for mapping a panel back to its source page."""
    from PIL import Image
    imgs, names = [], []
    for p in page_paths:
        try:
            with Image.open(p) as im:
                imgs.append(np.array(im.convert("RGB")))
                names.append(p.name)
        except Exception as exc:
            log.warning("reconstruct: unreadable %s (%s)", p.name, exc)
    if not imgs:
        return None, []
    W = int(np.median([a.shape[1] for a in imgs]))
    norm = []
    for a in imgs:
        if a.shape[1] != W:
            a = cv2.resize(a, (W, int(a.shape[0] * W / a.shape[1])), interpolation=cv2.INTER_AREA)
        norm.append(a)
    parts, spans, y = [], [], 0
    for i, a in enumerate(norm):
        drop = 0
        if parts:
            prev_tail = cv2.cvtColor(parts[-1][-60:], cv2.COLOR_RGB2GRAY).astype(np.float32)
            head = cv2.cvtColor(a[:200], cv2.COLOR_RGB2GRAY).astype(np.float32)
            best, bestsc = 0, 1e18
            for sh in range(0, min(150, len(head) - len(prev_tail))):
                d = np.abs(head[sh:sh + len(prev_tail)] - prev_tail).mean()
                if d < bestsc:
                    bestsc, best = d, sh
            if bestsc < 6.0:            # a real overlap, not coincidence
                drop = best + len(prev_tail)
        a2 = a[drop:] if 0 < drop < a.shape[0] - 20 else a
        parts.append(a2)
        spans.append((names[i], y, y + a2.shape[0]))
        y += a2.shape[0]
    return np.concatenate(parts, axis=0), spans


def _cut_strip_into_panels(gray, texts, W, H, nocut=None):
    """Cut a reconstructed strip into panels — CONSERVATIVE gutter rule.

    Cut ONLY at a wide, clean, full-width gutter (a near-white OR near-black
    band). `nocut` (bool per-row) is the HARD no-cut mask — faces, plus
    bubbles when RECAP_BUBBLE_DETECT=1 — a cut may never pass through it.
    A speech bubble floating in a gutter does NOT block the cut (that merged
    THWT conversations into one tall strip); instead the band is bridged back
    together and the cut is placed on the clean side of the bubble so it
    stays whole with exactly one panel (webtoon default: bubble joins the
    panel BELOW when there's clean gutter above it). Whatever sits between two
    gutters is one panel with every bubble that lands there — no box
    expansion, no "nearest panel" reasoning. A near-empty segment folds into
    the segment BELOW. An over-tall gutterless block gets one low-ink split.
    """
    MIN_GUT = int(os.environ.get("RECAP_STRIP_MIN_GUTTER", "34"))
    MIN_PANEL = int(os.environ.get("RECAP_STRIP_MIN_PANEL", "170"))
    MAX_PANEL = int(os.environ.get("RECAP_STRIP_MAX_PANEL", "3800"))
    g = gray.astype(np.int16)
    std = g.std(axis=1)
    ink = (g < 205).mean(axis=1)

    tboxes = [(int(ty1), int(ty2)) for (tx1, ty1, tx2, ty2, *_r) in (texts or [])
              if 0 <= ty1 < ty2 <= H]
    txt_rows = np.zeros(H, dtype=bool)
    for (ty1, ty2) in tboxes:
        txt_rows[max(0, ty1 - 4):min(H, ty2 + 4)] = True

    # `nocut` is the HARD no-cut mask — faces (and bubbles when
    # RECAP_BUBBLE_DETECT=1). A cut may never pass through it. Speech-bubble
    # TEXT is NOT a no-cut zone: a bubble floating in a gutter has to be
    # ASSIGNED to one of the two neighbouring panels, never used to suppress
    # the gutter — suppressing it is exactly what merged THWT conversations
    # into one tall strip.
    face_rows = (np.asarray(nocut, dtype=bool)[:H] if nocut is not None
                 else np.zeros(H, dtype=bool))

    # clean gutter row: near-uniform full-width white OR black, not through a face
    white = ((g >= 244).mean(axis=1) >= 0.97) & (std <= 16)
    black = ((g <= 18).mean(axis=1) >= 0.95) & (std <= 14)
    gut = (white | black) & ~face_rows

    # raw clean-gutter bands
    raw, i = [], 0
    while i < H:
        if not gut[i]:
            i += 1; continue
        j = i
        while j < H and gut[j]:
            j += 1
        raw.append([i, j])
        i = j

    # A speech bubble floating in a gutter splits the white band in two, and
    # each half can drop under MIN_GUT so the cut is lost and the panels
    # merge. Bridge two clean bands separated ONLY by bubble text + blank
    # rows (no solid art between them) back into one logical gutter zone.
    BR = int(os.environ.get("RECAP_STRIP_BUBBLE_BRIDGE", "170"))
    bands = []
    for bd in raw:
        if bands:
            g0, g1 = bands[-1][1], bd[0]
            if 0 < g1 - g0 <= BR:
                solid = (ink[g0:g1] >= 0.16) & ~txt_rows[g0:g1]
                if float(solid.mean()) < 0.04:
                    bands[-1][1] = bd[1]
                    continue
        bands.append(bd[:])

    # place one cut per gutter band; when a bubble sits in the band, cut on
    # the clean side of it so it stays whole with a single panel
    cuts = []
    for (a, b) in bands:
        if int(gut[a:b].sum()) < MIN_GUT:
            continue
        ov = [(t1, t2) for (t1, t2) in tboxes if t1 < b - 2 and t2 > a + 2]
        if ov:
            btop = max(a, min(t[0] for t in ov))
            bbot = min(b, max(t[1] for t in ov))
            if btop - a >= 12:
                cuts.append((a + btop) // 2)        # clean gutter above -> bubble joins panel BELOW
            elif b - bbot >= 12:
                cuts.append((bbot + b) // 2)        # clean gutter below -> bubble joins panel ABOVE
            else:
                cuts.append((a + b) // 2)
        else:
            cuts.append((a + b) // 2)

    bounds = [0] + cuts + [H]
    segs = [[bounds[k], bounds[k + 1]] for k in range(len(bounds) - 1)
            if bounds[k + 1] - bounds[k] >= MIN_PANEL]
    if not segs:
        segs = [[0, H]]

    # split an over-tall gutterless block once at its emptiest internal row
    out = []
    for (a, b) in segs:
        while b - a > MAX_PANEL:
            lo, hi = a + int(0.30 * (b - a)), b - int(0.30 * (b - a))
            seg = ink[lo:hi]
            k = lo + int(np.argmin(seg))
            if seg.min() > 0.055 or face_rows[k] or txt_rows[k]:
                break
            out.append([a, k]); a = k
        out.append([a, b])
    out.sort()

    def _artf(a, b):
        s = slice(max(0, a), min(H, b))
        return float(((ink[s] >= 0.16) & ~txt_rows[s]).mean()) if b > a else 0.0

    def _nbox(a, b):
        return sum(1 for (t1, t2) in tboxes if t1 < b - 2 and t2 > a + 2)

    # A segment that must NOT stand on its own as a frame: a sliver, a near-
    # blank band, a bubble/text run over almost no drawn art, or a tall stack
    # of ≥3 bubbles with little art (an orphan speech ribbon). A segment that
    # carries real art of its own — e.g. a face close-up under one bubble —
    # is NOT needy and is never folded away, even when it's tall.
    def _needy(a, b):
        if b - a < MIN_PANEL:
            return True
        af = _artf(a, b)
        if af < 0.10:
            return True
        if af < 0.24 and _nbox(a, b) >= 1:          # bubbles/caption over sparse art
            return True
        if (b - a) > int(1.8 * W) and _nbox(a, b) >= 3 and af < 0.28:
            return True
        return False

    # Fold each needy segment into the neighbour with the most drawn art —
    # i.e. toward the speaker. A speech bubble in this genre sits just below
    # (or beside) whoever said it far more often than above the next shot, so
    # "always fold down" kept handing a bubble to the beat AFTER the one it
    # belongs to ("ghalat panel ko ghalat bubble"). One left-to-right pass;
    # each merged block is locked (index skips past it) so a big orphan ribbon
    # can't chain-eat a whole column of panels.
    i = 0
    while i < len(out) and len(out) > 1:
        if not _needy(*out[i]):
            i += 1
            continue
        if i == 0:
            j = 1
        elif i == len(out) - 1:
            j = i - 1
        else:
            j = i - 1 if _artf(*out[i - 1]) >= _artf(*out[i + 1]) else i + 1
        lo, hi = min(i, j), max(i, j)
        out[lo] = [min(out[lo][0], out[hi][0]), max(out[lo][1], out[hi][1])]
        del out[hi]
        i = lo + 1

    # cut points land in the middle of the gap between finished panels
    out.sort()
    res, prev = [], 0
    for idx, (a, b) in enumerate(out):
        top = prev if idx else 0
        bot = (b + out[idx + 1][0]) // 2 if idx + 1 < len(out) else H
        res.append((0, max(0, top), W, min(H, bot)))
        prev = bot
    return res


def _squeeze_internal_whitespace(rgb, keep=48):
    """Collapse a wide internal all-background band (>150px of near-uniform
    white/black spanning the full width) down to `keep` px, seaming the
    content above and below together. Used after a floating bubble is folded
    into its panel so the frame shows 'bubble + panel', not 'bubble + a lake
    of white + panel'. Purely visual."""
    if rgb.ndim != 3 or rgb.shape[0] < 400:
        return rgb
    g = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY).astype(np.int16)
    H = g.shape[0]
    std = g.std(axis=1)
    bg = (((g >= 244).mean(axis=1) >= 0.97) | ((g <= 16).mean(axis=1) >= 0.97)) & (std <= 14)
    keep_rows = np.ones(H, dtype=bool)
    i = 0
    while i < H:
        if not bg[i]:
            i += 1; continue
        j = i
        while j < H and bg[j]:
            j += 1
        # only squeeze an INTERNAL band (not the top/bottom margin) that's fat
        if i > 10 and j < H - 10 and (j - i) > 150:
            keep_rows[i + keep // 2: j - keep // 2] = False
        i = j
    if keep_rows.all():
        return rgb
    return rgb[keep_rows]


_WM_RE = re.compile(
    r"(read\s+(it\s+)?(first|now|more)?\s*(on|at)\b)|(\.com\b)|(\.net\b)|"
    r"(scans?\b)|(manhwa[\s-]*freak)|(freakscans)|(asura\w*)|(flamescans?)|"
    r"(reaperscans?)|(mangabuddy)|(manhuaplus)|(join\s+(our\s+)?discord)|"
    r"(follow\s+us)|(support\s+us\s+on)", re.IGNORECASE)


def _strip_edge_watermark(rgb, text_boxes=None, max_frac: float = 0.30):
    """Trim an aggregator's watermark from the TOP or BOTTOM edge of a panel
    crop — the "READ AT / MANHWA-FREAK.COM / FREAKSCANS.COM" style stack that
    scanlation sites burn onto the artwork (not a flat banner, so
    `_looks_like_credits_panel` / `_border_trim_amounts` miss it; mid-art, so
    `_trim_edge_whitespace` misses it too).

    Structural signal, no OCR: >=2 WIDE (>=48% of the crop width) text lines,
    STACKED (line gaps <= 30px), FLUSH to an edge (within ~24px), with the
    real artwork ending in a near-clean transition just above/below the stack.
    Three wide text lines glued to the very bottom edge is a watermark, not a
    story caption (those are boxed and sit higher).

    `text_boxes` = the detected text boxes in THIS crop's coordinates
    [(x1,y1,x2,y2,...), ...]. Falls back to a pixel scan if not given.
    Returns (trimmed_rgb, top_removed, bottom_removed). Conservative and it
    only touches the *displayed* frame — the OCR crop keeps everything.
    """
    if os.environ.get("RECAP_STRIP_WATERMARK", "1").lower() in ("0", "false", "no"):
        return rgb, 0, 0
    if rgb.ndim != 3 or rgb.shape[0] < 200 or rgb.shape[1] < 120:
        return rgb, 0, 0
    H, W = rgb.shape[:2]
    g = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY).astype(np.int16)
    row_ink = ((g < 150).mean(axis=1))

    # derive per-line bands: prefer detector text boxes, else find full-width
    # text-ink runs
    lines = []  # (y1, y2, width_frac)
    if text_boxes:
        for tb in text_boxes:
            x1, y1, x2, y2 = int(tb[0]), int(tb[1]), int(tb[2]), int(tb[3])
            y1 = max(0, min(H, y1)); y2 = max(0, min(H, y2))
            if y2 - y1 >= 4:
                lines.append((y1, y2, (x2 - x1) / max(1.0, W)))
    else:
        inked = row_ink > 0.05
        i = 0
        while i < H:
            if not inked[i]:
                i += 1; continue
            j = i
            while j < H and inked[j]:
                j += 1
            # estimate this line's width span from the middle row
            mid = (i + j) // 2
            cols = np.where(g[mid] < 150)[0]
            wf = (cols[-1] - cols[0]) / max(1.0, W) if len(cols) else 0.0
            lines.append((i, j, wf))
            i = j
    lines = [(a, b, wf) for (a, b, wf) in lines if wf >= 0.48 and 4 <= (b - a) <= 0.14 * H]
    if len(lines) < 2:
        return rgb, 0, 0
    lines.sort()

    def _edge_stack(near_bottom: bool):
        cand = sorted(lines, key=lambda t: -t[0] if near_bottom else t[0])
        stack = [cand[0]]
        for ln in cand[1:]:
            top = min(stack, key=lambda t: t[0])
            bot = max(stack, key=lambda t: t[1])
            if near_bottom and 0 <= top[0] - ln[1] <= 30:
                stack.append(ln)
            elif (not near_bottom) and 0 <= ln[0] - bot[1] <= 30:
                stack.append(ln)
            else:
                break
        if len(stack) < 2:
            return None
        s0 = min(t[0] for t in stack)
        s1 = max(t[1] for t in stack)
        cap = int(max_frac * H)
        if near_bottom:
            if H - s1 > 24 or (H - s0) > cap:
                return None
            k = s0 - 1
            if k > 3 and not (row_ink[max(0, k - 5):k + 1].mean() < 0.05):
                return None
            return ("bottom", s0)
        else:
            if s0 > 24 or s1 > cap:
                return None
            k = s1 + 1
            if k < H - 4 and not (row_ink[k:min(H, k + 6)].mean() < 0.05):
                return None
            return ("top", s1)

    top_rm = bot_rm = 0
    b = _edge_stack(near_bottom=True)
    if b:
        bot_rm = H - b[1]
        rgb = rgb[:b[1]]
    if rgb.shape[0] > 200:
        # recheck top edge on the possibly-shortened crop
        H2 = rgb.shape[0]
        t = None
        tl = [(a, bb, wf) for (a, bb, wf) in lines if bb <= H2]
        if len(tl) >= 2:
            saved = lines
            lines = tl
            row_ink = ((cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY).astype(np.int16) < 150).mean(axis=1))
            H = H2
            t = _edge_stack(near_bottom=False)
            lines = saved
        if t:
            top_rm = t[1]
            rgb = rgb[top_rm:]
    return rgb, top_rm, bot_rm


def _trim_edge_whitespace(rgb, keep=36):
    """Drop leading / trailing full-width near-pure white or black rows down
    to a `keep`-px margin. Unlike _border_trim_amounts this is UNCAPPED: the
    conservative strip cutter puts its cut at the midpoint of a gutter, so a
    panel can inherit hundreds of px of pure gutter on an edge, and that is
    never content. Returns (trimmed_rgb, rows_removed_from_top)."""
    if rgb.ndim != 3 or rgb.shape[0] < 80:
        return rgb, 0
    g = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY)
    H = g.shape[0]
    bar = (((g >= 244).mean(axis=1) >= 0.985) | ((g <= 14).mean(axis=1) >= 0.985))
    t = 0
    while t < H and bar[t]:
        t += 1
    b = 0
    while b < H and bar[H - 1 - b]:
        b += 1
    t = max(0, t - keep)
    b = max(0, b - keep)
    if t + b >= H - 40:
        return rgb, 0
    return rgb[t:H - b], t


def _tall_display_window(rgb, max_aspect=2.5, target_aspect=1.85):
    """Pick the vertical sub-window of a very tall grouped panel that best
    shows the DRAWN ART, so the on-screen frame is a readable panel instead
    of a hair-thin centre ribbon. The OCR crop stays the full height, so no
    dialogue is lost from the narration — a bubble that scrolls off the
    displayed frame is still transcribed and spoken.

    Returns (y0, y1). Falls back to the whole crop when the panel isn't tall,
    or has no clear art concentration (a genuine tall scroll shot)."""
    if os.environ.get("RECAP_STRIP_TALL_WINDOW", "1").lower() in ("0", "false", "no"):
        return 0, rgb.shape[0]
    H, W = rgb.shape[:2]
    if rgb.ndim != 3 or H <= int(max_aspect * W):
        return 0, H
    win = int(target_aspect * W)
    if win >= H:
        return 0, H
    g = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY).astype(np.int16)
    # an "art" row is substantially non-white across its width; a speech
    # bubble reads as a mostly-white row (thin outline + a little text), so
    # this weights real drawn panels far above floating dialogue
    art = (g < 232).mean(axis=1)
    art = np.clip((art - 0.30) / 0.40, 0.0, 1.0)          # soft threshold ~0.30
    k = 41
    dens = np.convolve(art, np.ones(k, np.float32) / k, mode="same")
    csum = np.concatenate([[0.0], np.cumsum(dens)])
    best_s, best_v = 0, -1.0
    for s in range(0, H - win + 1, 12):
        v = float(csum[s + win] - csum[s])
        if v > best_v:
            best_v, best_s = v, s
    if best_v <= 0.02 * win:
        return 0, H
    y0, y1 = best_s, best_s + win
    # nudge each edge off the middle of an ink run so the visible frame
    # doesn't slice cleanly through a bubble / face
    lowink = art < 0.12
    for _ in range(1):
        if y0 > 0 and not lowink[y0]:
            cand = np.where(lowink[max(0, y0 - 180):y0 + 1])[0]
            if len(cand):
                y0 = max(0, y0 - 180) + int(cand[-1])
        if y1 < H and not lowink[min(H - 1, y1)]:
            cand = np.where(lowink[y1:min(H, y1 + 180)])[0]
            if len(cand):
                y1 = y1 + int(cand[0])
    return max(0, y0), min(H, y1)


def _frame_reconstructed_strip(cfg, chapter, out_dir):
    """Reconstruct the chapter strip, cut it whole, emit one frame per panel."""
    from PIL import Image
    strip, spans = _reconstruct_strip(chapter.panel_paths)
    if strip is None:
        return []
    H, W = strip.shape[:2]
    gray = cv2.cvtColor(strip, cv2.COLOR_RGB2GRAY)
    log.info("[%s] reconstructed strip %dx%d from %d chunks", chapter.tag, W, H, len(chapter.panel_paths))
    try:
        tb = _detect_text_boxes(gray)
        texts = [(int(a), int(c_), int(b_), int(d_), 0.9) for (a, c_, b_, d_) in tb]
    except Exception:
        texts = []
    try:
        _t0 = time.time()
        nocut = _face_row_mask(strip, H)
        log.info("[%s] face no-cut mask over %.1fs (%d guarded rows)", chapter.tag,
                 time.time() - _t0, int(np.count_nonzero(nocut)))
    except Exception as exc:
        log.warning("[%s] face no-cut detection failed (%s) — gutter-only guard", chapter.tag, exc)
        nocut = None
    boxes = _cut_strip_into_panels(gray, texts, W, H, nocut=nocut)

    def _page_for(y):
        for (nm, y0, y1) in spans:
            if y0 <= y < y1:
                return nm, y0
        return (spans[-1][0], spans[-1][1]) if spans else ("001.jpg", 0)

    entries, counter = [], 0
    for (x1, y1, x2, y2) in boxes:
        crop = strip[max(0, y1):min(H, y2), max(0, x1):min(W, x2)]
        t, b, l, r = _border_trim_amounts(crop)
        if (t or b or l or r) and crop.shape[0] - t - b >= 24:
            crop = crop[t:crop.shape[0] - b, l:crop.shape[1] - r]
            y1 += t
        crop, _ct = _trim_edge_whitespace(crop)
        y1 += _ct
        crop = _squeeze_internal_whitespace(crop)
        gc = cv2.cvtColor(crop, cv2.COLOR_RGB2GRAY)
        if _is_blank_crop(gc) or crop.shape[0] < 24 or crop.shape[1] < 24:
            continue
        pi = int(spans and next((k for k, (_n, a, bb) in enumerate(spans) if a <= y1 < bb), 0))
        if (pi <= 1 or pi >= len(chapter.panel_paths) - 2) and _looks_like_credits_panel(crop):
            log.info("[%s] strip: skipped credits panel near chunk %d", chapter.tag, pi + 1)
            continue
        # the displayed frame focuses on the art of a very tall grouped panel;
        # OCR still sees the whole crop so every bubble is transcribed
        dw0, dw1 = _tall_display_window(crop)
        disp = crop[dw0:dw1] if (dw0, dw1) != (0, crop.shape[0]) else crop
        # trim a burned-on aggregator watermark stack from the displayed frame
        # only (the OCR crop `oc` below keeps it, so narration is unaffected)
        _ch0 = disp.shape[0]
        _cy = y1 + dw0
        _tl = [(int(t[0]) - x1, int(t[1]) - _cy, int(t[2]) - x1, int(t[3]) - _cy) for t in texts]
        _tl = [(max(0, a), max(0, b), min(disp.shape[1], c), min(disp.shape[0], d))
               for (a, b, c, d) in _tl if b < disp.shape[0] and d > 0 and c > a and d > b]
        disp, _wt, _wb = _strip_edge_watermark(disp, text_boxes=_tl or None)
        if (_wt or _wb) and disp.shape[0] >= 24:
            log.info("[%s] frame %d: trimmed watermark (top %d, bot %d)", chapter.tag, counter, _wt, _wb)
        elif disp.shape[0] < 24:
            disp = crop[dw0:dw1] if (dw0, dw1) != (0, crop.shape[0]) else crop
        fp = out_dir / f"frame_{counter:05d}.jpg"
        _compose_canvas(Image.fromarray(disp)).save(fp, quality=92)
        ocr_path = ""
        if _OCR_FRAMES_ENABLED:
            ocr_fp = out_dir / f"frame_{counter:05d}_ocr.jpg"
            try:
                # OCR crop: aim the WIDTH at the target (text legibility scales
                # with column width, not the long side) and only clamp height
                # for a genuinely giant panel — scaling a tall grouped panel by
                # its long side crushed the text to an unreadable sliver.
                oc = crop
                tgt = int(os.environ.get("RECAP_OCR_MAX_SIDE", "1100"))
                hh, ww = oc.shape[:2]
                s = tgt / max(1, ww)
                if hh * s > tgt * 6:
                    s = (tgt * 6) / max(1, hh)
                if abs(s - 1.0) > 0.05:
                    oc = cv2.resize(oc, (max(1, int(ww * s)), max(1, int(hh * s))),
                                    interpolation=cv2.INTER_AREA if s < 1 else cv2.INTER_CUBIC)
                Image.fromarray(oc).save(ocr_fp, quality=94)
                ocr_path = str(ocr_fp.resolve())
            except Exception:
                ocr_path = ""
        nm, y0 = _page_for(y1)
        entries.append(FrameEntry(
            frame_id=f"{chapter.tag}_frame_{counter:05d}",
            filename=fp.name, path=str(fp.resolve()), ocr_path=ocr_path,
            source_page=nm, source_index=pi, frame_kind="scroll_frame",
            source_box=[int(x1), int(max(0, y1 - y0)), int(x2), int(y2 - y0)],
        ))
        counter += 1
    log.info("[%s] strip reconstruction: %d chunks -> %d panel frames", chapter.tag,
             len(chapter.panel_paths), len(entries))
    _slice_qa_check(chapter.tag, entries, [])
    return entries


def _frame_pages_reference_style(cfg: "PipelineConfig", chapter: "Chapter",
                                 out_dir: Path) -> List["FrameEntry"]:
    """Reference-style framing: detect the real comic panels on every page
    (see _detect_page_panels) and emit ONE frame per panel, contain-fit over
    a blurred backdrop — matching the reference recap (one whole panel with
    its bubbles per on-screen beat, in reading order).

    Webtoon hosts slice a chapter into fixed-height chunk 'pages' at arbitrary
    pixel rows, so a panel often straddles a mid-artwork seam and is split
    across two files. When the bottom panel of page N and the top panel of
    page N+1 are both flush with that shared edge and the seam cuts through
    art, the two halves are stitched and emitted as ONE frame — never cut."""
    from PIL import Image

    # Aggregators (mgeko, toonily, mangapill, …) serve a chapter as individual
    # ~760x850 panel TILES, not a raw tall strip. On those, panel detection +
    # borderless split + edge-trim fragments clean panels and crops through
    # faces — pass each tile straight through instead.
    if _pages_are_presliced_tiles(chapter.panel_paths):
        log.info("[%s] source pages look pre-sliced into panel tiles — using passthrough framing", chapter.tag)
        return _frame_presliced_tiles(cfg, chapter, out_dir)

    # Chunked webtoon: glue the arbitrary chunks back into the original strip
    # and cut the whole thing, so the cutter never sees a half-panel. NOT for
    # tiles (already handled above). RECAP_STRIP_RECONSTRUCT forces it on/off.
    _sr = os.environ.get("RECAP_STRIP_RECONSTRUCT", "auto").lower()
    if _sr not in ("0", "false", "no") and (
            _sr in ("1", "true", "yes")
            or _pages_are_webtoon_chunks(chapter.panel_paths)
            or _pages_are_webtoon_strip(chapter.panel_paths)):
        log.info("[%s] webtoon strip — reconstructing full column before slicing", chapter.tag)
        _r = _frame_reconstructed_strip(cfg, chapter, out_dir)
        if _r:
            return _r
        log.warning("[%s] strip reconstruction produced nothing — falling back to per-page", chapter.tag)

    # 1. detect panels on every page, note which touch the top/bottom edge.
    # This is the CPU-bound half of framing (image decode + YOLO panel detect
    # + RT-DETR text detect per page) and every page is independent, so run it
    # across a small thread pool — the ONNX sessions (_panel_yolo, text
    # detector) are shared and their .run() is thread-safe. cv2/PIL release
    # the GIL. The seam-stitch/emit pass below stays serial (it needs pages in
    # order and shares a frame counter). RECAP_FRAME_WORKERS overrides (1 =
    # back to serial). Measured ~3x on this leg on the 4-core box.
    total = len(chapter.panel_paths)
    _fw = max(1, int(os.environ.get("RECAP_FRAME_WORKERS", "3")))

    def _scan_page(item):
        page_idx, page_path = item
        try:
            with Image.open(page_path) as im:
                rgb = np.array(im.convert("RGB"))
        except Exception as exc:
            log.warning("[%s] skipping unreadable page %s: %s", chapter.tag, page_path.name, exc)
            return None
        h, w = rgb.shape[:2]
        gray = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY)
        dets = []
        for (x1, y1, x2, y2) in _detect_page_panels(Image.fromarray(rgb)):
            dets.append(((int(x1), int(y1), int(x2), int(y2)),
                         y1 <= 0.012 * h, y2 >= 0.988 * h))
        return [page_idx, page_path.name, rgb, gray, dets]

    if _fw > 1 and total > 1:
        # warm the lazy-init detector singletons once, serially, so the pool
        # threads don't race on first construction
        _detect_page_panels(Image.fromarray(np.zeros((32, 32, 3), dtype=np.uint8)))
        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor(max_workers=min(_fw, total)) as _ex:
            pages = [p for p in _ex.map(_scan_page, list(enumerate(chapter.panel_paths))) if p is not None]
    else:
        pages = [p for p in (_scan_page(it) for it in enumerate(chapter.panel_paths)) if p is not None]

    seam_stitch = (os.environ.get("RECAP_SEAM_STITCH", "1").lower() not in ("0", "false", "no")
                   and _pages_are_webtoon_chunks(chapter.panel_paths))

    entries: List[FrameEntry] = []
    counter = 0

    def _emit(crop_rgb, page_idx, page_name, src_box=None):
        nonlocal counter
        # Drop ONLY pure letterbox (near-white / near-black full-width bands),
        # capped at 10% per side. The old `< 234` ink-density trim shaved the
        # edges off coloured panels, SFX and faces — the exact "cuts through
        # content" complaint. `_safe_border_trim` never touches coloured art.
        h0, w0 = crop_rgb.shape[:2]
        t, b, l, r = _border_trim_amounts(crop_rgb)
        if (t or b or l or r) and (h0 - t - b) >= 24 and (w0 - l - r) >= 24:
            if src_box is not None:
                bx1, by1, _bx2, _by2 = src_box
                src_box = [int(bx1 + l), int(by1 + t),
                           int(bx1 + w0 - r), int(by1 + h0 - b)]
            crop_rgb = crop_rgb[t:h0 - b, l:w0 - r]
        elif src_box is not None:
            src_box = [int(v) for v in src_box]
        arr_gray = cv2.cvtColor(crop_rgb, cv2.COLOR_RGB2GRAY)
        if _is_blank_crop(arr_gray) or crop_rgb.shape[0] < 24 or crop_rgb.shape[1] < 24:
            return
        if (page_idx <= 1 or page_idx >= total - 2) and _looks_like_credits_panel(crop_rgb):
            log.info("[%s] skipped credits / notes panel on page %d", chapter.tag, page_idx + 1)
            return
        fp = out_dir / f"frame_{counter:05d}.jpg"
        _compose_canvas(Image.fromarray(crop_rgb)).save(fp, quality=92)
        # OCR reads this tight raw-pixel crop, NOT the composed canvas: the
        # canvas contain-fits a tall panel to a small centred strip and rings
        # it with a blurred copy of itself, both of which wreck recognition.
        # (deleted again by _ocr_frames_into_narration_json once OCR has run)
        ocr_path = ""
        if _OCR_FRAMES_ENABLED:
            ocr_fp = out_dir / f"frame_{counter:05d}_ocr.jpg"
            try:
                oc = crop_rgb
                # Normalise the OCR crop's long side to RECAP_OCR_MAX_SIDE
                # (default 1100). Bench on this box: RapidOCR is 427 ms/frame
                # at 1500 px vs 293 ms at 1100 vs 203 at 900 — image size is
                # the dominant cost, and PP-OCRv5-mobile's detector runs at
                # ~960 px internally anyway, so 1100 keeps recognition detail
                # while cutting OCR wall time ~1.5x. Crucially this now also
                # DOWNSCALES oversized crops (a 3000 px tall webtoon panel used
                # to be OCR'd at full height — the real worst case).
                target = int(os.environ.get("RECAP_OCR_MAX_SIDE", "1100"))
                m = max(oc.shape[:2])
                if m > 0 and abs(m - target) / target > 0.05:
                    s = target / m
                    interp = cv2.INTER_AREA if s < 1 else cv2.INTER_CUBIC
                    oc = cv2.resize(oc, (max(1, int(oc.shape[1] * s)),
                                         max(1, int(oc.shape[0] * s))),
                                    interpolation=interp)
                Image.fromarray(oc).save(ocr_fp, quality=94)
                ocr_path = str(ocr_fp.resolve())
            except Exception:
                ocr_path = ""
        entries.append(FrameEntry(
            frame_id=f"{chapter.tag}_frame_{counter:05d}",
            filename=fp.name, path=str(fp.resolve()), ocr_path=ocr_path,
            source_page=page_name, source_index=page_idx, frame_kind="panel",
            source_box=list(src_box) if src_box is not None else None,
        ))
        counter += 1

    def _page_is_backmatter(gray_pg) -> bool:
        # a title / "To Be Continued" / staff-credits page: overwhelmingly
        # white with only a little scattered ink (a logo + a few text lines),
        # never a big filled art region
        white = float((gray_pg >= 236).mean())
        ink = float((gray_pg < 120).mean())
        if white < 0.86 or ink > 0.06:
            return False
        row_ink = (gray_pg < 120).mean(axis=1)
        return float((row_ink >= 0.02).mean()) <= 0.35

    consumed_first = set()   # (page_idx) whose first panel was already merged upward
    for pi in range(len(pages)):
        page_idx, name, rgb, gray, dets = pages[pi]
        h, w = gray.shape
        pad_x, pad_y = round(w * 0.006), round(h * 0.004)
        if (page_idx <= 1 or page_idx >= total - 2) and _page_is_backmatter(gray):
            log.info("[%s] skipped front/back-matter page %d", chapter.tag, page_idx + 1)
            continue
        for di, (box, clip_top, clip_bot) in enumerate(dets):
            x1, y1, x2, y2 = box
            if di == 0 and pi in consumed_first:
                continue
            # --- seam stitch: last panel of this page is edge-flush and the
            #     next page opens with an edge-flush panel across a mid-art seam
            if (seam_stitch and di == len(dets) - 1 and clip_bot and pi + 1 < len(pages)
                    and _seam_is_midart(gray, pages[pi + 1][3])):
                nrgb, ndets = pages[pi + 1][2], pages[pi + 1][4]
                nh = nrgb.shape[0]
                # merge ONLY a genuine split — one side is a spillover fragment
                # (< 55% of its page). Two full-height panels that merely touch
                # the shared edge are separate beats; leave them per-page so
                # each OCRs on its own tight crop.
                frag = ndets and ndets[0][1] and (
                    (y2 - y1) < 0.55 * h or (ndets[0][0][3] - ndets[0][0][1]) < 0.55 * nh)
                if frag:
                    (nx1, ny1, nx2, ny2), _, n_clip_bot = ndets[0]
                    # union across the stitched pair (2nd half offset by page h)
                    ux1, uy1 = min(x1, nx1), y1
                    ux2 = max(x2, nx2)
                    stitched = np.concatenate([rgb, nrgb], axis=0)
                    uy2 = h + ny2
                    cx1 = max(0, ux1 - pad_x); cy1 = max(0, uy1 - pad_y)
                    cx2 = min(w, ux2 + pad_x); cy2 = min(stitched.shape[0], uy2 + pad_y)
                    merged_crop = stitched[cy1:cy2, cx1:cx2]
                    # only accept the merge if the two halves are truly one
                    # image across the seam — a wide near-white band right at
                    # the join means they are separate panels; emit apart.
                    seam_rows = cv2.cvtColor(
                        merged_crop[max(0, h - cy1 - 12):max(1, h - cy1 + 12)],
                        cv2.COLOR_RGB2GRAY) if 12 < h - cy1 < merged_crop.shape[0] else None
                    if seam_rows is None or (seam_rows >= 238).mean() < 0.75:
                        _emit(merged_crop, page_idx, name)
                        consumed_first.add(pi + 1)
                        continue
            if _INCLUSIVE_SLICE:
                prev_y2 = int(dets[di - 1][0][3]) if di > 0 else 0
                next_y1 = int(dets[di + 1][0][1]) if di < len(dets) - 1 else h
                cx1, cy1, cx2, cy2 = _inclusive_crop_box(gray, box, prev_y2, next_y1, w, h)
            else:
                cx1 = max(0, x1 - pad_x); cy1 = max(0, y1 - pad_y)
                cx2 = min(w, x2 + pad_x); cy2 = min(h, y2 + pad_y)
            if cx2 - cx1 < w * 0.12 or cy2 - cy1 < h * 0.02:
                continue
            _emit(rgb[cy1:cy2, cx1:cx2], page_idx, name, src_box=(cx1, cy1, cx2, cy2))

    log.info("[%s] reference-style framing: %d pages -> %d panel frames",
             chapter.tag, total, len(entries))
    _slice_qa_check(chapter.tag, entries, pages)
    return entries


def _slice_qa_check(tag: str, entries: "List[FrameEntry]", pages) -> None:
    """Sanity-score a chapter's slice result and WARN on pathological layouts
    (borrowed from the zainrana558/slicer QA-scorer idea). Purely advisory —
    it never changes the frames — but a loud log line on a chapter that sliced
    badly lets a 100-chapter batch be caught before it wastes hours. Silenced
    with RECAP_SLICE_QA=0."""
    if os.environ.get("RECAP_SLICE_QA", "1").lower() in ("0", "false", "no"):
        return
    n = len(entries)
    if n == 0:
        log.warning("[%s] SLICE QA: 0 panels emitted — the chapter will be empty", tag)
        return
    try:
        page_h = [p[2].shape[0] for p in pages if p and p[2] is not None] if pages else []
    except Exception:
        page_h = []
    if not page_h:
        # tile-passthrough (no page scan): score on panel count + sliver ratio only
        hs = [(b[3] - b[1]) for e in entries if (b := e.source_box) and len(b) == 4]
        slivers = sum(1 for h in hs if h < 120)
        if slivers > max(3, 0.30 * n):
            log.warning("[%s] SLICE QA: %d/%d sliver panels (<120px)", tag, slivers, n)
        else:
            log.info("[%s] SLICE QA: ok (%d panels, passthrough)", tag, n)
        return
    total_h = float(sum(page_h)) or 1.0
    heights, widths = [], []
    for e in entries:
        b = e.source_box
        if b and len(b) == 4:
            heights.append(b[3] - b[1])
            widths.append(b[2] - b[0])
    if not heights:
        return
    covered = float(sum(heights))
    coverage = covered / total_h
    per_page = n / max(1, len(page_h))
    slivers = sum(1 for h in heights if h < 120)
    giants = sum(1 for h, w in zip(heights, widths) if w > 0 and h > 4.0 * w)
    issues = []
    if coverage < 0.28:
        issues.append(f"low art coverage {coverage:.0%} — panels likely being MISSED")
    if coverage > 1.15:
        issues.append(f"coverage {coverage:.0%} — panels overlapping / double-counted")
    if per_page < 1.2:
        issues.append(f"only {per_page:.1f} panels/page — under-segmenting (beats glued together)")
    if slivers > max(3, 0.30 * n):
        issues.append(f"{slivers}/{n} sliver panels (<120px) — over-segmenting")
    if giants:
        issues.append(f"{giants} panel(s) taller than 4x their width — probably an unsplit multi-beat block")
    if issues:
        log.warning("[%s] SLICE QA: %s", tag, " | ".join(issues))
    else:
        log.info("[%s] SLICE QA: ok (%d panels, %.0f%% coverage, %.1f/page)",
                 tag, n, coverage * 100, per_page)


_VISUAL_PROMPT = (
    "Caption this manhwa artwork for an audio recap. Reply with ONE sentence, "
    "max 18 words, present tense, describing only the physical action and mood "
    "— e.g. 'A swordsman lunges as shadowy figures surround him.' "
    "Rules: start with a noun ('A ...', 'Two ...', 'The ...'). Refer to people "
    "as he/she/they or by role. Do NOT quote or read any text. Do NOT use the "
    "words image, picture, panel, scene, comic, manhwa, artwork, illustration, "
    "shows, depicts, features. If it is only a logo, credits, an ad, a title "
    "card, or blank, reply exactly: SKIP"
)


_smolvlm_cache: "dict" = {}


def _get_smolvlm():
    """Lazy-load SmolVLM2-500M (Apache-2.0, HF-native) for local, key-free panel
    captioning. Returns (model, processor) or None. ~3.5 s/panel on this 4-vCPU
    box WHEN the processor's longest_edge is pinned to 512 — the default 2048
    tiles each frame into a 4x4 grid and blows per-panel latency to ~30 s.

    First call downloads ~500 MB to the HF cache. Any failure (transformers
    missing, num2words missing, OOM, download blocked) returns None and the
    caller falls through to its next provider."""
    if "v" in _smolvlm_cache:
        return _smolvlm_cache["v"]
    _smolvlm_cache["v"] = None
    model_id = os.environ.get("RECAP_SMOLVLM_MODEL", "HuggingFaceTB/SmolVLM2-500M-Video-Instruct")
    edge = int(os.environ.get("RECAP_SMOLVLM_EDGE", "512"))
    try:
        _cap_torch_threads()
        import torch
        from transformers import AutoModelForImageTextToText, AutoProcessor
        proc = AutoProcessor.from_pretrained(model_id, size={"longest_edge": edge})
        model = AutoModelForImageTextToText.from_pretrained(
            model_id, dtype=torch.float32, _attn_implementation="eager").eval()
        _smolvlm_cache["v"] = (model, proc, edge)
        log.info("Loaded SmolVLM2 local caption model (%s, longest_edge=%d)", model_id, edge)
    except Exception as exc:
        log.warning("SmolVLM2 load failed (%s) — local captioning unavailable "
                    "(pip install num2words if that is the error)", exc)
        _smolvlm_cache["v"] = None
    return _smolvlm_cache["v"]


def _resolve_visual_client(cfg: "PipelineConfig"):
    """Return (call_fn, label) where call_fn(jpeg_bytes)->str produces a one-line
    visual caption, or (None, 'none') if no vision engine is available.

    Precedence for provider='auto': a cloud key if the user supplied one
    (fast), else — only when RECAP_VISUAL_LOCAL=1 — local SmolVLM2, else
    nothing (local models are ~3.5 s/panel so they stay opt-in).
    """
    import base64 as _b64
    import json as _json
    import urllib.request

    prov = (cfg.visual_provider or "auto").lower()
    groq_key = cfg.groq_api_key or os.environ.get("GROQ_API_KEY")
    gem_key = cfg.gemini_api_key or os.environ.get("GEMINI_API_KEY")
    orouter_key = cfg.openrouter_api_key or os.environ.get("OPENROUTER_API_KEY")
    ollama_base = os.environ.get("OLLAMA_BASE_URL", "http://localhost:11434")

    def _ollama_up():
        try:
            urllib.request.urlopen(ollama_base + "/api/tags", timeout=3).read()
            return True
        except Exception:
            return False

    if prov == "auto":
        # 'auto' deliberately does NOT fall through to local Ollama: on a
        # GPU-less box llava/moondream run ~20-70s PER PANEL, which turns even
        # a 3-chapter job into hours. A cloud free-tier key (Groq / Gemini) is
        # ~1-2s/panel. With no key, 'auto' means "off" — the user must pick
        # 'ollama' explicitly (and accept the wait) to caption locally.
        if groq_key:
            prov = "groq"
        elif gem_key:
            prov = "gemini"
        elif orouter_key:
            prov = "openrouter"
        elif os.environ.get("RECAP_VISUAL_LOCAL", "0").lower() in ("1", "true", "yes"):
            prov = "smolvlm"
        else:
            log.warning("--describe-visuals: no cloud vision key (GROQ/GEMINI/"
                        "OPENROUTER) — skipping. Use visual_provider=smolvlm (local "
                        "SmolVLM2, ~3.5s/panel) or =ollama to caption without a key.")
            return None, "none"

    if prov == "none":
        return None, "none"

    if prov == "smolvlm":
        loaded = _get_smolvlm()
        if not loaded:
            return None, "none"
        model, proc, _edge = loaded
        import torch
        _max_new = int(os.environ.get("RECAP_SMOLVLM_TOKENS", "48"))
        # SmolVLM2-500M parrots few-shot examples and drowns in long negative
        # rule lists — the elaborate _VISUAL_PROMPT makes it worse, not better.
        # A short direct instruction gives the cleanest output; the regex
        # post-processing in _describe_frames strips any "comic/panel" framing.
        _prompt = os.environ.get("RECAP_SMOLVLM_PROMPT") or (
            "Describe what is happening in this scene in one short sentence. "
            "Focus on the characters and their action or expression. "
            "Do not mention comics, panels, or art style.")

        def _call(jpeg: bytes) -> str:
            from PIL import Image
            import io as _io
            im = Image.open(_io.BytesIO(jpeg)).convert("RGB")
            msgs = [{"role": "user", "content": [
                {"type": "image", "image": im},
                {"type": "text", "text": _prompt},
            ]}]
            inp = proc.apply_chat_template(
                msgs, add_generation_prompt=True, tokenize=True,
                return_dict=True, return_tensors="pt")
            with torch.no_grad():
                ids = model.generate(**inp, do_sample=False, max_new_tokens=_max_new)
            txt = proc.batch_decode(
                ids[:, inp["input_ids"].shape[-1]:], skip_special_tokens=True)[0].strip()
            # keep just the first sentence — the model tends to ramble a second.
            m = re.match(r"^(.+?[.!?])(?:\s|$)", txt)
            return (m.group(1) if m else txt).strip()

        return _call, f"smolvlm/{os.environ.get('RECAP_SMOLVLM_MODEL', 'SmolVLM2-500M')}"

    if prov == "ollama":
        if not _ollama_up():
            log.warning("--describe-visuals: Ollama not reachable at %s — skipping", ollama_base)
            return None, "none"
        # moondream (1.8B, ~20s/panel) is faster than llava:7b (~70s/panel) on
        # CPU but its captions were unreliable in testing; llava is the default
        # despite the cost. RECAP_VISUAL_MODEL overrides. Either way this is an
        # "leave it running" path on a GPU-less box — see RECAP_VISUAL_MAX.
        model = cfg.visual_model or os.environ.get("RECAP_VISUAL_MODEL", "llava:7b")

        def _call(jpeg: bytes) -> str:
            body = _json.dumps({
                "model": model,
                "prompt": _VISUAL_PROMPT,
                "images": [_b64.b64encode(jpeg).decode()],
                "stream": False,
                "options": {"temperature": 0.2, "num_predict": 60},
            }).encode()
            req = urllib.request.Request(ollama_base + "/api/generate", data=body,
                                        headers={"Content-Type": "application/json"})
            with urllib.request.urlopen(req, timeout=180) as r:
                return (_json.load(r).get("response") or "").strip()

        return _call, f"ollama/{model}"

    # cloud: all OpenAI-chat-compatible (image_url data URI)
    try:
        from openai import OpenAI
    except Exception:
        return None, "none"
    if prov == "groq":
        client = OpenAI(api_key=groq_key, base_url=GROQ_BASE_URL)
        model = cfg.visual_model or "meta-llama/llama-4-scout-17b-16e-instruct"
    elif prov == "gemini":
        client = OpenAI(api_key=gem_key,
                        base_url="https://generativelanguage.googleapis.com/v1beta/openai/")
        model = cfg.visual_model or "gemini-2.0-flash"
    elif prov == "openrouter":
        client = OpenAI(api_key=orouter_key, base_url="https://openrouter.ai/api/v1")
        model = cfg.visual_model or "google/gemini-2.0-flash-exp:free"
    else:
        return None, "none"

    def _call(jpeg: bytes) -> str:
        uri = "data:image/jpeg;base64," + _b64.b64encode(jpeg).decode()
        resp = client.chat.completions.create(
            model=model, temperature=0.2, max_tokens=80,
            messages=[{"role": "user", "content": [
                {"type": "text", "text": _VISUAL_PROMPT},
                {"type": "image_url", "image_url": {"url": uri}},
            ]}],
        )
        return (resp.choices[0].message.content or "").strip()

    return _call, f"{prov}/{model}"


def _describe_frames(cfg: "PipelineConfig", chapter: "Chapter",
                     frame_entries: List["FrameEntry"], dialogue: List[str],
                     phase_cb=None) -> List[str]:
    """Return a visual caption (or "") per frame. Best-effort: any failure
    yields "" for that frame and the pipeline carries on as before.

    By default only frames with NO usable dialogue are captioned (that is
    exactly where the recap currently goes silent). RECAP_VISUAL_ALL=1
    captions every frame (visual context even under dialogue)."""
    from concurrent.futures import ThreadPoolExecutor
    from PIL import Image
    import io as _io

    call, label = _resolve_visual_client(cfg)
    if call is None:
        log.warning("[%s] --describe-visuals: no vision engine available "
                    "(no cloud key, Ollama not reachable) — skipping", chapter.tag)
        return [""] * len(frame_entries)

    caption_all = os.environ.get("RECAP_VISUAL_ALL", "0").lower() in ("1", "true", "yes")
    todo = [i for i, e in enumerate(frame_entries)
            if caption_all or not (dialogue[i] or "").strip()]
    if not todo:
        return [""] * len(frame_entries)

    is_local = label.startswith(("ollama", "smolvlm"))
    is_cloud = not is_local
    # Hard per-chapter cap so a mis-set local run can't balloon into hours.
    # Cloud is fast enough to leave effectively uncapped. Local defaults to
    # the first 40 silent panels/chapter; RECAP_VISUAL_MAX overrides (0 = no cap).
    _cap = int(os.environ.get("RECAP_VISUAL_MAX", "0" if is_cloud else "40"))
    if _cap and len(todo) > _cap:
        log.info("[%s] --describe-visuals: capping %d -> %d frames "
                 "(RECAP_VISUAL_MAX; raise it or use a cloud key for full coverage)",
                 chapter.tag, len(todo), _cap)
        todo = todo[:_cap]

    # SmolVLM2 is one in-process torch model — concurrent generate() calls just
    # thrash the same 4 cores and double memory, so pin it to 1 worker.
    _default_workers = "6" if is_cloud else ("1" if label.startswith("smolvlm") else "2")
    workers = max(1, int(os.environ.get("RECAP_VISUAL_WORKERS", _default_workers)))
    log.info("[%s] --describe-visuals: captioning %d/%d frames via %s (%d-way)",
             chapter.tag, len(todo), len(frame_entries), label, workers)

    def _prep(path: str) -> bytes:
        with Image.open(path) as im:
            im = im.convert("RGB")
            if max(im.size) > 768:            # small = faster + plenty for a caption
                im.thumbnail((768, 768), Image.LANCZOS)
            b = _io.BytesIO()
            im.save(b, format="JPEG", quality=85)
            return b.getvalue()

    out = [""] * len(frame_entries)
    t0 = time.time()

    def _one(i: int):
        e = frame_entries[i]
        try:
            # the FULL composed frame — not e.ocr_path, which is the tight
            # text-only crop used for OCR (captioning that would just re-read
            # the speech bubble).
            cap = call(_prep(e.path))
        except Exception as exc:
            log.debug("[%s] visual caption failed for frame %d (%s)", chapter.tag, i, exc)
            return
        cap = re.sub(r"\s+", " ", cap).strip().strip('"“”').strip()
        if not cap or cap.upper().startswith("SKIP") or len(cap) < 8:
            return
        # Models (llava especially) ignore "don't mention it's a comic" and
        # open with "The image is a comic book panel featuring X ..." or "This
        # panel shows X ...". Strip that framing clause down to X.
        cap = re.sub(
            r"^(the|this)\s+(image|panel|picture|artwork|art|scene|illustration|drawing|comic)"
            r"[^,.:;]*?(?:\b(?:show(?:s|ing|n)?|depict(?:s|ing)?|featur(?:es|ing)|"
            r"is|appears to (?:show|depict|be)|portrays?)\b)\s*",
            "", cap, flags=re.I).strip()
        cap = re.sub(r"^(?:a |an )?(?:comic |manhwa |manga |webtoon )?panel\s+(?:show(?:s|ing)?|of|with)\s+",
                     "", cap, flags=re.I).strip()
        cap = re.sub(r"\b(comic|manhwa|manga|webtoon)\s+(book\s+)?(panel|page|strip)\b", "scene", cap, flags=re.I)
        cap = cap.strip().strip('"“”,').strip()
        # drop a dangling half-sentence from num_predict truncation
        if len(cap) > 40 and cap[-1:] not in ".!?…":
            cut = max(cap.rfind("."), cap.rfind("!"), cap.rfind("?"))
            if cut > 20:
                cap = cap[:cut + 1]
        if cap and len(cap) >= 8:
            out[i] = cap[0].upper() + cap[1:]

    _done = [0]
    _n = len(todo)

    def _one_tracked(i):
        _one(i)
        _done[0] += 1
        if phase_cb and _done[0] % 5 == 0:
            try:
                phase_cb("visual", 0.55 + 0.44 * (_done[0] / max(1, _n)))
            except Exception:
                pass

    with ThreadPoolExecutor(max_workers=workers) as ex:
        list(ex.map(_one_tracked, todo))
    got = sum(1 for c in out if c)
    log.info("[%s] --describe-visuals: %d/%d captioned in %.1fs",
             chapter.tag, got, len(todo), time.time() - t0)
    return out


def _ocr_frames_into_narration_json(cfg: "PipelineConfig", chapter: "Chapter",
                                    frame_entries: List["FrameEntry"], phase_cb=None) -> bool:
    """OCR each composed frame with the local PaddleOCR/RapidOCR service and
    rewrite narration.json keyed by frame filename, so downstream narration is
    exactly this panel's transcribed words (word-for-word, per panel) instead
    of a whole page's text split proportionally. Returns True if it ran.

    OCR'ing the small framed panel is also markedly more accurate than OCR'ing
    a 4000px webtoon page. Skipped (keeping any existing narration.json) if the
    service is unreachable."""
    import json as _json
    import urllib.request

    if not _OCR_FRAMES_ENABLED:
        return False
    base = os.environ.get("OCR_SERVICE_URL", "http://localhost:3002")
    # prefer the tight raw crop (see _emit) — falls back to the composed canvas
    paths = [(e.ocr_path or e.path) for e in frame_entries]
    if not paths:
        return False
    try:
        _series = (getattr(cfg, "recap_title", None)
                   or os.environ.get("RECAP_OCR_SERIES")
                   or (cfg.input_dir.name if getattr(cfg, "input_dir", None) else ""))
        req = urllib.request.Request(
            f"{base}/ocr/batch",
            data=_json.dumps({"images": paths, "series": _series}).encode(),
            headers={"Content-Type": "application/json"},
        )
        with urllib.request.urlopen(req, timeout=max(120, len(paths) * 8)) as r:
            results = _json.load(r).get("results", [])
    except Exception as e:
        log.warning("[%s] per-frame OCR unavailable (%s) — keeping existing narration.json", chapter.tag, e)
        return False

    by_index = {int(x.get("index", i)): x for i, x in enumerate(results)}
    texts = []
    for i, e in enumerate(frame_entries):
        item = by_index.get(i, {})
        text = (item.get("text") or "").strip()
        status = item.get("status") or ("SUCCESS" if text else "NO_TEXT")
        texts.append([text, status])

    # A cut that ran through a speech bubble makes the SAME words tail frame N
    # and head frame N+1 ("…IS THAT GUY A" / "IS THAT GUY A STRONG HUNTER") —
    # spoken twice, and the second panel's audio starts on stale words. Drop
    # the duplicated run from the later frame's start.
    def _norm(w):
        return re.sub(r"[^a-z0-9]", "", w.lower())

    for i in range(len(texts) - 1):
        a, b = texts[i][0], texts[i + 1][0]
        if not a or not b:
            continue
        aw, bw = a.split(), b.split()
        best = 0
        for k in range(min(8, len(aw), len(bw)), 2, -1):
            if [_norm(w) for w in aw[-k:]] == [_norm(w) for w in bw[:k]]:
                best = k
                break
        if best:
            texts[i + 1][0] = " ".join(bw[best:]).strip()

    # OPTIONAL: fold in a one-line visual caption per panel so action panels
    # aren't just silence. Off unless --describe-visuals. The caption is
    # prepended to any dialogue ("He raises his blade. 'You will not pass.'")
    # and a caption-only panel flips NO_TEXT -> SUCCESS so it gets narrated.
    captions = None
    if getattr(cfg, "describe_visuals", False):
        if phase_cb:
            try:
                phase_cb("visual", 0.55)
            except Exception:
                pass
        try:
            captions = _describe_frames(cfg, chapter, frame_entries, [t[0] for t in texts], phase_cb=phase_cb)
        except Exception as exc:
            log.warning("[%s] --describe-visuals failed wholesale (%s) — OCR-only", chapter.tag, exc)
            captions = None

    narration = []
    for i, e in enumerate(frame_entries):
        text, status = texts[i]
        if not text and status == "SUCCESS":
            status = "NO_TEXT"
        visual = (captions[i] if captions else "") or ""
        if visual:
            cap = visual.rstrip(" .") + "."
            dlg = text.strip()
            if dlg:
                dlg_p = dlg if dlg[-1:] in ".!?…\"'”" else dlg + "."
                text = f"{cap} {dlg_p}"
            else:
                text = cap
            if status in ("NO_TEXT", "FAILED", "UNCERTAIN"):
                status = "SUCCESS"
        e.ocr_text, e.ocr_status = text, status
        entry = {"image": e.filename, "text": text, "status": status}
        if visual:
            entry["visual"] = visual
        narration.append(entry)

    (chapter.folder / "narration.json").write_text(_json.dumps(narration, indent=2), encoding="utf-8")
    chapter.image_narrations = {n["image"]: n for n in narration}
    got = sum(1 for n in narration if n["text"])
    vgot = sum(1 for n in narration if n.get("visual"))
    log.info("[%s] per-frame narration: %d/%d have text (%d with visual caption)",
             chapter.tag, got, len(narration), vgot)

    # the upscaled raw-crop OCR images have served their purpose — reclaim the space
    for e in frame_entries:
        if e.ocr_path and e.ocr_path != e.path:
            try:
                Path(e.ocr_path).unlink()
            except OSError:
                pass
            e.ocr_path = ""
    return True


def slice_chapter_panels(cfg: PipelineConfig, chapter: Chapter, phase_cb=None) -> List[tuple]:
    """
    Slice each source image into individual panel frames.

    `phase_cb(substage: str, frac: float)` — optional; called at the frame /
    ocr / visual sub-phase boundaries so a caller can drive a smooth progress
    bar through this (slow) step instead of only jumping at chapter edges.

    Default (RECAP_FRAME_MODE=page): one frame per source page, tall pages
    split on gutter rows — reproduces the reference recap style (whole
    panels with bubbles, blur-fill, no text-strip blow-ups).

    RECAP_FRAME_MODE=panel: the older contour/gutter-aware per-panel slicer.

    Each frame is composited onto a 1920x1080 canvas with blurred background
    fill (contain-fit).

    Returns list of (frame_path, source_panel_index) tuples in order.
    Resumable: if the chapter's slice folder has a valid manifest, reuse it.
    """
    from PIL import Image, ImageFilter

    out_dir = cfg.temp_slices_dir / chapter.tag
    manifest_path = out_dir / "manifest.json"

    is_valid, manifest, reason = validate_canonical_manifest(manifest_path, chapter, job_id=cfg.job_id)
    if is_valid and manifest:
        log.info("[%s] canonical manifest verified (%d frames, %s) — skipping slicing", chapter.tag, len(manifest.frames), reason)
        return [(Path(f.path if Path(f.path).exists() else out_dir / f.filename), f.source_index) for f in manifest.frames]

    log.info("[%s] manifest invalid or missing (%s) — slicing source pages into canonical frames", chapter.tag, reason)
    out_dir.mkdir(parents=True, exist_ok=True)

    def _ph(name, frac):
        if phase_cb:
            try:
                phase_cb(name, frac)
            except Exception:
                pass

    if os.environ.get("RECAP_FRAME_MODE", "page").lower() != "panel":
        _ph("frame", 0.0)
        frame_entries = _frame_pages_reference_style(cfg, chapter, out_dir)
        _ph("ocr", 0.40)
        _ocr_frames_into_narration_json(cfg, chapter, frame_entries, phase_cb=phase_cb)
        manifest = CanonicalManifest(
            manifest_version=MANIFEST_VERSION,
            job_id=cfg.job_id,
            chapter_tag=chapter.tag,
            source_pages=[p.name for p in chapter.panel_paths],
            frames=frame_entries,
        )
        manifest.save(manifest_path)
        return [(Path(f.path), f.source_index) for f in manifest.frames]

    frame_entries: List[FrameEntry] = []
    frame_counter = 0
    total_blank_skipped = 0
    detect_method_counts: Counter = Counter()

    for panel_idx, panel_path in enumerate(chapter.panel_paths):
        try:
            with Image.open(panel_path) as img:
                img = img.convert("RGB")
                w, h = img.size
                gray = cv2.cvtColor(np.array(img), cv2.COLOR_RGB2GRAY)

                panels, detect_method = _detect_panels_for_page(gray)
                log.debug("[%s] img %d: detected %d panel(s) via %s", chapter.tag, panel_idx, len(panels), detect_method)
                detect_method_counts[detect_method] += 1

                content_mask = _build_dilated_content_mask(gray)
                content_mask = _add_text_boxes_to_mask(content_mask, gray)

                merged_panel_boxes = []
                for (px, py, pw, ph) in panels:
                    if ph < 50 or pw < 50:
                        continue

                    safe_top = _snap_cut_to_safe_row(content_mask, py)
                    safe_bot = _snap_cut_to_safe_row(content_mask, py + ph)
                    if safe_bot - safe_top >= 50:
                        py, ph = safe_top, safe_bot - safe_top

                    px, py, pw, ph = _apply_dynamic_padding((px, py, pw, ph), content_mask, (h, w), padding_px=30)

                    crop_candidate = img.crop((px, py, px + pw, py + ph))
                    crop_candidate_gray = cv2.cvtColor(np.array(crop_candidate), cv2.COLOR_RGB2GRAY)

                    if _is_blank_crop(crop_candidate_gray) or _is_lines_only_crop(crop_candidate_gray):
                        total_blank_skipped += 1
                        continue

                    if _is_featureless_vfx(crop_candidate_gray):
                        if merged_panel_boxes:
                            prev_x, prev_y, prev_w, prev_h = merged_panel_boxes[-1]
                            new_y1 = min(prev_y, py)
                            new_y2 = max(prev_y + prev_h, py + ph)
                            new_x1 = min(prev_x, px)
                            new_x2 = max(prev_x + prev_w, px + pw)
                            merged_panel_boxes[-1] = (new_x1, new_y1, new_x2 - new_x1, new_y2 - new_y1)
                        else:
                            merged_panel_boxes.append((px, py, pw, ph))
                    else:
                        prev_box = merged_panel_boxes[-1] if merged_panel_boxes else None
                        prev_crop_gray = None
                        if prev_box is not None:
                            prev_crop_gray = cv2.cvtColor(
                                np.array(img.crop((prev_box[0], prev_box[1], prev_box[0] + prev_box[2], prev_box[1] + prev_box[3]))),
                                cv2.COLOR_RGB2GRAY,
                            )
                        if prev_box is not None and _is_featureless_vfx(prev_crop_gray):
                            prev_x, prev_y, prev_w, prev_h = merged_panel_boxes.pop()
                            new_y1 = min(prev_y, py)
                            new_y2 = max(prev_y + prev_h, py + ph)
                            new_x1 = min(prev_x, px)
                            new_x2 = max(prev_x + prev_w, px + pw)
                            merged_panel_boxes.append((new_x1, new_y1, new_x2 - new_x1, new_y2 - new_y1))
                        elif prev_box is not None and _crops_are_near_duplicate(prev_crop_gray, crop_candidate_gray):
                            prev_x, prev_y, prev_w, prev_h = merged_panel_boxes.pop()
                            new_y1 = min(prev_y, py)
                            new_y2 = max(prev_y + prev_h, py + ph)
                            new_x1 = min(prev_x, px)
                            new_x2 = max(prev_x + prev_w, px + pw)
                            merged_panel_boxes.append((new_x1, new_y1, new_x2 - new_x1, new_y2 - new_y1))
                        else:
                            merged_panel_boxes.append((px, py, pw, ph))

                # Fold detached caption/SFX strips into their panels and enforce
                # the per-page frame budget, so one source page can't explode
                # into a dozen frames (which the audio-timing floor then pads
                # into many seconds of near-silent, near-empty video).
                pre_consolidation = len(merged_panel_boxes)
                merged_panel_boxes = _consolidate_panel_boxes(
                    merged_panel_boxes, w, h, MAX_FRAMES_PER_PANEL
                )
                if len(merged_panel_boxes) != pre_consolidation:
                    log.debug("[%s] img %d: consolidated %d panel box(es) -> %d",
                              chapter.tag, panel_idx, pre_consolidation, len(merged_panel_boxes))

                for (px, py, pw, ph) in merged_panel_boxes:
                    crop = img.crop((px, py, px + pw, py + ph))
                    crop_arr = np.array(crop)
                    crop_gray = cv2.cvtColor(crop_arr, cv2.COLOR_RGB2GRAY)

                    # Clean stray boundary-edge fragments bleeding in from an
                    # adjacent panel (a solid near-black or near-white row
                    # within the first/last ~15px of the crop) BEFORE the
                    # blank-crop check and canvas composition. This is a
                    # narrower, distinct case from _compose_canvas's own
                    # whole-crop white-margin trim below: it catches a thin
                    # bleed-through strip (including dark border lines,
                    # which a white-only threshold can't catch), not a large
                    # accumulated gutter margin. Was implemented and tested
                    # (tests/test_image_slicing.py) but its only caller
                    # (_trim_white_borders) was dead code removed in an
                    # earlier cleanup pass, orphaning this function entirely
                    # -- rewiring it here instead of leaving it dead.
                    crop_arr, crop_gray = _clean_panel_boundary_edges(crop_arr, crop_gray)
                    crop = Image.fromarray(crop_arr)

                    if _is_blank_crop(crop_gray):
                        total_blank_skipped += 1
                        log.debug("[%s] img %d: skipping blank panel", chapter.tag, panel_idx)
                        continue

                    cw, ch = crop.size
                    # Threshold raised from 1.8 -- mathematically confirmed
                    # this was firing on ordinary tall panels, not just the
                    # "system/quest UI card" content it was meant for.
                    # _generate_ui_card_scroll_frames's own internal early
                    # return (`if window_h >= ch: return one frame`) can
                    # NEVER trigger for any crop that reaches it, because
                    # window_h is always crop_width * 0.5625 (a 16:9 ratio)
                    # and the caller only invokes it when ch/cw already
                    # exceeds this threshold -- so with the old 1.8 gate,
                    # every merged caption/panel crop with a remotely tall
                    # aspect ratio (extremely common in vertical webtoon
                    # scroll format, e.g. a standing character shot or a
                    # caption merged with the panel above/below it) was
                    # unconditionally sliced into 4 overlapping panning
                    # windows down its height instead of shown as one
                    # correctly-composited frame.
                    #
                    # Even at 3.0, real jobs kept showing the same bug for
                    # crops that legitimately exceed that ratio -- so
                    # _should_scroll_fragment additionally gates this on
                    # the text detector's own judgment: if a single
                    # detected text box already covers most of this
                    # crop's area, it IS essentially one caption/dialogue
                    # block, not a multi-element scrollable UI list,
                    # regardless of raw aspect ratio. See that function's
                    # own docstring for the full reasoning.
                    if _should_scroll_fragment(cw, ch, crop):
                        from PIL import Image as PILImage
                        # Tall UI/quest cards get sliced into several panning
                        # sub-frames for display. They all show fragments of
                        # ONE piece of text, so tag them with a shared
                        # scroll_group — OCR'ing (and narrating) each window
                        # separately would chop sentences at arbitrary pixel
                        # boundaries and read them as N disjoint, garbled
                        # clips instead of one continuous line.
                        group_id = f"{chapter.tag}_grp{frame_counter:05d}"
                        scroll_frames = _generate_ui_card_scroll_frames(crop, num_scroll_frames=4)
                        for s_frame in scroll_frames:
                            fp = out_dir / f"frame_{frame_counter:05d}.jpg"
                            s_frame.save(fp, quality=92)
                            frame_id = f"{chapter.tag}_frame_{frame_counter:05d}"
                            frame_entries.append(
                                FrameEntry(
                                    frame_id=frame_id,
                                    filename=fp.name,
                                    path=str(fp.resolve()),
                                    source_page=panel_path.name,
                                    source_index=panel_idx,
                                    frame_kind="scroll_frame",
                                    scroll_group=group_id,
                                )
                            )
                            frame_counter += 1
                    else:
                        from PIL import Image as PILImage
                        frame = _compose_canvas(PILImage.fromarray(crop_arr))
                        fp = out_dir / f"frame_{frame_counter:05d}.jpg"
                        frame.save(fp, quality=92)
                        frame_id = f"{chapter.tag}_frame_{frame_counter:05d}"
                        frame_entries.append(
                            FrameEntry(
                                frame_id=frame_id,
                                filename=fp.name,
                                path=str(fp.resolve()),
                                source_page=panel_path.name,
                                source_index=panel_idx,
                                frame_kind="panel",
                            )
                        )
                        frame_counter += 1
        except Exception as exc:
            log.warning("[%s] Skipping unreadable/corrupt image %s: %s", chapter.tag, panel_path.name, exc)
            continue

    if total_blank_skipped > 0:
        log.info("[%s] skipped %d blank panel(s) during slicing", chapter.tag, total_blank_skipped)

    manifest = CanonicalManifest(
        manifest_version=MANIFEST_VERSION,
        job_id=cfg.job_id,
        chapter_tag=chapter.tag,
        source_pages=[p.name for p in chapter.panel_paths],
        frames=frame_entries,
    )
    manifest.save(manifest_path)
    # Accurate summary of which detector(s) actually ran across this
    # chapter's pages -- previously hardcoded to always claim
    # "(contour-based detection)" regardless of what really happened,
    # which was actively misleading (e.g. showed that label even when
    # every page went through the gutter-aware or YOLO path instead).
    method_summary = ", ".join(f"{count}x {name}" for name, count in detect_method_counts.most_common())
    log.info("[%s] sliced %d source pages into %d canonical frames (detection: %s)",
             chapter.tag, len(chapter.panel_paths), len(frame_entries), method_summary or "none")
    return [(Path(f.path), f.source_index) for f in manifest.frames]


SCROLL_FRAGMENT_ASPECT_RATIO = 3.0  # raised from 1.8 -- see _should_scroll_fragment
SCROLL_FRAGMENT_ONE_CAPTION_AREA_RATIO = 0.6  # a single text box covering more than
# this fraction of the crop's area means the crop is essentially one
# caption, not a multi-element UI card -- see _should_scroll_fragment.


def _should_scroll_fragment(cw: int, ch: int, crop) -> bool:
    """Decide whether a tall crop should be panned through as several
    overlapping video frames (see _generate_ui_card_scroll_frames) or
    shown as a single, correctly-composited frame.

    Two-part gate: the crop must first be tall enough
    (height/width > SCROLL_FRAGMENT_ASPECT_RATIO) to even be considered,
    then the text detector (see _detect_text_boxes,
    ogkalu/comic-text-and-bubble-detector) gets the final say -- if a
    single detected text box already covers most of the crop's area, the
    crop IS essentially one caption/dialogue block, not a multi-element
    scrollable UI list, regardless of raw aspect ratio.

    This matters beyond just visual correctness: researched, established
    practice for image+narration video sync (the pattern used across
    MoviePy/ffmpeg slideshow-narration tooling generally) is "one image,
    one audio clip, no internal subdivision" -- fragmenting a single
    caption into multiple video frames is what forces the downstream
    code to split one TTS segment's audio across multiple frames at all,
    which is the structural root of audio/panel sync issues for this
    class of content, not just a cosmetic slicing problem.

    Falls back to the plain aspect-ratio gate alone if the detector is
    unavailable (returns no boxes), same "degrade, don't crash" pattern
    as everywhere else it's used -- a real production job kept showing
    the fragmentation bug even after raising the aspect-ratio threshold
    alone, from crops that legitimately exceed it (e.g. a caption merged
    with panel content above/below it during boundary detection).
    """
    if (ch / max(1, cw)) <= SCROLL_FRAGMENT_ASPECT_RATIO:
        return False
    crop_gray = cv2.cvtColor(np.array(crop), cv2.COLOR_RGB2GRAY)
    crop_area = max(1, cw * ch)
    for (tx1, ty1, tx2, ty2) in _detect_text_boxes(crop_gray):
        box_area = max(0, tx2 - tx1) * max(0, ty2 - ty1)
        if box_area / crop_area > SCROLL_FRAGMENT_ONE_CAPTION_AREA_RATIO:
            return False  # one big caption -- don't fragment it
    return True


def _generate_ui_card_scroll_frames(crop, num_scroll_frames: int = 4) -> List["Image.Image"]:
    """Generate a sequence of linear vertical scroll sub-frames for tall rectangular system/quest UI cards.
    Maintains full resolution width and generates vertical panning steps down the UI card rather than squishing or cropping.
    """
    from PIL import Image

    cw, ch = crop.size
    # Visible window height in source space to match 16:9 ratio at full width cw
    window_h = int(cw * CANVAS_H / CANVAS_W)
    if window_h >= ch:
        return [_compose_canvas(crop)]

    scroll_frames = []
    max_top = ch - window_h
    step = max_top / max(1, num_scroll_frames - 1)

    for i in range(num_scroll_frames):
        top = int(round(i * step))
        bot = min(ch, top + window_h)
        sub_crop = crop.crop((0, top, cw, bot))

        # Scale sub_crop to 1920x1080 canvas preserving aspect ratio
        canvas = Image.new("RGB", (CANVAS_W, CANVAS_H), (0, 0, 0))
        fg = sub_crop.resize((CANVAS_W, CANVAS_H), Image.LANCZOS)
        canvas.paste(fg, (0, 0))
        scroll_frames.append(canvas)

    return scroll_frames


def _content_bbox_corner_floodfill(img_bgr, tol=16, keep_thresh=0.985, min_keep_frac=0.4):
    """Corner-seeded, fixed-range flood-fill margin trim. See _compose_canvas
    for the full history/validation notes -- this is the core algorithm,
    kept separate so it can be unit-tested on its own.

    Returns (x0, y0, x1, y1) -- always a valid box within the image, even on
    degenerate input (falls back to the whole image rather than raising).
    """
    import cv2
    import numpy as np

    if img_bgr is None or img_bgr.size == 0:
        h, w = (0, 0) if img_bgr is None else img_bgr.shape[:2]
        return 0, 0, w, h
    if img_bgr.ndim == 2:
        img_bgr = cv2.cvtColor(img_bgr, cv2.COLOR_GRAY2BGR)
    h, w = img_bgr.shape[:2]
    if h == 0 or w == 0:
        return 0, 0, w, h

    # margin mask: flood-fill from small zones near each of the 4 corners
    # only (not the full border -- see history note above), fixed-range
    # (each pixel compared to its OWN seed's color, not its neighbor's, so
    # it can't leak arbitrarily far through a smooth gradient the way a
    # relative flood-fill was found to when this was first tried).
    smoothed = cv2.medianBlur(img_bgr, 5)
    mask = np.zeros((h + 2, w + 2), np.uint8)
    flood_img = smoothed.copy()
    loDiff = upDiff = (tol, tol, tol)
    zx = max(12, int(w * 0.08))
    zy = max(12, int(h * 0.08))
    zx, zy = min(zx, w // 2 or 1), min(zy, h // 2 or 1)

    # Anchor each corner zone to the exact corner pixel's own color, and only
    # seed from points that still match it. FIXED_RANGE compares every filled
    # pixel to *its own seed's* color, not to the true corner -- so without
    # this gate, a seed a few pixels into the zone that happens to land on a
    # same-colored-but-unrelated flat UI element (e.g. a translator's caption
    # box whose edge sits inside the zone) becomes its own valid reference
    # point and floods that entire element as "margin". Confirmed on a real
    # webtoon page: a caption box's left edge sat at x=40 inside a zx=64
    # corner zone, a seed landed on the box's own black fill, and the flood
    # ate the box's internal padding right up to its first line of text.
    # Requiring color-continuity back to the literal corner pixel closes
    # this without weakening genuine margins, which by definition are
    # uniform all the way into the corner (so every candidate seed still
    # passes trivially).
    corner_anchor = {
        'tl': smoothed[0, 0].astype(np.int16),
        'tr': smoothed[0, w - 1].astype(np.int16),
        'bl': smoothed[h - 1, 0].astype(np.int16),
        'br': smoothed[h - 1, w - 1].astype(np.int16),
    }

    def _matches_anchor(x, y, corner_key):
        return int(np.abs(smoothed[y, x].astype(np.int16) - corner_anchor[corner_key]).max()) <= tol

    seeds = set()
    for x in range(0, zx, max(1, zx // 6)):
        if _matches_anchor(x, 0, 'tl'):
            seeds.add((x, 0))
        if _matches_anchor(w - 1 - x, 0, 'tr'):
            seeds.add((w - 1 - x, 0))
        if _matches_anchor(x, h - 1, 'bl'):
            seeds.add((x, h - 1))
        if _matches_anchor(w - 1 - x, h - 1, 'br'):
            seeds.add((w - 1 - x, h - 1))
    for y in range(0, zy, max(1, zy // 6)):
        if _matches_anchor(0, y, 'tl'):
            seeds.add((0, y))
        if _matches_anchor(0, h - 1 - y, 'bl'):
            seeds.add((0, h - 1 - y))
        if _matches_anchor(w - 1, y, 'tr'):
            seeds.add((w - 1, y))
        if _matches_anchor(w - 1, h - 1 - y, 'br'):
            seeds.add((w - 1, h - 1 - y))
    for (x, y) in seeds:
        if 0 <= x < w and 0 <= y < h and mask[y + 1, x + 1] == 0:
            cv2.floodFill(flood_img, mask, (x, y), (0, 0, 0), loDiff, upDiff,
                          flags=4 | cv2.FLOODFILL_MASK_ONLY | cv2.FLOODFILL_FIXED_RANGE | (255 << 8))
    m = mask[1:-1, 1:-1]

    is_margin = m > 0
    row_frac = is_margin.mean(axis=1)
    col_frac = is_margin.mean(axis=0)

    y0 = 0
    while y0 < h and row_frac[y0] >= keep_thresh:
        y0 += 1
    y1 = h
    while y1 > y0 and row_frac[y1 - 1] >= keep_thresh:
        y1 -= 1
    x0 = 0
    while x0 < w and col_frac[x0] >= keep_thresh:
        x0 += 1
    x1 = w
    while x1 > x0 and col_frac[x1 - 1] >= keep_thresh:
        x1 -= 1

    # degenerate collapse (uniform image, or trim met itself) -- no
    # reliable content signal at all; keep the whole image rather than let
    # the min-size backstop re-center around a collapsed coordinate
    if x0 >= x1 or y0 >= y1:
        return 0, 0, w, h

    min_w, min_h = max(1, int(w * min_keep_frac)), max(1, int(h * min_keep_frac))
    if x1 - x0 < min_w:
        cx = (x0 + x1) // 2
        x0, x1 = max(0, cx - min_w // 2), min(w, cx + min_w // 2)
    if y1 - y0 < min_h:
        cy = (y0 + y1) // 2
        y0, y1 = max(0, cy - min_h // 2), min(h, cy + min_h // 2)

    return x0, y0, x1, y1


def _compose_canvas(crop):
    """Composite `crop` onto a 1920x1080 canvas with a blurred, cover-fit
    copy of the same panel as the background (instead of plain black bars).
    Uses CONTAIN-FIT for the foreground: scales the panel to fit ENTIRELY
    within the canvas, showing the complete panel — including character
    head and feet — with the blurred backdrop filling the rest of the
    frame. This ensures NO content is ever cut off while avoiding the
    dead-black letterbox bars that plain contain-fit leaves on portrait
    panels.
    Also trims white borders from the source panel first."""
    from PIL import Image, ImageFilter
    import numpy as np

    # Trim margin from the crop -- corner-seeded, fixed-range flood-fill,
    # not a plain brightness threshold. Replaces an earlier per-row/column
    # "% non-white" trim that only handled flat WHITE margins and had no
    # defense against a piece of real content merely touching an edge.
    #
    # Stress-tested (session of 2026-09-05) across 8 real webtoon panel
    # types (bubbles top+bottom, diagonal composition, borderless/full-bleed,
    # dark-gradient margin, dense multi-bubble, low-contrast white-on-white,
    # outbound content escaping a border, plain white margin) plus crash/
    # degenerate inputs (corrupt file, grayscale, all-black/white, 1x1,
    # zero-height) and adversarial synthetic cases -- zero cut-throughs in
    # any of them after two real bugs were found and fixed:
    #   1. Seeding from the FULL border let a piece of CONTENT that merely
    #      touches one edge (e.g. a shirt touching the bottom of a
    #      bust-shot) get flood-filled as "margin" from its own
    #      border-touching pixels -- confirmed to cut ~300px into a real
    #      shirt before this fix. Now seeds only from small zones near each
    #      of the 4 corners (a real margin that surrounds content typically
    #      extends into the corners; content that merely touches the middle
    #      of one edge does not).
    #   2. A fully uniform image (all-black/white, or otherwise
    #      indistinguishable from its own border) made the independent
    #      per-axis shrink loops collapse to a corner instead of the center;
    #      now explicitly detected and treated as "keep the whole image."
    # One known, accepted limit: a single flat-color block touching all 4
    # corners can't be told apart from a real margin by color alone (proven
    # by direct counter-example -- the identical pattern is CORRECT when the
    # roles are reversed, i.e. real content centered on a dark background,
    # which is a common composition). Verified rare in practice; this
    # function's input already comes from _detect_page_panels' bubble/panel
    # detection above, which is the real safety net for that case -- this
    # trim only ever shaves further margin off an already-content-safe box.
    #
    # IMPORTANT: must only ever receive a single already-detected panel, not
    # an arbitrary raw strip window -- confirmed during testing that feeding
    # it a region spanning two unrelated panels produces a technically
    # "correct" (nothing cut) but useless result mixing both together. That
    # is a scope contract of the caller, not something this function can
    # detect on its own.
    cw0, ch0 = crop.size
    if cw0 > 0 and ch0 > 0:
        import cv2

        img_bgr = cv2.cvtColor(np.array(crop.convert("RGB")), cv2.COLOR_RGB2BGR)
        x0, y0, x1, y1 = _content_bbox_corner_floodfill(img_bgr)
        if (x1 - x0) > 20 and (y1 - y0) > 20:
            crop = crop.crop((x0, y0, x1, y1))

    cw, ch = crop.size

    # Blurred, cover-fit background: scales the SAME panel up until it fully
    # covers the canvas (cropping the overflow, never the foreground), then
    # blurs + darkens it. Fills the whole frame — no black bars — while the
    # sharp foreground panel below still shows every pixel of the source.
    bg_scale = max(CANVAS_W / cw, CANVAS_H / ch)
    bw, bh = max(1, int(cw * bg_scale)), max(1, int(ch * bg_scale))
    bg = crop.resize((bw, bh), Image.LANCZOS)
    bx = (bw - CANVAS_W) // 2
    by = (bh - CANVAS_H) // 2
    bg = bg.crop((bx, by, bx + CANVAS_W, by + CANVAS_H))
    bg = bg.filter(ImageFilter.GaussianBlur(40))
    # Adaptive tone: a flat p*0.66 turns an already-dark panel's backdrop into
    # a pure-black void (a very common look in the old output). Instead pull
    # the blurred backdrop's mean toward a fixed dark tone (~46) — bright
    # backdrops get darkened, near-black ones get lifted off zero — then a
    # gentle radial vignette so the sharp panel still reads as the subject.
    _b = np.asarray(bg).astype(np.float32)
    _m = float(_b.mean())
    _b *= float(np.clip(48.0 / max(_m, 1.0), 0.40, 4.5))
    _b = _b * 0.9 + 16.0
    yy, xx = np.mgrid[0:CANVAS_H, 0:CANVAS_W].astype(np.float32)
    _r = (((xx - CANVAS_W / 2) / (CANVAS_W / 2)) ** 2 + ((yy - CANVAS_H / 2) / (CANVAS_H / 2)) ** 2)
    _b *= (1.0 - 0.22 * np.clip(_r, 0, 1))[..., None]
    canvas = Image.fromarray(np.clip(_b, 0, 255).astype(np.uint8)).convert("RGB")

    # Contain-fit by default (whole panel visible over its blurred backdrop).
    # But a MODERATELY tall panel (aspect ~1.5–2.9) contain-fits to a thin
    # centre ribbon that reads as a broken "small strip". For those, fill the
    # width and crop the vertical overflow — biased to KEEP THE TOP (a webtoon
    # tall panel puts the face/bubble up top, background/legs below). An
    # EXTREME aspect (>2.9) is genuine tall scroll art — keep contain so
    # nothing is lost. RECAP_TALL_COVER=0 forces contain everywhere.
    # A mildly-tall panel (aspect ~1.45–1.9) contain-fits to a thin ribbon
    # that reads as a broken "small strip". Fill the width instead and crop
    # the vertical overflow — but ONLY the rows that are near-empty (a plain
    # margin), and never a row that carries ink (a bubble / face / SFX). If
    # neither the top nor the bottom overflow is safe to drop, fall back to
    # contain and keep the whole panel. Taller than ~1.9 is genuine scroll
    # art: contain, lose nothing. RECAP_TALL_COVER=0 disables cover entirely.
    aspect = ch / max(1, cw)
    want_cover = (os.environ.get("RECAP_TALL_COVER", "1").lower() not in ("0", "false", "no")
                  and 1.45 <= aspect <= 1.95)
    fg_contain = min(CANVAS_W / cw, CANVAS_H / ch) * PANEL_FIT_MARGIN
    fg_scale = fg_contain
    crop_top = crop_bot = 0
    if want_cover:
        cover_scale = (CANVAS_W / cw) * PANEL_FIT_MARGIN
        fh_cov = int(ch * cover_scale)
        overflow = max(0, fh_cov - CANVAS_H)
        if overflow > 0:
            # inspect the source rows that a cover crop would remove
            band_src = max(1, int(overflow / cover_scale))
            gg = cv2.cvtColor(np.asarray(crop), cv2.COLOR_RGB2GRAY)
            def _inky(a, b):
                seg = gg[max(0, a):min(ch, b)]
                return seg.size and float((np.abs(seg.astype(np.int16) - 245) > 30).mean()) > 0.02
            top_inky, bot_inky = _inky(0, band_src), _inky(ch - band_src, ch)
            if not top_inky and not bot_inky:
                fg_scale = cover_scale; crop_top = overflow // 2; crop_bot = overflow - crop_top
            elif not top_inky:
                fg_scale = cover_scale; crop_top = overflow
            elif not bot_inky:
                fg_scale = cover_scale; crop_bot = overflow
            # else: both sides carry content -> stay contain

    fw, fh = max(1, int(cw * fg_scale)), max(1, int(ch * fg_scale))
    fg = crop.resize((fw, fh), Image.LANCZOS)
    if crop_top or crop_bot:
        fg = fg.crop((0, crop_top, fw, fh - crop_bot))
        fw, fh = fg.size
    if fw > CANVAS_W or fh > CANVAS_H:
        left = max(0, (fw - CANVAS_W) // 2)
        top = max(0, (fh - CANVAS_H) // 2)
        fg = fg.crop((left, top, left + min(fw, CANVAS_W), top + min(fh, CANVAS_H)))
        fw, fh = fg.size
    fx = (CANVAS_W - fw) // 2
    fy = (CANVAS_H - fh) // 2
    canvas.paste(fg, (fx, fy))

    return canvas


# ---------------------------------------------------------------------------
# 3a. TRANSLATION (Groq, OpenAI-compatible endpoint)
# ---------------------------------------------------------------------------

TRANSLATE_SYSTEM_PROMPT = (
    "You translate raw OCR text pulled from manhwa/manhua/webtoon panels into "
    "natural English. The input is machine-transcribed, so it may be split across "
    "odd line breaks, jumble dialogue with captions, or contain minor OCR errors.\n\n"
    "RULES:\n"
    "1. If the text is ALREADY English, return it unchanged except for joining "
    "hard-wrapped lines into normal sentences and fixing only unambiguous OCR "
    "typos (e.g. 'l' vs 'I', '0' vs 'O', 'rn' vs 'm'). Never paraphrase English.\n"
    "2. If it is not English, translate it into plain, natural English that matches "
    "the register of the original (casual speech stays casual, narration stays "
    "narration).\n"
    "3. Preserve ALL proper nouns, character names, place names, honorifics, and "
    "system/RPG terms exactly (e.g. Hunter, Gate, Dungeon, S-Rank, E-Rank, "
    "'[Daily Quest]', skill and item names).\n"
    "4. Keep sound effects and onomatopoeia — romanize them (e.g. 'BADUMP', "
    "'KWAAANG', 'THUD'); do not delete or explain them.\n"
    "5. Keep bracketed UI/system text in brackets.\n"
    "6. Do NOT add, remove, summarize, censor, or explain anything. No translator "
    "notes. No commentary. Same amount of content in, same amount out.\n"
    "7. Output ONLY the resulting text — no preamble, no quotes, no language labels."
)


def translate_text(cfg: PipelineConfig, text: str, cache_tag: str) -> str:
    """Translate a block of text to English via Groq. Cached by cache_tag.
    Any API error falls back to raw text so the pipeline never crashes."""
    out_path = cfg.temp_scripts_dir / f"{cache_tag}_translated.txt"
    if out_path.exists():
        return out_path.read_text(encoding="utf-8")

    if not text:
        out_path.write_text("", encoding="utf-8")
        return ""

    if not cfg.translate or getattr(cfg, "narration_style", "verbatim") in ("verbatim", "cleanup"):
        log.info("[%s] translation disabled — using raw text as-is", cache_tag)
        out_path.write_text(text, encoding="utf-8")
        return text

    # Provider cascade (groq -> gemini(free) -> openrouter(free) -> ollama).
    translated, prov = _llm_chat(
        cfg,
        [{"role": "system", "content": TRANSLATE_SYSTEM_PROMPT},
         {"role": "user", "content": text}],
        temperature=0.2, timeout=90, purpose=f"{cache_tag}-translate",
    )
    if translated:
        translated = translated.strip() or text
        out_path.write_text(translated, encoding="utf-8")
        log.info("[%s] translated via %s (%d chars)", cache_tag, prov, len(translated))
        return translated
    log.warning("[%s] all translation providers failed — using raw text", cache_tag)
    out_path.write_text(text, encoding="utf-8")
    return text


# ---------------------------------------------------------------------------
# 3b. SEAMLESS NARRATIVE REPHRASER (OpenAI)
# ---------------------------------------------------------------------------

FORBIDDEN_PATTERNS = [
    r"\bchapter\s*\d*\b",
    r"\bwelcome back\b",
    r"\bin this (chapter|episode|part)\b",
    r"\b(chapter|episode)\s*(title|recap)\b",
    r"^\s*(chapter|episode)\s*\d+",
]

SYSTEM_PROMPT = (
    "You turn raw webtoon/manhwa panel text into the spoken narration track of a "
    "recap video, in the style of channels like 'Asura Chronicles'.\n\n"
    "VOICE & STYLE:\n"
    "- First person, present tense, told BY THE MAIN CHARACTER as the scene happens "
    "('A door is just floating in mid-air. Am I seeing things?').\n"
    "- Turn dialogue and thought bubbles into natural spoken lines. When someone "
    "else speaks, attribute it plainly ('The old man tells me...', 'She says...').\n"
    "- Conversational and easy, like a person recapping a story to a friend. Keep the "
    "momentum flowing from one line to the next.\n\n"
    "ABSOLUTE RULES:\n"
    "1. Use ONLY what is in the provided text. Never invent names, places, events, "
    "powers, or backstory. If the source does not name someone, don't name them.\n"
    "2. No literary embellishment, no genre flavour that isn't in the source.\n"
    "3. Stay close to the source length — tighten and connect the fragments, do not "
    "pad. Never more than ~1.6x the word count.\n"
    "4. Fix OCR mangling and obvious typos. Merge broken fragments into whole "
    "sentences. Keep RPG/system terms and bracketed UI text as-is.\n"
    "5. Sound effects: fold them in as action ('something slams into me') rather "
    "than reading 'BOOM' aloud. Drop page numbers and translator/editor credits.\n"
    "6. No meta-phrases ('in this panel', 'we see'). No chapter/episode labels.\n"
    "7. Output ONLY the narration line(s) — no preamble, notes, or markdown.\n"
    "If the text is too garbled to make a coherent sentence, output it lightly "
    "cleaned rather than guessing."
)

CLEANUP_SYSTEM_PROMPT = (
    "You are given the raw OCR dump of ONE comic panel — its speech bubbles, "
    "captions and thought bubbles, in whatever jumbled order the OCR emitted "
    "them. Your ONLY job is to output the same words as clean readable dialogue.\n\n"
    "RULES — follow exactly:\n"
    "1. Do NOT translate. Do NOT paraphrase. Do NOT add, remove, summarise, or "
    "reword anything. Every word you output must come from the input.\n"
    "2. Put the lines back into natural reading order (top-to-bottom, "
    "right-to-left is NOT used here — it's left-to-right).\n"
    "3. Re-join words the OCR split apart ('CONNNOUS' -> 'CONTINUOUS', "
    "'BURNEDWHOLE' -> 'BURNED WHOLE') and fix only unambiguous OCR letter "
    "errors. Keep the original wording, tense and person.\n"
    "4. Separate distinct lines with a space; keep bracketed [SYSTEM] text.\n"
    "5. If a fragment is pure noise (single stray letters, a logo), drop it.\n"
    "6. Output ONLY the cleaned panel text — no notes, no preamble, no quotes.\n"
    "If the whole input is noise, output nothing."
)

INTRO_SYSTEM_PROMPT = (
    "You write the opening for a manhwa/manto recap video, in the style of channels "
    "like 'Asura Chronicles'. You are given the transcribed text of the chapters "
    "being recapped. Produce a SHORT spoken intro with exactly these beats, as one "
    "flowing piece of narration (no headings, no bullet points):\n"
    "1. A one-line channel welcome and that we're diving into this story today.\n"
    "2. 'Before we begin, let's take a quick look at what this series is about.'\n"
    "3. A tight spoiler-light overview of the premise and the main character's "
    "situation and goal — 90 to 150 words, built ONLY from the provided text, "
    "inventing nothing. Third person is fine here.\n"
    "4. End on a short hook line like 'And now, let the story begin.'\n"
    "Output only the narration text."
)


# Scanlation credit / staff / front-matter fragments that OCR picks up from
# the first and last pages of almost every chapter. These are never story
# content and must never be spoken. Matched case-insensitively, each pattern
# consuming to end-of-line/segment.
_CJK_RE = re.compile(
    "[\u3000-\u303f\u3040-\u30ff\u3400-\u4dbf\u4e00-\u9fff"
    "\uf900-\ufaff\uff00-\uffef\uac00-\ud7af]+"
)

_CREDIT_PATTERNS = [
    r"\b(?:translator|translation|translated by|editor|edited by|proofreader|proof[- ]?read(?:er|ing)?|"
    r"redraw(?:er)?|redrawer|typeset(?:ter|ting)?|cleaner|cleaning|quality check|qa\s*/?\s*qc|q\.?c\.?|"
    r"raw provider|scanlat(?:or|ion)|uploader|credits?)\s*[:\-—].*",
    r"\b(?:redice studio|d\s*&\s*c\s*webtoon|d\s*&\s*c\s*media|webtoon\s+translator|original (?:novel|work|story)|"
    r"art(?:ist|work)?\s*[:\-—]|story\s*[:\-—]|adapted by).*",
    r"\bto be continued\b\.*",
    r"\bnext (?:chapter|episode)\b.*",
    r"\bthanks for reading\b.*",
    r"\bplease (?:support|rate|comment|subscribe)\b.*",
    # chapter / episode title cards — "CHAPTER 3. ENTERING THE DEMONIC
    # ACADEMY", "EPISODE 12", "PROLOGUE", "SEASON 2 CHAPTER 1". Front-matter,
    # not story dialogue; narrating it verbatim ("Chapter 3. Entering the
    # demonic academy.") reads as an error in a recap. Anchored to the start
    # so a mid-sentence "…this chapter of my life…" is untouched.
    r"^\W*(?:(?:season\s*\d+\s*)?(?:chapter|episode)\s*\d+|prologue|epilogue)\b[\s.:\-—]*.*",
]

# strong markers — a known studio / author name, or a "Role:" label — that
# alone-plus-one signals a credits card; plain words like "studio" only count
# as weak corroboration so a line of dialogue that happens to say "studio" and
# "editor" isn't blanked.
_CREDIT_BLOB_STRONG = re.compile(
    r"(?:\bredice\b|\bred\s*ice\b|\bdubu\b|\bchugong\b|\bh[-\s]?goon\b|\bd\s*&\s*c\b|"
    r"\b(?:translat\w*|editor|edited|proofread\w*|typeset\w*|scanlat\w*|redraw\w*|"
    r"cleaner|art|artwork|story|original\s+novel)\s*(?:[:·\-—]|\bby\b))",
    re.IGNORECASE,
)
_CREDIT_BLOB_WEAK = re.compile(
    r"(?:\bwebtoon\b|\bstudio\b|\bartist\b|\badaptation\b|\bproduction\b|"
    r"\beditor\b|\btranslat\w*|\bproofread\w*|\bto\s+be\s+continued\b|"
    r"\bthanks\s+for\s+reading\b)",
    re.IGNORECASE,
)


def _is_credits_blob(text: str) -> bool:
    """True when a panel's text is a title / staff-credits card rather than
    story dialogue: at least one STRONG marker (studio/author name or a
    'Role:' label) plus one more credit marker, in a short non-prose line."""
    if not text:
        return False
    strong = {m.group(0).lower() for m in _CREDIT_BLOB_STRONG.finditer(text)}
    if not strong:
        return False
    weak = {m.group(0).lower() for m in _CREDIT_BLOB_WEAK.finditer(text)}
    if len(strong) + len(weak) < 2:
        return False
    words = re.findall(r"[A-Za-z']+", text)
    # a credits card is short and mostly proper nouns / labels, not prose
    return len(words) <= 18


def _clean_source_text(text: str) -> str:
    """Strip scanlation credits / front-matter from raw OCR/transcription text
    BEFORE it is translated and rewritten.

    Real jobs read scanlation credits ("Translator: ... Editor: ...") and
    front/end-matter ("To Be Continued", studio names) aloud verbatim because
    each is a "SUCCESS" OCR result as far as the transcriber is concerned.
    None of it is story content.

    Sound effects / onomatopoeia are DELIBERATELY LEFT IN — in verbatim
    (no-narration) mode they are part of what the viewer expects to hear, and
    in narration mode the rewrite prompt handles them. Conservative by design:
    only removes whole spans matching a credit/front-matter pattern, never
    touches dialogue or captions.
    """
    if not text or not text.strip():
        return text or ""

    cleaned = text

    # Drop CJK / Hangul / Kana runs entirely (see _CJK_RE). On raw
    # scanlations the only non-Latin text OCR picks up is the original-
    # language credits page, copyright notice and publisher watermarks
    # (Tencent etc.) — never story content, and all read aloud mangled
    # in word-for-word mode.
    cleaned = _CJK_RE.sub(" ", cleaned)
    # If after that the panel is basically empty or was ALL credits markup,
    # bail early — it's a front-matter / watermark panel.
    if len(re.sub(r"[^A-Za-z]", "", cleaned)) < 3:
        return ""

    # Whole-panel title / staff-credits card, wherever it lands in the chunk
    # stream (webtoon hosts pad several lead-in images before the real title):
    # a cluster of production-credit keywords / known studio + author names is
    # never story content.
    if _is_credits_blob(cleaned):
        return ""

    for pat in _CREDIT_PATTERNS:
        cleaned = re.sub(pat, " ", cleaned, flags=re.IGNORECASE)

    # Common raw-site / copyright boilerplate that survives in English too.
    cleaned = re.sub(
        r"\b(?:all rights reserved|do not (?:re[- ]?upload|repost)|reproduction is prohibited|"
        r"for( the)? promotional use only|read (?:it )?(?:first |for free )?(?:on|at)\s+\S+|"
        r"official (?:release|translation)|join our discord)\b.*",
        " ", cleaned, flags=re.IGNORECASE)

    # Raw-aggregator site watermark stamped INTO a story panel (baozimh,
    # mangabuddy, etc. — often mid-caption, and OCR mangles the TLD:
    # "www.baozimh.con"). Excise just the URL/domain token, NOT the rest of
    # the line — the caption text around it is real story content.
    cleaned = re.sub(r"\bwww\.\S+", " ", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"\bhttps?://\S+", " ", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"\b[a-z][a-z0-9-]{2,}\.(?:com|net|org|con|c0m|xyz|top)\b(?=$|\s|[.,!?])",
                     " ", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(
        r"\b(?:baozimh|baozi\s*manhua|mangabuddy|manhuaplus|manhuafast|mangapark|"
        r"asurascans?|asuracomic|flamescans?|reaperscans?)\b",
        " ", cleaned, flags=re.IGNORECASE)

    # Collapse artefacts left by the removals.
    cleaned = re.sub(r"\(\s*\)", "", cleaned)              # emptied parens
    cleaned = re.sub(r"\(\s*$", "", cleaned)               # dangling open paren
    cleaned = re.sub(r"^\s*\)", "", cleaned)               # dangling close paren
    cleaned = re.sub(r"\s*[,;:]\s*(?=[,;:.])", "", cleaned)
    cleaned = re.sub(r"^[\s,;:.\-—)]+", "", cleaned)
    cleaned = re.sub(r"[\s,;:\-—(]+$", "", cleaned)
    cleaned = re.sub(r"\s{2,}", " ", cleaned).strip()

    # Garbled-logo / credits guard: a studio logo or a stylised credits
    # graphic OCRs as a scatter of short, vowel-less, non-word tokens
    # ("GARO SSTTNO F O FEHNEEADS A S S YMY"). If most tokens don't look
    # like real words and the whole thing is short, it isn't dialogue.
    toks = re.findall(r"[A-Za-z][A-Za-z'\-]*", cleaned)
    SHORT_WORDS = {"a", "i", "an", "as", "at", "be", "by", "do", "go", "he", "if",
                   "in", "is", "it", "me", "my", "no", "of", "oh", "ok", "on", "or",
                   "so", "to", "up", "us", "we", "ah", "hi", "ha", "ho", "uh", "um"}
    if len(toks) >= 3:
        def _wordish(t: str) -> bool:
            tl = t.lower()
            if tl in SHORT_WORDS:
                return True
            if not (2 <= len(tl) <= 16) or not re.search(r"[aeiou]", tl):
                return False
            # English almost never has 4+ consonants in a row
            return re.search(r"[bcdfghjklmnpqrstvwxz]{4,}", tl) is None
        ratio = sum(_wordish(t) for t in toks) / len(toks)
        if ratio < 0.62 and len(cleaned) < 100:
            return ""

    # A panel whose whole transcription is a bare number ("40" — a page
    # number bleeding into an art panel) carries no dialogue. Drop it so the
    # frame plays silent instead of the TTS solemnly intoning "forty".
    # (Sound effects and short interjections are NOT numbers, so they pass.)
    if re.fullmatch(r"[\W\d]*\d[\W\d]*", cleaned) and re.fullmatch(r"\d{1,4}", cleaned.strip(" .,!?-—:;\"'")):
        return ""
    return cleaned


# Faithfulness guard for LLM narration output. A small local model (and
# occasionally a large one) will "continue the story": invent character
# names, locations and whole events that never appeared in the source text.
# Seen in a real job — llama3.2:3b turned a Solo Leveling page into a scene
# about "Kaito the exile" and "Yuna the elder of the clan". When the rewrite
# fails these checks we discard it and fall back to the cleaned source text.
_NARRATION_MAX_EXPANSION = 2.3   # output words / source words ceiling
_NARRATION_MIN_RATIO = 0.35      # output words / source words floor (dropped content)
_COMMON_CAPITALIZED = {
    "I", "I'm", "I'll", "I've", "I'd", "The", "A", "An", "He", "She", "They", "We", "You",
    "It", "His", "Her", "Their", "My", "Your", "Our", "This", "That", "These", "Those",
    "But", "And", "Or", "So", "Then", "When", "Now", "Here", "There", "What", "Why", "How",
    "If", "As", "At", "In", "On", "Of", "To", "For", "With", "No", "Yes", "Not", "Boss",
    "God", "Sir", "Hey", "Oh", "Ah", "Hunter", "Hunters", "Gate", "Gates", "Dungeon", "Dungeons",
}


def _proper_nouns(text: str) -> set:
    """Capitalized tokens that are not sentence-initial and not common words —
    a cheap proxy for named entities (people/places)."""
    nouns = set()
    for sentence in re.split(r"(?<=[.!?])\s+", text):
        words = sentence.split()
        for i, w in enumerate(words):
            bare = w.strip(".,!?\"'();:—-")
            if i == 0:
                continue
            if bare and bare[0].isupper() and bare.lower() != bare and bare not in _COMMON_CAPITALIZED:
                nouns.add(bare.rstrip("'s").lower())
    return nouns


def _cleanup_preserves_words(source: str, output: str) -> bool:
    """Guard for narration_style='cleanup': the LLM may only reorder the
    panel's words and fix OCR splits — never translate or rewrite. Accept
    only if the output is essentially the same bag of words."""
    def toks(s: str) -> list:
        return re.findall(r"[a-z]{3,}", s.lower())
    src, out = toks(source), toks(output)
    if not out:
        return False
    if not src:
        return len(out) <= 6
    if not (0.55 <= len(out) / len(src) <= 1.5):
        return False
    src_set, out_set = set(src), set(out)
    kept = len(src_set & out_set) / len(src_set)          # how much of source survived
    added = len(out_set - src_set) / max(1, len(out_set))  # how much is brand new
    return kept >= 0.6 and added <= 0.35


def _narration_is_faithful(source: str, output: str, cache_tag: str) -> bool:
    src_words = source.split()
    out_words = output.split()
    if not out_words:
        return False
    if src_words:
        ratio = len(out_words) / len(src_words)
        if ratio > _NARRATION_MAX_EXPANSION:
            log.warning("[%s] narration rejected: %.1fx expansion over source (%d -> %d words)",
                        cache_tag, ratio, len(src_words), len(out_words))
            return False
        if ratio < _NARRATION_MIN_RATIO and len(src_words) > 12:
            log.warning("[%s] narration rejected: only %.0f%% of source retained",
                        cache_tag, ratio * 100)
            return False
    # A token only counts as "invented" if its lowercase stem appears NOWHERE
    # in the source (not just not-as-a-proper-noun). This tolerates the model
    # title-casing words that are lowercase in the source ("daily quest" ->
    # "Daily Quest", "level up" -> "Level Up") — extremely common with webtoon
    # UI text — while still catching genuinely new names like "Kaito"/"Yuna".
    source_stems = {w.strip(".,!?\"'();:—-").lower().rstrip("'s") for w in source.split()}
    invented = {
        n for n in (_proper_nouns(output) - _proper_nouns(source))
        if n not in source_stems and n not in {c.lower() for c in _COMMON_CAPITALIZED}
    }
    # allow a single incidental slip; two or more named entities absent from
    # the source means the model is fabricating.
    if len(invented) >= 2:
        log.warning("[%s] narration rejected: introduces names/places absent from source: %s",
                    cache_tag, sorted(invented))
        return False
    return True


def _strip_forbidden(text: str) -> str:
    cleaned = text
    for pat in FORBIDDEN_PATTERNS:
        cleaned = re.sub(pat, "", cleaned, flags=re.IGNORECASE | re.MULTILINE)
    # Markdown-ish emphasis the small models sometimes wrap sound effects in
    # ("*crash* *boom*") — the asterisks would be spoken/awkward. Keep the word.
    cleaned = re.sub(r"\*+([^*]+?)\*+", r"\1", cleaned)
    cleaned = cleaned.replace("*", "")
    # \s+ (not \s{2,}) — a LONE embedded newline/tab from OCR's per-line
    # region joining must also collapse to a single space. This matters for
    # --narration-provider none (verbatim mode): edge-tts's internal
    # sanitizer explicitly preserves \n/\t/\r (they're outside the control-
    # character ranges it strips), so a raw newline between OCR'd speech
    # bubbles previously survived all the way into the spoken narration,
    # producing an unnatural pause/break mid-panel instead of a clean space.
    return re.sub(r"\s+", " ", cleaned).strip()


_OBSERVER_GARBLE_RE = re.compile(r"[A-Za-z]{4,}")
_ENGLISH_WORDS: "Optional[set]" = None


def _english_words() -> set:
    global _ENGLISH_WORDS
    if _ENGLISH_WORDS is None:
        _ENGLISH_WORDS = set()
        for path in ("/usr/share/dict/american-english", "/usr/share/dict/words"):
            try:
                with open(path, encoding="utf-8", errors="ignore") as fh:
                    _ENGLISH_WORDS = {w.strip().lower() for w in fh if w.strip().isalpha()}
                break
            except OSError:
                continue
    return _ENGLISH_WORDS


_RARE_BIGRAMS = re.compile(
    r"yy|yg|gy|ty(?![aeiou])|yt|vk|kv|qx|xq|jq|zx|xz|wg|gw|dy(?![aeiou])|fk|kf|pk|kp|bk")


def _text_has_garble(text: str) -> bool:
    """Gate for the observer LLM call. Fires when a token looks like a genuine
    OCR misfire, OR when the line carries several non-dictionary non-name
    tokens (a badly-recognised panel). The observer's output guard rejects
    anything but spelling fixes, so a false positive here only costs a wasted
    LLM call — never a bad edit."""
    words = _english_words()
    common = {w.lower() for w in _COMMON_CAPITALIZED}
    unknowns = 0
    for tok in re.findall(r"[A-Za-z][A-Za-z']*", text):
        tl = tok.lower().strip("'")
        if len(tl) < 2 or tl in common or (words and tl in words):
            continue
        if len(tok) <= 4 and tok[:1].isupper() and not tok.isupper():
            continue                                      # "Wang", "Shen" — a name
        unknowns += 1
        if re.search(r"(.)\1\1", tl):
            return True
        if (not re.search(r"[aeiou]", tl)
                or re.search(r"[bcdfghjklmnpqrstvwxyz]{4,}", tl)
                or _RARE_BIGRAMS.search(tl)
                or (len(tl) >= 5 and len(set(tl)) <= 2)
                or (len(tl) >= 5 and sum(c not in "aeiouy" for c in tl) / len(tl) >= 0.78)):
            return True
    # Otherwise only fire when SEVERAL tokens are unknown (a badly-recognised
    # panel). A lone short all-caps non-word ("EHOH", "TOTN") is left alone —
    # in an all-caps comic it's indistinguishable from a character name, and
    # the observer's guard would refuse to touch it anyway. This also keeps
    # observer LLM calls to ~1-2 per chapter so a big job stays inside a free
    # API tier.
    return unknowns >= 3


def _observer_fix_ocr(cfg: "PipelineConfig", text: str, cache_tag: str,
                      context: str = "") -> str:
    """Optional LLM 'observer': repair garbled OCR tokens IN PLACE — spelling
    only, never rewording. Hard-guarded: the output is accepted only if it
    keeps the same word count (±1) and every clean word / name from the
    input, so the model physically cannot paraphrase, translate or invent.
    `context` (the preceding narration) is given to the model as a hint for
    what a mangled word should be, but it must not appear in the output.
    Any failure -> the original text, unchanged."""
    if not text or len(text) < 8 or not _text_has_garble(text):
        return text
    sys_p = (
        "You are an OCR spell-checker for comic-book dialogue. You are given "
        "one line transcribed from a comic panel; some words are mis-recognised "
        "(e.g. 'ANYYG YTYOL' -> 'ANYTHING YOU', 'dunngoeoon' -> 'dungeon', "
        "'EHOH DID YOU' -> 'HOW DID YOU', 'I CTNOHS DO' -> 'I SHOULD DO'). "
        "Fix ONLY clearly garbled words to the real word they were meant to "
        "be, using the surrounding words (and the earlier line, if given) to "
        "decide. Keep EVERYTHING else exactly: same number of words, same "
        "order, same punctuation, same capitalisation, same sound effects. Do "
        "NOT add, remove, reorder, translate or rephrase anything. If a word "
        "is a character name or you are unsure, leave it unchanged. Reply with "
        "the corrected line ONLY — no quotes, no explanation."
    )
    user_msg = text if not context else (
        f"Earlier line (context, do NOT include in your reply): {context[-160:]}\n"
        f"Line to fix: {text}")
    out, _prov = _llm_chat(
        cfg,
        [{"role": "system", "content": sys_p}, {"role": "user", "content": user_msg}],
        temperature=0.0, max_tokens=min(400, len(text) + 80), timeout=40,
        purpose=f"{cache_tag}-observer",
    )
    if not out:
        return text
    out = out.strip().strip('"').strip()
    out = re.sub(r"\s+", " ", out.splitlines()[0] if out else "").strip()
    if not out or "[" in out or "]" in out or "SYSTEM" in out.upper():
        return text

    in_toks = re.findall(r"[A-Za-z']+", text)
    out_toks = re.findall(r"[A-Za-z']+", out)
    if not in_toks or abs(len(out_toks) - len(in_toks)) > 1:
        return text          # word count must match (±1) — no rewording
    if len(out) > len(text) * 1.25 + 6:
        return text

    # the LLM may ONLY touch tokens the garble gate itself flagged. Every
    # other input token (real words, and — crucially — character NAMES, which
    # the model loves to "correct" into English words) must survive verbatim,
    # same casing. This makes a name→word substitution impossible.
    _english = _english_words()
    _common_cap = {c.lower() for c in _COMMON_CAPITALIZED}

    # A token carries a STRONG garble signature (no vowel, a 4+ consonant run,
    # a rare bigram, >=78% consonants) — safe for the LLM to rewrite, it can't
    # be a plausible name. A merely-unknown short token ("EHOH", "JANG") is
    # left protected: structurally a name and a mis-read look identical, so
    # only the full cleanup/recap rewrite (or GOT-OCR2) can touch those.
    def _strong_garble(tok: str) -> bool:
        tl = tok.lower().strip("'")
        if tl in _common_cap or (_english and tl in _english):
            return False
        if re.search(r"(.)\1\1", tl) or len(tl) < 4:
            return False
        return (not re.search(r"[aeiou]", tl)
                or bool(re.search(r"[bcdfghjklmnpqrstvwxyz]{4,}", tl))
                or bool(_RARE_BIGRAMS.search(tl))
                or (len(tl) >= 5 and len(set(tl)) <= 2)
                or (len(tl) >= 5 and sum(c not in "aeiouy" for c in tl) / len(tl) >= 0.78))

    protected = {t for t in in_toks if not _strong_garble(t)}
    out_set = set(out_toks)
    if any(t not in out_set for t in protected):
        return text          # a clean word / name went missing -> reject

    if out != text:
        log.info("[%s] observer fixed OCR: %r -> %r", cache_tag, text[:70], out[:70])
    return out


def rephrase_text(cfg: PipelineConfig, text: str, cache_tag: str, prev_tail: str) -> str:
    """Call an LLM to rewrite (already-English) text into narration, chained with
    prev_tail for continuity. Cached by cache_tag.
    Provider selection (cfg.narration_provider):
      - auto: prefer OpenAI if key set, else Groq if key set, else none
      - openai/groq/none: explicit
    Any API error falls back to the raw text verbatim."""
    out_path = cfg.temp_scripts_dir / f"{cache_tag}.txt"
    if out_path.exists():
        log.info("[%s] narration script already exists — skipping rewrite", cache_tag)
        return out_path.read_text(encoding="utf-8")

    if not text:
        log.warning("[%s] no text available, writing empty placeholder script", cache_tag)
        out_path.write_text("", encoding="utf-8")
        return ""

    # Strip scanlation credits / front-matter / non-Latin watermarks before
    # anything else — noise in every downstream path. `text` from here on is
    # the cleaned source.
    text = _clean_source_text(text)
    if not text.strip():
        log.info("[%s] source was entirely credits/watermark noise — empty narration", cache_tag)
        out_path.write_text("", encoding="utf-8")
        return ""

    style = getattr(cfg, "narration_style", "verbatim")

    # verbatim: the OCR's own words, in the OCR's own order, nothing added.
    # No LLM, no translation — regardless of narration_provider.
    if style == "verbatim":
        narration = _strip_forbidden(text)
        if getattr(cfg, "observer", False):
            narration = _observer_fix_ocr(cfg, narration, cache_tag, context=prev_tail or "")
        out_path.write_text(narration, encoding="utf-8")
        return narration

    # Provider cascade: openai -> groq -> gemini(free) -> openrouter(free) ->
    # ollama(local). A daily-quota / rate-limit on one provider rolls to the
    # next instead of silently dropping the whole job to raw verbatim (the
    # exact failure on the 328-chapter run).
    chain = _llm_provider_chain(cfg)
    if not chain:
        log.warning(
            "[%s] [RAW/VERBATIM MODE] no LLM provider key configured — using raw text. "
            "Set GROQ_API_KEY / GEMINI_API_KEY / OPENROUTER_API_KEY (all have free tiers).",
            cache_tag,
        )
        narration = _strip_forbidden(text)
        out_path.write_text(narration, encoding="utf-8")
        return narration

    if style == "cleanup":
        sys_prompt = CLEANUP_SYSTEM_PROMPT
        user_prompt = f"RAW OCR OF ONE PANEL:\n{text}"
        temperature = 0.1
    else:  # recap
        sys_prompt = SYSTEM_PROMPT
        # prev_tail is tone/tense continuity ONLY — framed as "already told,
        # don't reuse" so the model can't snowball an earlier invented name.
        user_prompt = (
            "Rewrite the SOURCE TEXT below into recap narration. Use only what it "
            f"contains.\n\nSOURCE TEXT:\n{text}"
        )
        if prev_tail:
            user_prompt = (
                f"[For tone/tense continuity only — already narrated, do NOT repeat or "
                f"build on its specifics]\n...{prev_tail}\n\n" + user_prompt
            )
        temperature = 0.45

    provider = "cascade"
    model = chain[0][3]
    try:
        raw_out, _prov = _llm_chat(
            cfg,
            [{"role": "system", "content": sys_prompt},
             {"role": "user", "content": user_prompt}],
            temperature=temperature, timeout=90, purpose=cache_tag,
        )
        if raw_out is None:
            raise RuntimeError("all providers failed")
        provider = _prov
        raw_out = raw_out.strip()
        candidate = _strip_forbidden(raw_out)
        if style == "cleanup":
            # strip bracketed tags the small model likes to inject ("[SYSTEM]")
            # unless that exact tag was in the source
            for tag in set(re.findall(r"\[[A-Za-z ]{2,12}\]", candidate)):
                if tag.lower() not in text.lower():
                    candidate = candidate.replace(tag, " ")
            candidate = re.sub(r"\s{2,}", " ", candidate).strip()
        ok = bool(candidate) and (
            _cleanup_preserves_words(text, candidate) if style == "cleanup"
            else _narration_is_faithful(text, candidate, cache_tag)
        )
        if ok:
            narration = candidate
        else:
            narration = _strip_forbidden(text)
            log.info("[%s] LLM %s output rejected — using raw OCR words", cache_tag, style)
    except Exception as e:
        log.warning("[%s] narration API call failed via %s (%s) — using raw OCR words", cache_tag, provider, e)
        narration = _strip_forbidden(text)

    out_path.write_text(narration, encoding="utf-8")
    log.info("[%s] narration script written via %s/%s (%d chars)", cache_tag, provider, model, len(narration))
    return narration


def last_sentences(text: str, n: int = 2) -> str:
    sentences = re.split(r"(?<=[.!?])\s+", text.strip())
    sentences = [s for s in sentences if s]
    return " ".join(sentences[-n:])


def split_into_segments(text: str, n: int) -> List[str]:
    """Split narration text into n roughly-equal word chunks, one per frame,
    so every sliced image gets its own narration segment for tight sync.
    If there are fewer words than frames, trailing frames get an empty
    segment and simply hold silently for SILENT_FRAME_DURATION."""
    words = text.split()
    if n <= 0:
        return []
    if not words:
        return [""] * n

    segments: List[str] = []
    idx = 0
    total = len(words)
    for i in range(n):
        remaining_slots = n - i
        remaining_words = total - idx
        if remaining_words <= 0:
            segments.append("")
            continue
        seg_len = max(1, round(remaining_words / remaining_slots))
        segments.append(" ".join(words[idx: idx + seg_len]))
        idx += seg_len
    return segments


# ---------------------------------------------------------------------------
# 4. LOCAL-FIRST PRODUCTION TEXT-TO-SPEECH (Piper -> Piper retry -> eSpeak NG)
# ---------------------------------------------------------------------------
# NOTE: narration used to be synthesized one tiny word-chunk at a time (one
# edge-tts call per sliced frame) and then concatenated. edge-tts inserts a
# short natural pause at the start/end of every call it makes, so stitching
# dozens of these clips back-to-back produced an audible "stop" after every
# few words. Fixed by synthesizing each *panel's* full narration as a single
# continuous speech clip, then using the actual word-level timestamps from
# that one clip to divide it across frames — no re-synthesis, no seams.

def get_audio_duration(path: Path) -> float:
    """Audio duration in seconds.

    Fast path: for a PCM WAV (every per-segment clip in the render loop is
    one — mono/16-bit/AUDIO_SAMPLE_RATE), read nframes/framerate straight
    from the header. That is exactly what ffprobe's `format=duration`
    returns for PCM, sample-accurate, but with no ~80 ms subprocess spawn —
    and this is called O(frames) times per chapter. Falls back to ffprobe
    for any non-WAV input or on any read error.
    """
    if str(path).lower().endswith(".wav"):
        try:
            with wave.open(str(path), "rb") as w:
                fr = w.getframerate()
                if fr > 0:
                    return w.getnframes() / float(fr)
        except Exception:
            pass  # fall through to ffprobe
    result = subprocess.run(
        [
            "ffprobe", "-v", "error", "-show_entries", "format=duration",
            "-of", "default=noprint_wrappers=1:nokey=1", str(path),
        ],
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True,
    )
    try:
        return float(result.stdout.strip())
    except ValueError:
        raise RuntimeError(f"ffprobe could not read duration of {path}: {result.stderr}")


def _generate_silence(path: Path, duration: float) -> None:
    # Output as WAV (not MP3) to avoid encoder delay/padding that causes
    # sync drift when concatenated. WAV is raw PCM — sample-accurate.
    #
    # Fast path: silent PCM is just zero samples — write them with the stdlib
    # `wave` module (mono / 16-bit / AUDIO_SAMPLE_RATE, byte-identical to the
    # old `ffmpeg anullsrc -t ... -ac 1` output) instead of spawning ffmpeg
    # once per silent panel (~34 of 100 frames on a typical chapter).
    if str(path).lower().endswith(".wav"):
        try:
            n = max(0, int(round(duration * AUDIO_SAMPLE_RATE)))
            with wave.open(str(path), "wb") as w:
                w.setnchannels(1)
                w.setsampwidth(2)
                w.setframerate(AUDIO_SAMPLE_RATE)
                w.writeframes(b"\x00\x00" * n)
            return
        except Exception as exc:
            log.debug("pure-python silence write failed (%s) — using ffmpeg", exc)
    run_ffmpeg(
        [
            "ffmpeg", "-y", "-f", "lavfi",
            "-i", f"anullsrc=r={AUDIO_SAMPLE_RATE}:cl=mono",
            "-t", f"{duration:.3f}",
            "-ar", str(AUDIO_SAMPLE_RATE), "-ac", "1",
            str(path),
        ]
    )


def _audio_qa(path: Path, allow_silence: bool = False) -> bool:
    if not path.exists() or path.stat().st_size < 44:
        return False
    try:
        duration = get_audio_duration(path)
        if duration <= 0.05:
            return False
        if allow_silence:
            return True
        result = subprocess.run([
            "ffmpeg", "-hide_banner", "-i", str(path), "-af", "volumedetect", "-f", "null", "-",
        ], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=30)
        probe = result.stderr + result.stdout
        m = re.search(r"max_volume:\s*(-?\d+(?:\.\d+)?) dB", probe)
        return bool(m and float(m.group(1)) > -50.0)
    except Exception:
        return False


def _synthesize_with_espeak(text: str, out_wav: Path) -> None:
    espeak = shutil.which("espeak-ng") or shutil.which("espeak")
    if not espeak:
        raise RuntimeError("espeak-ng binary unavailable")
    result = subprocess.run([espeak, "-w", str(out_wav), text], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=120)
    if result.returncode != 0:
        raise RuntimeError(f"espeak-ng failed: {result.stderr[-200:]}")


def _synthesize_with_piper(text: str, out_wav: Path) -> None:
    piper = shutil.which("piper")
    model = os.environ.get("PIPER_VOICE_MODEL", "en_US-ryan-high.onnx")
    if not piper:
        raise RuntimeError("piper binary unavailable")
    # If model is a relative path or filename, let piper resolve it unless explicitly missing as an absolute path
    if Path(model).is_absolute() and not Path(model).exists():
        raise RuntimeError(f"piper voice model unavailable: {model}")
    # Deliberately NOT `with subprocess.Popen(...) as proc:` here -- verified
    # directly with an isolated timing test that Popen's context-manager
    # __exit__ calls its own unconditional (untimed) wait() while
    # propagating a TimeoutExpired raised inside the block, which blocks
    # until the child actually exits on its own instead of the requested
    # timeout: a `sleep 10` process with `communicate(timeout=1)` measured
    # at 10.00s end-to-end through the with-statement, vs 1.00s with the
    # explicit try/except/kill pattern below. That means this function's
    # 120s cap was not actually enforced -- a slow or stuck Piper
    # synthesis (long RAW/VERBATIM-mode text under CPU load competing
    # with rendering/OCR is exactly the realistic trigger) could hang far
    # past 120s instead of failing over to eSpeak as
    # synthesize_segment_audio's cascade intends, which is a real,
    # plausible contributor to narration going missing or a whole job
    # stalling on one segment.
    proc = subprocess.Popen(
        [piper, "--model", model, "--output_file", str(out_wav)],
        stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True,
    )
    try:
        _out, err = proc.communicate(text, timeout=120)
    except subprocess.TimeoutExpired:
        proc.kill()
        proc.communicate()  # reap the killed process so it doesn't linger as a zombie
        raise RuntimeError("piper timed out after 120s")
    if proc.returncode != 0:
        raise RuntimeError(f"piper failed: {err[-200:]}")


_kokoro_python_cache: Optional[str] = None
_kokoro_unavailable_logged = False


def _kokoro_python() -> Optional[str]:
    """Path to the Python that has kokoro-onnx, or None. Prefers an explicit
    RECAP_KOKORO_PYTHON, then the isolated pipeline/.venv-kokoro venv."""
    global _kokoro_python_cache
    if _kokoro_python_cache is not None:
        return _kokoro_python_cache or None
    cand = os.environ.get("RECAP_KOKORO_PYTHON", "").strip()
    if cand and Path(cand).exists():
        _kokoro_python_cache = cand
        return cand
    if KOKORO_VENV_PYTHON.exists():
        _kokoro_python_cache = str(KOKORO_VENV_PYTHON)
        return _kokoro_python_cache
    _kokoro_python_cache = ""
    return None


_KOKORO_VOICE_RE = re.compile(r"^[abhijpef][fm]_[a-z][a-z_]*$")


def _kokoro_voice_requested(cfg) -> Optional[str]:
    """The Kokoro voice to use, or None to leave TTS on edge-tts. Kokoro is
    selected either by RECAP_TTS_ENGINE=kokoro (voice from RECAP_KOKORO_VOICE)
    or by cfg.voice being a Kokoro voice id (am_michael, af_bella, bm_george,
    …) — which is how the website's voice picker turns it on."""
    v = (getattr(cfg, "voice", "") or "").strip()
    if v and _KOKORO_VOICE_RE.match(v):
        return v
    if os.environ.get("RECAP_TTS_ENGINE", "").strip().lower() == "kokoro":
        return os.environ.get("RECAP_KOKORO_VOICE", "am_michael")
    return None


def _synthesize_with_kokoro(text: str, out_wav: Path,
                            voice: Optional[str] = None) -> Optional[List[dict]]:
    """Synthesize `text` to a 24 kHz mono PCM WAV at `out_wav` using Kokoro-82M
    in its isolated venv (see pipeline/kokoro_tts.py). Returns the per-sentence
    timing list [{"text","start","end"}, ...] on success, or None on ANY failure
    (not installed, model missing, subprocess error) so the caller falls
    through to its normal TTS cascade with no behaviour change."""
    global _kokoro_unavailable_logged
    py = _kokoro_python()
    if not py or not KOKORO_TTS_SCRIPT.exists():
        if not _kokoro_unavailable_logged:
            log.info("RECAP_TTS_ENGINE=kokoro set but Kokoro venv not found "
                     "(run pipeline/setup_kokoro.sh) — using edge-tts")
            _kokoro_unavailable_logged = True
        return None
    model_ok = (KOKORO_MODEL_DIR / "kokoro-v1.0.onnx").exists() and \
               (KOKORO_MODEL_DIR / "voices-v1.0.bin").exists()
    if not model_ok:
        if not _kokoro_unavailable_logged:
            log.info("Kokoro model files missing under %s — using edge-tts", KOKORO_MODEL_DIR)
            _kokoro_unavailable_logged = True
        return None

    req = {
        "text": text,
        "voice": voice or os.environ.get("RECAP_KOKORO_VOICE", "am_michael"),
        "speed": float(os.environ.get("RECAP_KOKORO_SPEED", "1.0") or 1.0),
        "lang": os.environ.get("RECAP_KOKORO_LANG", "en-us"),
        "out_wav": str(out_wav),
        "model_dir": str(KOKORO_MODEL_DIR),
        "sample_rate": 24000,
        "sentence_pause": float(os.environ.get("RECAP_KOKORO_SENT_PAUSE", "0.18") or 0.18),
    }
    # Generous ceiling: ~4x real-time on this box, plus init/spawn slack.
    timeout = max(60.0, len(text) * 0.12 + 25.0)
    try:
        proc = subprocess.run(
            [py, str(KOKORO_TTS_SCRIPT)],
            input=json.dumps(req), text=True,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=timeout,
        )
    except subprocess.TimeoutExpired:
        log.warning("Kokoro synthesis timed out after %.0fs — falling back", timeout)
        return None
    except Exception as e:
        log.warning("Kokoro subprocess failed to launch (%s) — falling back", e)
        return None

    out = (proc.stdout or "").strip().splitlines()
    payload = None
    for line in reversed(out):
        line = line.strip()
        if line.startswith("{"):
            try:
                payload = json.loads(line)
                break
            except Exception:
                continue
    if not payload or not payload.get("ok"):
        err = (payload or {}).get("error") if payload else (proc.stderr or "")[-200:]
        log.info("Kokoro synthesis unavailable (%s) — using edge-tts", err)
        return None
    if not out_wav.exists() or out_wav.stat().st_size < 200:
        return None
    return payload.get("sentences") or []


def _kokoro_word_boundaries(text: str, sentences: List[dict]) -> Optional[List[dict]]:
    """Turn Kokoro's per-sentence timing into a per-word {"text","start","end"}
    list aligned 1:1 with text.split() — split_frame_timings needs that exact
    count to use real timing instead of an even word-count estimate. Kokoro
    gives no word timestamps, so each sentence's measured span is distributed
    across its words weighted by word length (a decent proxy for syllables).
    Returns None if the counts don't line up (caller keeps the estimate)."""
    words = text.split()
    if not words or not sentences:
        return None
    wb: List[dict] = []
    wi = 0
    for s in sentences:
        sw = (s.get("text") or "").split()
        if not sw:
            continue
        span = max(0.01, float(s.get("end", 0.0)) - float(s.get("start", 0.0)))
        weights = [max(1, len(w)) for w in sw]
        tot = float(sum(weights))
        cur = float(s.get("start", 0.0))
        for w, wt in zip(sw, weights):
            d = span * (wt / tot)
            if wi < len(words):
                wb.append({"text": words[wi], "start": cur, "end": cur + d})
                wi += 1
            cur += d
    if len(wb) != len(words):
        return None
    return wb


def _srt_to_vtt(srt_content: str) -> str:
    """Convert SRT subtitle content to WebVTT format."""
    lines = ["WEBVTT", ""]
    for line in srt_content.splitlines():
        # Convert comma to dot in timestamps: 00:00:01,234 -> 00:00:01.234
        if "-->" in line:
            lines.append(line.replace(",", "."))
        else:
            lines.append(line)
    return "\n".join(lines)


def _normalize_case_for_tts(text: str) -> str:
    """Convert shouty ALL-CAPS comic lettering to normal sentence case
    before handing text to a TTS engine.

    Comic/manhwa lettering is drawn in all-caps by convention -- a purely
    visual/stylistic choice by the letterer, carrying no more semantic
    weight than the specific font used -- but production neural TTS
    engines do not treat it as mere styling. Microsoft's own documentation
    on Azure/Edge neural voices (the same voice family this pipeline's
    primary engine, edge-tts, uses) explicitly confirms capitalization
    changes text-normalization and pronunciation behavior. Feeding raw
    all-caps OCR text straight to TTS is exactly the out-of-distribution
    input neural TTS models were never trained on (their training
    transcripts are ordinary mixed-case text) -- the documented cause of
    unnatural, shouty, or inconsistently-pronounced narration.

    This can't perfectly recover "proper" capitalization -- comic
    lettering doesn't preserve the original case distinction at all, so a
    name like "JINWOO" and a word like "STOP" are visually identical --
    but sentence case is still a strict improvement over leaving text
    all-caps, and is the standard mitigation this class of problem gets
    in practice.

    Leaves already-mixed-case text (e.g. from an upstream narration LLM
    rewrite, when one is configured) completely untouched -- only
    triggers when the text is actually shouty in the first place.
    """
    stripped = text.strip()
    if not stripped:
        return stripped
    letters = [c for c in stripped if c.isalpha()]
    if not letters:
        return stripped
    upper_ratio = sum(1 for c in letters if c.isupper()) / len(letters)
    if upper_ratio < 0.8:
        return stripped

    lowered = stripped.lower()
    parts = re.split(r'([.!?]+\s*)', lowered)
    rebuilt = []
    capitalize_next = True
    for part in parts:
        if not part:
            continue
        if capitalize_next and part[0].isalpha():
            part = part[0].upper() + part[1:]
            capitalize_next = False
        if re.fullmatch(r'[.!?]+\s*', part):
            capitalize_next = True
        rebuilt.append(part)
    result = "".join(rebuilt)
    # Standalone "i" -> "I" is a basic English capitalization rule
    # regardless of sentence position; cheap and worth restoring.
    result = re.sub(r'\bi\b', 'I', result)
    return result


def _prewarm_segment_audio(cfg: "PipelineConfig", chapter: "Chapter", segments: list) -> None:
    """Fill the per-segment audio cache in parallel. Each segment's synthesis
    is independent and network-I/O-bound (edge-tts), so a small thread pool
    collapses the per-chapter TTS wall time. Best-effort: any failure here is
    ignored — the sequential renderer re-runs that segment (and handles the
    Piper/eSpeak/silence cascade) exactly as before."""
    from concurrent.futures import ThreadPoolExecutor
    todo = []
    for seg in segments:
        tag, text = seg[0], (seg[1] or "").strip()
        if not text:
            continue
        cached = cfg.temp_audio_dir / chapter.tag / f"{tag}.wav"
        if cached.exists():
            continue
        todo.append((tag, text))
    if len(todo) < 2:
        return
    # Default lowered 4 -> 2 to match this box's 2 vCPUs: 4 concurrent
    # edge-tts connections (each its own asyncio event loop in a thread)
    # competing with ffmpeg/PaddleOCR on 2 cores was the leading suspect for
    # the ~1-in-2-chapters "No audio was received" failures observed on a
    # 100-chapter run (load averaged 5.5-5.9 throughout render) -- fewer
    # concurrent connections means less scheduler contention locally AND
    # less chance of tripping Microsoft's endpoint-side throttling.
    workers = max(2, min(int(os.environ.get("RECAP_TTS_WORKERS", "2")), len(todo)))
    # Kokoro synthesis is CPU-bound (each worker runs the 82M ONNX model), NOT
    # network-I/O like edge-tts — so a high RECAP_TTS_WORKERS (tuned for
    # edge-tts's parallel connections) just oversubscribes the cores and
    # thrashes. Cap it near the core count when Kokoro is the engine.
    if _kokoro_voice_requested(cfg):
        _kc = max(2, min(int(os.environ.get("RECAP_KOKORO_WORKERS",
                         str(max(2, min(3, (os.cpu_count() or 4) - 1))))), len(todo)))
        workers = min(workers, _kc)

    def _one(item):
        try:
            synthesize_segment_audio(cfg, chapter, item[0], item[1])
        except Exception:
            pass

    t0 = time.time()
    with ThreadPoolExecutor(max_workers=workers) as ex:
        list(ex.map(_one, todo))
    log.info("[%s] pre-synthesised %d segments in %.1fs (%d-way)", chapter.tag, len(todo), time.time() - t0, workers)


def synthesize_segment_audio(cfg: PipelineConfig, chapter: Chapter, tag: str, text: str) -> tuple:
    """Generate atomic segment audio with Edge-TTS (primary), Piper ONNX (fallback), eSpeak NG (tertiary fallback).
    Also exports matching .vtt / .srt timing markers alongside Edge-TTS audio outputs for caption syncing.

    Returns (audio_path, tts_failed, word_boundaries). word_boundaries is a
    list of {"text", "start", "end"} dicts (seconds, relative to this
    segment's own audio) when edge-tts succeeded and provided per-word
    timing data -- see split_frame_timings, which uses this in place of
    an estimated proportional word-count split when it's available and
    trustworthy. None for every other path (cache hit, silent segment,
    Piper/eSpeak fallback -- neither provides word-level timestamps),
    in which case callers fall back to the pre-existing estimate.
    """
    seg_audio_dir = cfg.temp_audio_dir / chapter.tag
    seg_audio_dir.mkdir(parents=True, exist_ok=True)
    final_path = seg_audio_dir / f"{tag}.wav"
    text = text.strip()
    text = _normalize_case_for_tts(text)
    if final_path.exists() and _audio_qa(final_path, allow_silence=not text):
        return final_path, False, None

    final_path.unlink(missing_ok=True)
    tmp_path = seg_audio_dir / f"{tag}.tmp.wav"
    tmp_path.unlink(missing_ok=True)

    if not text:
        _generate_silence(tmp_path, SILENT_FRAME_DURATION)
        if not _audio_qa(tmp_path, allow_silence=True):
            tmp_path.unlink(missing_ok=True)
            raise RuntimeError(f"silent audio QA failed for {tag}")
        os.replace(tmp_path, final_path)
        return final_path, False, None

    failures = []

    # Kokoro-82M neural TTS, tried BEFORE edge-tts when the job's voice is a
    # Kokoro voice id (set by the website's voice picker) or RECAP_TTS_ENGINE=
    # kokoro. Isolated venv + subprocess (see _synthesize_with_kokoro /
    # pipeline/kokoro_tts.py). Any failure appends to `failures` and falls
    # straight through to the edge-tts cascade below — zero behaviour change
    # when it is not selected or not installed.
    _kok_voice = _kokoro_voice_requested(cfg)
    if _kok_voice:
        kok_wav = seg_audio_dir / f"{tag}_kok.wav"
        kok_wav.unlink(missing_ok=True)
        try:
            sentences = _synthesize_with_kokoro(text, kok_wav, voice=_kok_voice)
            if sentences is not None and kok_wav.exists() and kok_wav.stat().st_size > 200:
                raw_dur = get_audio_duration(kok_wav)
                fade_out_start = max(0.0, raw_dur - SEGMENT_FADE_OUT)
                seg_af = (f"afade=t=in:st=0:d={SEGMENT_FADE_IN},"
                          f"afade=t=out:st={fade_out_start:.3f}:d={SEGMENT_FADE_OUT}")
                run_ffmpeg(["ffmpeg", "-y", "-i", str(kok_wav), "-af", seg_af,
                            "-ar", str(AUDIO_SAMPLE_RATE), "-ac", "1", str(tmp_path)])
                if _audio_qa(tmp_path, allow_silence=False):
                    os.replace(tmp_path, final_path)
                    wb = _kokoro_word_boundaries(text, sentences)
                    log.info("[%s] Kokoro TTS synthesised segment %s (%.1fs, %d sentence(s), timing=%s)",
                             chapter.tag, tag, raw_dur, len(sentences),
                             "real" if wb else "estimate")
                    return final_path, False, wb
                raise RuntimeError("kokoro output failed audio QA")
            failures.append("kokoro: unavailable / empty output")
        except Exception as e:
            failures.append(f"kokoro: {e}")
            log.info("[%s] Kokoro TTS unavailable for segment %s (%s) — using edge-tts",
                     chapter.tag, tag, e)
        finally:
            kok_wav.unlink(missing_ok=True)
            tmp_path.unlink(missing_ok=True)

    import asyncio
    import edge_tts

    # If the job picked a Kokoro voice and we reached here, Kokoro failed —
    # don't hand its id to edge-tts (invalid), use a close edge-tts stand-in.
    voice = cfg.voice or "en-US-ChristopherNeural"
    if _KOKORO_VOICE_RE.match(voice):
        voice = ("en-GB-RyanNeural" if voice.startswith("bm_")
                 else "en-GB-SoniaNeural" if voice.startswith("bf_")
                 else "en-US-AvaNeural" if voice.startswith("af_")
                 else "en-US-AndrewNeural")
    raw_path = seg_audio_dir / f"{tag}_raw.mp3"
    srt_path = seg_audio_dir / f"{tag}.srt"
    vtt_path = seg_audio_dir / f"{tag}.vtt"
    word_boundaries = []  # type: list

    async def _run_edge_tts():
        # Cap the per-attempt wait: a successful synth streams in ~1-2s, so
        # 8s connect / 15s receive never bites a real success but stops a
        # rejected/hung connection from burning edge-tts's 10s/60s defaults
        # (the difference between a ~6s failed attempt and a ~30-60s one
        # during a throttle wave).
        communicate = edge_tts.Communicate(
            text, voice, rate="+5%", connect_timeout=8, receive_timeout=15)
        submaker = edge_tts.SubMaker()
        with open(raw_path, "wb") as f:
            async for chunk in communicate.stream():
                if chunk["type"] == "audio":
                    f.write(chunk["data"])
                elif chunk["type"] in ("WordBoundary", "SentenceBoundary"):
                    submaker.feed(chunk)
                    if chunk["type"] == "WordBoundary":
                        # offset/duration are in 100-nanosecond ticks (the
                        # Windows/.NET "ticks" convention edge-tts's
                        # underlying service uses) -- confirmed against
                        # the package's own docs ("converts 100-nanosecond
                        # ticks into SRT-compliant timestamps"), not
                        # assumed. /1e7 converts to seconds.
                        word_boundaries.append({
                            "text": chunk["text"],
                            "start": chunk["offset"] / 1e7,
                            "end": (chunk["offset"] + chunk["duration"]) / 1e7,
                        })
        srt_text = submaker.get_srt()
        if srt_text:
            srt_path.write_text(srt_text, encoding="utf-8")
            vtt_path.write_text(_srt_to_vtt(srt_text), encoding="utf-8")

    # edge-tts's "No audio was received" / connection-drop failures are
    # usually transient (a flaky websocket round-trip to Microsoft's
    # endpoint, more so under the CPU contention 4-way concurrent synthesis
    # puts on a small 2-vCPU box) rather than a real reason to give up on
    # edge-tts's much better voice quality + word-boundary timestamps.
    # 1 retry with a short backoff recovers most of these before falling
    # through to the Piper ONNX cascade, which loses the word-boundary sync
    # data entirely. Observed on a 100-chapter run: ~1 edge-tts failure per
    # 2 chapters, all currently falling back to Piper on the first miss.
    EDGE_TTS_ATTEMPTS = 2
    # Throttle-wave short-circuit: if edge-tts has been failing in a cluster,
    # don't even attempt it — go straight to Piper for the cooldown window.
    with _EDGE_TTS_WAVE_LOCK:
        _wave_active = time.time() < _EDGE_TTS_WAVE["skip_until"]
    for attempt in range(1, EDGE_TTS_ATTEMPTS + 1):
        if _wave_active:
            failures.append("edge-tts: skipped (throttle-wave cooldown -> Piper)")
            break
        try:
            word_boundaries.clear()
            asyncio.run(_run_edge_tts())
            if not raw_path.exists() or raw_path.stat().st_size < 100:
                raise RuntimeError("edge-tts produced empty or invalid audio file")
            raw_dur = get_audio_duration(raw_path)
            fade_out_start = max(0.0, raw_dur - SEGMENT_FADE_OUT)
            seg_af = f"afade=t=in:st=0:d={SEGMENT_FADE_IN},afade=t=out:st={fade_out_start:.3f}:d={SEGMENT_FADE_OUT}"
            run_ffmpeg(["ffmpeg", "-y", "-i", str(raw_path), "-af", seg_af, "-ar", str(AUDIO_SAMPLE_RATE), "-ac", "1", str(tmp_path)])
            if not _audio_qa(tmp_path, allow_silence=False):
                raise RuntimeError("edge-tts output failed audio QA")
            os.replace(tmp_path, final_path)
            with _EDGE_TTS_WAVE_LOCK:  # success -> wave is over
                _EDGE_TTS_WAVE["consec_fail"] = 0
                _EDGE_TTS_WAVE["skip_until"] = 0.0
            return final_path, False, (word_boundaries or None)
        except Exception as e:
            failures.append(f"edge-tts (attempt {attempt}/{EDGE_TTS_ATTEMPTS}): {e}")
            _tripped = False
            with _EDGE_TTS_WAVE_LOCK:
                _EDGE_TTS_WAVE["consec_fail"] += 1
                if (_EDGE_TTS_WAVE["consec_fail"] >= _EDGE_TTS_WAVE_THRESHOLD
                        and _EDGE_TTS_WAVE["skip_until"] < time.time()):
                    _EDGE_TTS_WAVE["skip_until"] = time.time() + _EDGE_TTS_WAVE_COOLDOWN
                    _tripped = True
            if _tripped:
                log.warning("[%s] edge-tts throttle wave detected (%d consecutive failures) — "
                            "routing all segments to Piper for %.0fs",
                            chapter.tag, _EDGE_TTS_WAVE_THRESHOLD, _EDGE_TTS_WAVE_COOLDOWN)
            if attempt < EDGE_TTS_ATTEMPTS:
                log.info("[%s] edge-tts attempt %d/%d failed for segment %s (%s) — retrying",
                          chapter.tag, attempt, EDGE_TTS_ATTEMPTS, tag, e)
                time.sleep(random.uniform(0.3, 0.9) + 0.4 * attempt)
            else:
                log.warning("[%s] edge-tts failed for segment %s after %d attempts (%s) — attempting Piper ONNX fallback",
                            chapter.tag, tag, EDGE_TTS_ATTEMPTS, e)
        finally:
            raw_path.unlink(missing_ok=True)

    # Fallback 1: Piper ONNX
    tmp_path.unlink(missing_ok=True)
    try:
        _synthesize_with_piper(text, tmp_path)
        if _audio_qa(tmp_path, allow_silence=False):
            os.replace(tmp_path, final_path)
            log.info("[%s] Piper ONNX fallback succeeded for segment %s", chapter.tag, tag)
            return final_path, False, None
        raise RuntimeError("piper output failed audio QA")
    except Exception as e:
        failures.append(f"piper: {e}")
        log.warning("[%s] Piper ONNX fallback failed for segment %s (%s) — attempting eSpeak NG fallback", chapter.tag, tag, e)

    # Fallback 2: eSpeak NG
    tmp_path.unlink(missing_ok=True)
    try:
        _synthesize_with_espeak(text, tmp_path)
        if _audio_qa(tmp_path, allow_silence=False):
            os.replace(tmp_path, final_path)
            log.info("[%s] eSpeak NG fallback succeeded for segment %s", chapter.tag, tag)
            return final_path, False, None
        raise RuntimeError("espeak output failed audio QA")
    except Exception as e:
        failures.append(f"espeak: {e}")
        log.warning("[%s] All TTS engines failed for segment %s (%s) — using silence fallback", chapter.tag, tag, " | ".join(failures))

    # Ultimate fallback in legacy mode: generate silence
    _generate_silence(tmp_path, SILENT_FRAME_DURATION)
    os.replace(tmp_path, final_path)
    return final_path, True, None

def build_chapter_audio_track(
    cfg: PipelineConfig, chapter: Chapter, segment_audio_paths: List[Path],
    narration_expected: bool = True,
) -> Path:
    """Concatenate per-segment (per-panel) audio clips into one continuous
    chapter audio track, then apply loudness normalization.
    Because each input clip is now a full continuous utterance (not a lone
    word), the only joins left are the natural breath-like gaps between
    panels/scenes — not mid-sentence chops. Resumable.

    `narration_expected` should reflect whether ANY segment in this chapter
    actually had real dialogue to narrate (the caller's `tts_attempted > 0`
    count) — NOT just whether `segment_audio_paths` is non-empty, which it
    always is even for a chapter with zero dialogue (every silent segment
    still produces a real silence WAV). Passing that wrong signal would make
    audio_qa's silent-audio check reject a legitimately quiet chapter's
    audio track as a QA failure."""
    out_path = cfg.temp_audio_dir / f"{chapter.tag}.mp3"  # final output still MP3 (re-encoded from WAV, so no padding issues)
    if out_path.exists():
        log.info("[%s] chapter audio track already assembled — skipping", chapter.tag)
        return out_path

    concat_list = cfg.temp_audio_dir / f"{chapter.tag}_audio_concat.txt"
    with concat_list.open("w", encoding="utf-8") as f:
        for p in segment_audio_paths:
            f.write(f"file '{p.resolve().as_posix()}'\n")

    # First: raw concat (stream copy). WAV files have no encoder delay/padding,
    # so concatenation with -c copy is sample-accurate — no sync drift.
    # Output MUST be WAV (not MP3) because -c copy can't put PCM into an MP3
    # container without re-encoding. The loudnorm step below re-encodes to MP3.
    raw_path = cfg.temp_audio_dir / f"{chapter.tag}_raw.wav"
    run_ffmpeg(
        [
            "ffmpeg", "-y", "-f", "concat", "-safe", "0",
            "-i", str(concat_list),
            "-c", "copy",
            "-f", "wav",
            str(raw_path),
        ]
    )

    # Second: audio post-processing — gentle loudness normalization only.
    #
    # PREVIOUSLY this chain used acompressor(attack=5ms,makeup=+2dB) + bass(+2dB)
    # + loudnorm. The compressor's 5ms attack combined with +2dB makeup gain
    # exaggerated the attack transient of every spoken phrase, producing an
    # audible "pop" at the onset of each narration segment. The bass boost
    # added a low-frequency "thump" on top. Both have been REMOVED.
    #
    # Per-segment fade-in/fade-out (applied in synthesize_segment_audio) now
    # eliminates click artifacts at clip boundaries, so all we need here is
    # smooth loudness normalization to keep volume consistent across chapters.
    #
    # loudnorm: EBU R128 normalization to TARGET_LOUDNESS_LUFS.
    #
    # NOTE: if a chapter has no narration at all (every segment fell back to
    # silence — narration.json entries all empty, or narrative rewrite
    # returned nothing), raw_path is pure digital silence end-to-end.
    # loudnorm's gain boost on an absolutely-zero signal trips a real
    # libmp3lame bug (psymodel.c calc_energy: Assertion 'el >= 0' failed,
    # verified locally), which crashes ffmpeg outright. There's nothing to
    # normalize in silence anyway, so on that failure we just copy
    # the raw (silent) track through untouched instead of crashing the job.
    #
    # Like render_chapter/merge_chapters, this writes to a .tmp path first
    # and only promotes to `out_path` (the resume-checked path above) after
    # audio_qa passes — a process killed mid-loudnorm-encode used to be able
    # to leave a truncated MP3 sitting directly at `out_path`, which a
    # resumed run would then treat as "already assembled" and feed straight
    # into render_chapter's video mux.
    tmp_path = cfg.temp_audio_dir / f"{chapter.tag}.mp3.tmp"
    tmp_path.unlink(missing_ok=True)
    af = f"loudnorm=I={TARGET_LOUDNESS_LUFS}:TP=-1.5:LRA=11"
    try:
        run_ffmpeg(
            [
                "ffmpeg", "-y", "-i", str(raw_path),
                "-af", af,
                "-ar", str(AUDIO_SAMPLE_RATE), "-b:a", AUDIO_BITRATE, "-ac", "2",
                "-f", "mp3",
                str(tmp_path),
            ]
        )
    except RuntimeError as e:
        log.warning(
            "[%s] audio post-processing failed (%s) — falling back to raw (unprocessed) audio track",
            chapter.tag, e,
        )
        tmp_path.unlink(missing_ok=True)
        run_ffmpeg(["ffmpeg", "-y", "-i", str(raw_path), "-ar", str(AUDIO_SAMPLE_RATE), "-ac", "2", "-f", "mp3", str(tmp_path)])

    qa = audio_qa(tmp_path, narration_expected=narration_expected)
    if not qa.ok:
        quarantine_dir = cfg.temp_audio_dir / "quarantine"
        quarantine_dir.mkdir(exist_ok=True)
        bad_path = quarantine_dir / f"{chapter.tag}.{int(time.time())}.{qa.reason}.bad"
        try:
            tmp_path.rename(bad_path)
        except OSError:
            tmp_path.unlink(missing_ok=True)
        raw_path.unlink(missing_ok=True)
        raise RuntimeError(f"[{chapter.tag}] chapter audio track failed QA ({qa.reason}) — see {bad_path}")

    atomic_promote(tmp_path, out_path)
    raw_path.unlink(missing_ok=True)
    log.info("[%s] assembled + post-processed chapter audio (loudnorm) -> %s", chapter.tag, out_path.name)
    return out_path


# ---------------------------------------------------------------------------
# 4b. FRAME TIMING (proportional word-count split)
# ---------------------------------------------------------------------------

def _join_scroll_fragments(fragments: List[str]) -> str:
    """Join OCR/VLM text fragments read off consecutive, overlapping
    scroll-pan windows of one tall UI card into a single continuous line.

    Each window is a vertical crop that overlaps its neighbor, so the same
    words are often transcribed twice at the boundary. Trim that duplicated
    overlap instead of concatenating verbatim, which would otherwise repeat
    words/sentences in the narration."""
    result = ""
    for frag in fragments:
        frag = frag.strip()
        if not frag:
            continue
        if not result:
            result = frag
            continue
        result_words = result.split()
        frag_words = frag.split()
        max_overlap = min(len(result_words), len(frag_words), 12)
        overlap = 0
        for k in range(max_overlap, 0, -1):
            if [w.lower() for w in result_words[-k:]] == [w.lower() for w in frag_words[:k]]:
                overlap = k
                break
        result = (result + " " + " ".join(frag_words[overlap:])).strip()
    return result


def split_frame_timings(text: str, positions: List[int], duration: float, is_silent: bool = False, word_boundaries: Optional[List[dict]] = None) -> dict:
    """Split a segment's TTS duration across its frames, using real
    per-word timing when available and falling back to a proportional
    word-count estimate otherwise. For narrated frames, ensures each
    frame gets at least MIN_FRAME_DURATION seconds and adds
    FRAME_HOLD_PADDING (0.5s) to the last frame. For silent (NO_TEXT or
    FAILED textless) frames, avoids MIN_FRAME_DURATION and
    FRAME_HOLD_PADDING to maintain appropriate short pacing.

    word_boundaries, when provided (see synthesize_segment_audio), is a
    list of {"text", "start", "end"} dicts giving each spoken word's REAL
    timing from the actual TTS synthesis, in text.split() order. When its
    length matches text.split()'s word count exactly, this replaces the
    proportional estimate below with the segment's actual measured
    pacing -- pauses at punctuation, variable syllable length, and
    natural pauses between sentences all fall out of using real data
    instead of assuming every word takes an equal share of time (which
    is what made "audio panel mismatch" worse than it needed to be: a
    short word next to a long one were always given equal screen time
    regardless of how long either actually took to say). Falls back to
    the proportional estimate if boundaries are missing, empty, or don't
    line up 1:1 with text.split() -- edge-tts's own internal tokenization
    for WordBoundary events isn't guaranteed to exactly match a naive
    whitespace split (e.g. contractions, hyphenation), and forcing a
    mismatched mapping would silently produce WORSE timing than the
    estimate it would be replacing.
    """
    frame_texts = split_into_segments(text, len(positions))
    word_counts = [len(t.split()) for t in frame_texts]
    total_words = sum(word_counts)
    num_frames = len(positions)
    all_words = text.split()

    timings: dict = {}

    use_real_timing = (
        not is_silent
        and word_boundaries
        and len(word_boundaries) == len(all_words)
        and total_words > 0
    )

    cursor = 0.0
    if use_real_timing:
        word_idx = 0
        for pos, count in zip(positions, word_counts):
            if count == 0:
                timings[pos] = (cursor, cursor)
                continue
            frame_words = word_boundaries[word_idx: word_idx + count]
            start = frame_words[0]["start"]
            end = frame_words[-1]["end"]
            # Real per-word timestamps are absolute within the segment's
            # own audio, not relative to a running cursor -- use them
            # directly so a natural pause edge-tts inserted between
            # frames (e.g. at a sentence boundary) is preserved instead
            # of being silently squeezed out by a cumulative estimate.
            timings[pos] = (start, end)
            cursor = end
            word_idx += count
    elif total_words > 0:
        # Proportional estimate (pre-existing behavior, used whenever
        # real timing isn't available or trustworthy): every word
        # assumed to take an equal share of the segment's total measured
        # duration.
        for pos, count in zip(positions, word_counts):
            span = duration * (count / total_words)
            timings[pos] = (cursor, cursor + span)
            cursor += span
    else:
        span = duration / max(1, num_frames)
        for pos in positions:
            timings[pos] = (cursor, cursor + span)
            cursor += span

    if not is_silent:
        # Enforce MIN_FRAME_DURATION: stretch any short frame and push later ones out.
        # Walk forward, adjusting each frame's end to be at least MIN_FRAME_DURATION
        # from its start, then shifting subsequent starts.
        prev_end = 0.0
        for pos in positions:
            start, end = timings[pos]
            start = max(start, prev_end)  # ensure no overlap
            if end - start < MIN_FRAME_DURATION:
                end = start + MIN_FRAME_DURATION
            timings[pos] = (start, end)
            prev_end = end

        # Add FRAME_HOLD_PADDING only to the LAST frame in the segment.
        if positions:
            last_pos = positions[-1]
            start, end = timings[last_pos]
            timings[last_pos] = (start, end + FRAME_HOLD_PADDING)
    else:
        # For silent frames, enforce non-overlapping boundaries without MIN_FRAME_DURATION padding.
        prev_end = 0.0
        for pos in positions:
            start, end = timings[pos]
            start = max(start, prev_end)
            if end <= start:
                end = start + 1.0
            timings[pos] = (start, end)
            prev_end = end

    return timings


# ---------------------------------------------------------------------------
# 5. CHAPTER RENDERER (static frames, memory-efficient per-segment ffmpeg)
# ---------------------------------------------------------------------------

def render_chapter(
    cfg: PipelineConfig,
    chapter: Chapter,
    frame_paths: List[Path],
    frame_durations: List[float],
    audio_path: Optional[Path],
) -> Optional[Path]:
    """Render a chapter's static panel frames + per-frame narration into an MP4.

    FAST approach: uses ffmpeg concat demuxer with image durations, so a single
    ffmpeg call creates the entire chapter video (instead of N separate processes).
    This is dramatically faster than the old per-segment approach.

    Each frame is held on screen for exactly its own audio segment's duration
    (frame_durations), so image swaps line up precisely with the narration.
    RESUME: skip entirely if chap_XXX.mp4 already exists on disk."""
    out_path = cfg.temp_chapters_dir / f"{chapter.tag}.mp4"
    if out_path.exists():
        log.info("[%s] chapter video already rendered — skipping (resume)", chapter.tag)
        return out_path

    if not frame_paths:
        log.warning("[%s] no frames to render — skipping chapter", chapter.tag)
        return None

    # Render to a temp path, never the resume-checked `out_path` directly.
    # If this process gets killed mid-ffmpeg-write (OOM, crash, manual
    # interrupt — all realistic on an unattended multi-day Oracle run),
    # `out_path` must NOT exist as a partial/corrupt file, or the next
    # resumed run's `out_path.exists()` check above would treat a broken
    # chapter as done and silently ship it in the final merge.
    tmp_path = cfg.temp_chapters_dir / f"{chapter.tag}.mp4.tmp"
    tmp_path.unlink(missing_ok=True)

    # Write a concat demuxer input file with per-image durations.
    # This lets a SINGLE ffmpeg call produce the whole slideshow video.
    #
    # ffmpeg's concat demuxer computes each entry's on-screen time from the
    # gap between consecutive `file` directives — the `duration` on the
    # FINAL entry has nothing after it to measure against, so ffmpeg drops
    # it and instead holds that last frame for exactly one output frame
    # (1/FPS s). Verified directly: a 2-entry list with durations 3.0/4.0s
    # renders as 3.04s, not 7.0s. Because render_chapter muxes audio with
    # `-shortest`, that truncated video length then cuts the tail off the
    # chapter's real narration audio too — every chapter's final segment
    # was losing its narration and getting frozen on ~1 frame. The
    # documented fix is to repeat the last file path once more with no
    # `duration` line, giving the demuxer an end marker for that segment
    # without adding a new one (it does not add an extra displayed frame).
    concat_list = cfg.temp_chapters_dir / f"{chapter.tag}_images.txt"
    with concat_list.open("w", encoding="utf-8") as f:
        for i, (fp, d) in enumerate(zip(frame_paths, frame_durations)):
            # Ensure the image exists (use absolute path for concat demuxer).
            abs_fp = fp.resolve().as_posix()
            f.write(f"file '{abs_fp}'\n")
            f.write(f"duration {d:.3f}\n")
        if frame_paths:
            # Trailing repeat of the last frame gives the concat demuxer an
            # end-marker for the final real entry (the demuxer ALWAYS drops
            # the last `duration` directive). This repeat MUST also carry its
            # own `duration` line: on ffmpeg 4.2's concat demuxer under
            # `-vsync vfr`, a bare trailing `file` with no duration is held
            # open for an unbounded time, inflating the whole video by
            # 5-15% (verified directly — a 170.24s timeline rendered as
            # 182.4s, which then fails render QA and forces a black-
            # placeholder fallback). With the duration line present the
            # demuxer drops only that one trailing directive and the video
            # renders to the intended length, staying in sync with the
            # audio track. The value is the one that gets dropped, so it's
            # cosmetic — mirror the real last-frame hold.
            last_d = frame_durations[-1] if frame_durations else SILENT_FRAME_DURATION
            f.write(f"file '{frame_paths[-1].resolve().as_posix()}'\n")
            f.write(f"duration {max(0.1, last_d):.3f}\n")

    log.info("[%s] rendering %d frames with concat demuxer", chapter.tag, len(frame_paths))

    # Single ffmpeg call: slideshow from concat demuxer + audio mux.
    # Frames are already 1920x1080 from _compose_canvas, but ensure exact size.
    #
    # The trailing `fps={FPS}` is load-bearing, not cosmetic. On ffmpeg 4.2's
    # concat image demuxer, `-vsync vfr` + an audio input + `-shortest`
    # interact so that the LAST image is held far past its declared duration
    # (verified: a 166.31s frame timeline rendered as 179.12s of video
    # against 166.31s of audio — a 13s progressive desync that also trips
    # render QA into a black-placeholder fallback). Normalising the concat
    # stream to a constant frame rate in the filter graph BEFORE encoding
    # removes that interaction: the same timeline then renders to 166.36s,
    # in sync with the audio. Confirmed to leave the correct no-audio and
    # short-clip ([3,4,5]s -> 12.0s) cases unchanged.
    video_filters = (
        f"scale={CANVAS_W}:{CANVAS_H}:force_original_aspect_ratio=decrease,"
        f"pad={CANVAS_W}:{CANVAS_H}:(ow-iw)/2:(oh-ih)/2,fps={FPS}"
    )
    # --motion kenburns is applied as a SEPARATE second pass on the finished,
    # QA-validated chapter mp4 (see _apply_motion below) — NOT here. Putting a
    # zoompan into this filter graph re-times the VFR concat stream and
    # desyncs video from audio (duration_out_of_tolerance -> black-placeholder
    # fallback; observed directly). The post-pass reframes an already-correct
    # video, copying the audio, so timing is untouchable.
    _tune = "stillimage"
    if getattr(cfg, "watermark", None):
        wm = str(cfg.watermark).replace("\\", "").replace("'", "").replace(":", " ")
        video_filters += (
            f",drawtext=text='{wm}':fontcolor=white@0.55:fontsize=34:"
            f"shadowcolor=black@0.6:shadowx=2:shadowy=2:x=w-tw-32:y=h-th-28"
        )

    # NOTE on -vsync vfr (not "-r FPS"): forcing a constant output frame
    # rate makes ffmpeg duplicate frames to fill each image's declared
    # `duration`, and that duplication math compounds across multiple
    # concat-demuxer duration entries — verified directly: a 3-segment
    # (3.0/4.0/5.0s) concat list rendered as ~16.0s instead of 12.0s under
    # "-r 24", a ~33% overshoot. With has_audio + "-shortest" this overshoot
    # was silently absorbed (the real video track got clipped down to the
    # correct audio length), which is why it stayed hidden — but the
    # no-audio path has no "-shortest" to hide behind and shipped the
    # inflated-duration video as-is. "-vsync vfr" keeps each image's own
    # declared duration exactly (no forced duplication), which is also the
    # semantically correct representation for a static-panel slideshow.
    has_audio = bool(audio_path and audio_path.exists())
    if has_audio:
        cmd = [
            "ffmpeg", "-y",
            "-f", "concat", "-safe", "0",
            "-i", str(concat_list),
            "-i", str(audio_path),
            "-vf", video_filters,
            "-map", "0:v", "-map", "1:a",
            "-c:v", "libx264", "-preset", "veryfast", "-tune", _tune, "-crf", "20", "-pix_fmt", "yuv420p",
            "-vsync", "vfr",
            "-c:a", "aac", "-b:a", AUDIO_BITRATE, "-ar", str(AUDIO_SAMPLE_RATE),
            "-shortest",
            # Force the output muxer explicitly rather than letting ffmpeg
            # guess it from the output filename's extension. tmp_path ends
            # in ".mp4.tmp" (by design — see the atomic-write comment
            # above), so extension-sniffing sees ".tmp" as the extension
            # and fails with "Unable to find a suitable output format".
            # This bit the very first real render on production hardware.
            "-f", "mp4",
            str(tmp_path),
        ]
    else:
        cmd = [
            "ffmpeg", "-y",
            "-f", "concat", "-safe", "0",
            "-i", str(concat_list),
            "-vf", video_filters,
            "-c:v", "libx264", "-preset", "veryfast", "-tune", _tune, "-crf", "20", "-pix_fmt", "yuv420p",
            "-vsync", "vfr",
            "-f", "mp4",
            str(tmp_path),
        ]

    try:
        run_ffmpeg(cmd)
    except RuntimeError as e:
        log.error("[%s] concat render failed: %s", chapter.tag, e)
        tmp_path.unlink(missing_ok=True)
        return None

    concat_list.unlink(missing_ok=True)

    # Never mark a chapter complete before validation (loudnorm drift,
    # a killed ffmpeg process, or disk pressure can all leave a file that
    # opens but is truncated, has no audio stream, or is far shorter than
    # expected — ffmpeg exiting 0 is not sufficient proof of a good file).
    #
    # Tolerance scales with chapter length (5% of expected duration, floor
    # 5.0s) instead of a flat 5.0s regardless of length. A flat 5s cap is
    # ~1% margin on a long, many-frame chapter — far tighter than the real,
    # benign cumulative drift that legitimately accumulates from several
    # independent, small sources across dozens of frames/segments: the
    # loudnorm pass in build_chapter_audio_track shifting final audio
    # duration via its own lookahead/limiter buffering, ffmpeg's internal
    # frame-timebase rounding on each declared image duration, and the
    # MIN_FRAME_DURATION floor's per-frame stretching all being reconciled
    # independently rather than as one exact running total. None of that
    # is perceptible in the actual video — audio/video sync is governed by
    # the real rendered file, not this internal bookkeeping estimate — but
    # a real production run hit exactly this: a 66-frame, ~482s chapter's
    # actual rendered duration (496.36s, a 2.9% difference) tripped the old
    # flat 5.0s tolerance on all 3 retries, and every retry produces the
    # identical deterministic drift (it's not transient/flaky), so all 3
    # failed identically and the chapter's entire real, correct 66 panels
    # got thrown away for an 8-minute black "unavailable" placeholder.
    # A genuinely broken render (a chapter that comes out a few seconds
    # long instead of several minutes) still fails obviously under a
    # percentage check.
    qa_tolerance = float(os.environ.get("VIDEO_QA_TOLERANCE_SECONDS", "5.0"))
    expected_duration = sum(frame_durations)
    qa_tolerance = max(qa_tolerance, expected_duration * 0.05)
    qa = video_qa(tmp_path, audio_expected=has_audio, expected_duration=expected_duration, tolerance=qa_tolerance)
    if not qa.ok:
        quarantine_dir = cfg.temp_chapters_dir / "quarantine"
        quarantine_dir.mkdir(exist_ok=True)
        bad_path = quarantine_dir / f"{chapter.tag}.{int(time.time())}.{qa.reason}.bad"
        try:
            tmp_path.rename(bad_path)
        except OSError:
            tmp_path.unlink(missing_ok=True)
        log.error(
            "[%s] rendered video FAILED QA (%s) — quarantined",
            chapter.tag, qa.reason,
        )
        return None

    if getattr(cfg, "motion", "none") == "kenburns":
        if _apply_motion(tmp_path):
            log.info("[%s] applied Ken Burns motion pass", chapter.tag)
        else:
            log.warning("[%s] Ken Burns motion pass failed — keeping the static render", chapter.tag)

    atomic_promote(tmp_path, out_path)
    log.info("[%s] chapter video rendered + QA-validated -> %s", chapter.tag, out_path.name)
    return out_path


def _load_excluded_frames(cfg: "PipelineConfig") -> "set":
    """Set of 'chap_XXX/frame_NNNNN.jpg' the user dropped in the review step.
    Empty (and cached) when there is no exclusion file."""
    cached = getattr(_load_excluded_frames, "_cache", None)
    if cached is not None:
        return cached
    out = set()
    try:
        f = cfg.work_dir / "excluded_frames.json"
        if f.exists():
            data = json.loads(f.read_text(encoding="utf-8"))
            if isinstance(data, list):
                out = {str(x).strip() for x in data if str(x).strip()}
            elif isinstance(data, dict) and isinstance(data.get("excluded"), list):
                out = {str(x).strip() for x in data["excluded"] if str(x).strip()}
    except Exception as e:  # pragma: no cover
        log.warning("could not read excluded_frames.json (%s) — rendering all panels", e)
    _load_excluded_frames._cache = out  # type: ignore
    if out:
        log.info("manual review: %d panel(s) excluded from render", len(out))
    return out


def _apply_motion(video_path: Path) -> bool:
    """Ken Burns as a SECOND pass on an already-rendered, QA-passed chapter mp4.

    Upscales the frame ~13% and slowly pans a 1920x1080 window around inside
    that margin on a slow Lissajous path — reads as a gentle drifting camera.
    Audio is stream-copied and the frame timing is never touched, so this
    cannot desync anything (the reason it is NOT a filter in the concat
    render). Rewrites video_path in place. Returns False on any failure so
    the caller can fall back to the static cut.
    """
    over = 1.13
    sw, sh = int(round(CANVAS_W * over / 2) * 2), int(round(CANVAS_H * over / 2) * 2)
    mx, my = (sw - CANVAS_W) / 2.0, (sh - CANVAS_H) / 2.0
    vf = (
        f"scale={sw}:{sh},"
        f"crop={CANVAS_W}:{CANVAS_H}:"
        f"'(in_w-{CANVAS_W})/2 + {mx * 0.75:.1f}*sin(t*0.33)':"
        f"'(in_h-{CANVAS_H})/2 + {my * 0.75:.1f}*sin(t*0.24 + 1.1)'"
    )
    out = video_path.with_suffix(".motion.mp4")
    out.unlink(missing_ok=True)
    try:
        run_ffmpeg([
            "ffmpeg", "-y", "-i", str(video_path),
            "-vf", vf,
            "-c:v", "libx264", "-preset", "veryfast", "-tune", "film",
            "-crf", "20", "-pix_fmt", "yuv420p",
            "-c:a", "copy", "-f", "mp4", str(out),
        ])
    except RuntimeError as e:
        log.debug("motion pass ffmpeg failed: %s", e)
        out.unlink(missing_ok=True)
        return False
    try:
        if out.exists() and out.stat().st_size > 1024:
            out.replace(video_path)
            return True
    except OSError:
        pass
    out.unlink(missing_ok=True)
    return False


def render_chapter_with_retry(
    cfg: PipelineConfig,
    chapter: Chapter,
    frame_paths: List[Path],
    frame_durations: List[float],
    audio_path: Optional[Path],
    max_retries: int = 2,
) -> Optional[Path]:
    """Render chapter with retries. If all retries fail, return None."""
    for attempt in range(1 + max_retries):
        if attempt > 0:
            log.warning("[%s] Retry rendering chapter (attempt %d/%d)...", chapter.tag, attempt + 1, 1 + max_retries)
            time.sleep(2.0)
        res = render_chapter(cfg, chapter, frame_paths, frame_durations, audio_path)
        if res and res.exists():
            return res
    return None


def generate_black_placeholder_chapter(
    cfg: PipelineConfig,
    chapter_tag: str,
    duration: float,
    overlay_text: str,
) -> Path:
    """Generate a silent black video placeholder of specified duration with a text overlay."""
    out_path = cfg.temp_chapters_dir / f"{chapter_tag}.mp4"
    if out_path.exists():
        return out_path

    tmp_path = cfg.temp_chapters_dir / f"{chapter_tag}.mp4.tmp"
    tmp_path.unlink(missing_ok=True)
    dur_str = f"{max(1.0, duration):.3f}"

    # Escape overlay text for ffmpeg drawtext filter
    escaped_text = overlay_text.replace("'", "'\\''").replace(":", "\\:")
    cmd = [
        "ffmpeg", "-y",
        "-f", "lavfi", "-i", f"color=c=black:s={CANVAS_W}x{CANVAS_H}:r={FPS}",
        "-f", "lavfi", "-i", f"anullsrc=r={AUDIO_SAMPLE_RATE}:cl=mono",
        "-t", dur_str,
        "-vf", f"drawtext=text='{escaped_text}':fontcolor=white:fontsize=48:x=(w-text_w)/2:y=(h-text_h)/2",
        "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p",
        "-c:a", "aac", "-b:a", AUDIO_BITRATE, "-ar", str(AUDIO_SAMPLE_RATE),
        "-r", str(FPS),
        "-f", "mp4",
        str(tmp_path),
    ]

    try:
        run_ffmpeg(cmd)
        atomic_promote(tmp_path, out_path)
        log.info("[%s] generated black placeholder video (%.1fs) -> %s", chapter_tag, duration, out_path.name)
        return out_path
    except Exception as e:
        log.error("[%s] failed to generate black placeholder video: %s", chapter_tag, e)
        tmp_path.unlink(missing_ok=True)
        raise




# ---------------------------------------------------------------------------
# 5b. AUDIO PADDING HELPER
# ---------------------------------------------------------------------------

def pad_audio_with_silence(audio_path: Path, target_duration: float) -> Path:
    """If the audio is shorter than target_duration, append silence to reach it.
    Returns the original path if already long enough, or a new padded path."""
    current = get_audio_duration(audio_path)
    if current >= target_duration:
        return audio_path
    padding_dur = target_duration - current
    out = audio_path.with_suffix('.padded.wav')
    # Fast path: append zero PCM frames in the input's own format (no
    # re-encode, sample-accurate) rather than spawning an ffmpeg
    # filter_complex concat per short segment. ffmpeg fallback on any error
    # or a non-WAV input.
    if str(audio_path).lower().endswith(".wav"):
        try:
            with wave.open(str(audio_path), "rb") as w:
                nch, sw, fr = w.getnchannels(), w.getsampwidth(), w.getframerate()
                data = w.readframes(w.getnframes())
            pad_frames = max(0, int(round(padding_dur * fr)))
            with wave.open(str(out), "wb") as w:
                w.setnchannels(nch)
                w.setsampwidth(sw)
                w.setframerate(fr)
                w.writeframes(data)
                w.writeframes(b"\x00" * (pad_frames * nch * sw))
            log.debug("Padded %s from %.1fs to %.1fs (+%.1fs silence, wave)",
                      audio_path.name, current, target_duration, padding_dur)
            return out
        except Exception as exc:
            log.debug("pure-python pad failed (%s) — using ffmpeg", exc)
    run_ffmpeg([
        "ffmpeg", "-y",
        "-i", str(audio_path),
        "-f", "lavfi", "-i", f"anullsrc=r={AUDIO_SAMPLE_RATE}:cl=mono",
        "-filter_complex", "[0:a][1:a]concat=n=2:v=0:a=1",
        "-t", f"{target_duration:.3f}",
        "-ar", str(AUDIO_SAMPLE_RATE), "-ac", "1",
        str(out),
    ])
    log.debug("Padded %s from %.1fs to %.1fs (+%.1fs silence)",
             audio_path.name, current, target_duration, padding_dur)
    return out


# ---------------------------------------------------------------------------
# 6. FFMPEG ZERO-REENCODE STREAM MERGER & BGM OVERLAY
# ---------------------------------------------------------------------------

def run_ffmpeg(cmd: List[str]) -> None:
    log.debug("Running: %s", " ".join(cmd))
    result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=600)
    if result.returncode != 0:
        log.error("ffmpeg command failed (exit %d):\nCMD: %s\nSTDERR:\n%s\nSTDOUT:\n%s",
                  result.returncode, " ".join(cmd), result.stderr or "", result.stdout or "")
        err_msg = (result.stderr or result.stdout or "").strip()
        last_lines = "\n".join(err_msg.splitlines()[-20:])
        raise RuntimeError(f"ffmpeg failed (exit {result.returncode}):\n{last_lines}")


def _llm_provider_chain(cfg: "PipelineConfig"):
    """Ordered [(provider, api_key, base_url, model), ...] to try for a text
    LLM call. Free tiers are included so a large job doesn't stall when one
    provider's daily quota runs out (the exact failure on the 328-ch run):

        openai (paid)  ->  groq (free 200k tok/day)  ->  gemini flash-lite
        (free ~1k req/day, no card)  ->  openrouter free models  ->  ollama (local)

    An explicit `cfg.narration_provider` is moved to the front but the rest
    stay as fallbacks.
    """
    chain = []
    _ok = cfg.openai_api_key or os.environ.get("OPENAI_API_KEY")
    if _ok:
        chain.append(("openai", _ok, None, cfg.narration_model or cfg.openai_model))
    _gk = cfg.groq_api_key or os.environ.get("GROQ_API_KEY")
    if _gk:
        chain.append(("groq", _gk, GROQ_BASE_URL, cfg.narration_model or cfg.groq_model))
    _gem = getattr(cfg, "gemini_api_key", None) or os.environ.get("GEMINI_API_KEY")
    if _gem:
        chain.append(("gemini", _gem, GEMINI_BASE_URL,
                      os.environ.get("RECAP_GEMINI_TEXT_MODEL", "gemini-2.5-flash-lite")))
    _orr = getattr(cfg, "openrouter_api_key", None) or os.environ.get("OPENROUTER_API_KEY")
    if _orr:
        chain.append(("openrouter", _orr, OPENROUTER_BASE_URL,
                      os.environ.get("RECAP_OPENROUTER_TEXT_MODEL",
                                     "meta-llama/llama-3.3-70b-instruct:free")))
    if os.environ.get("OLLAMA_BASE_URL") or shutil.which("ollama"):
        chain.append(("ollama", "ollama",
                      os.environ.get("OLLAMA_BASE_URL", "http://localhost:11434") + "/v1",
                      cfg.narration_model or os.environ.get("OLLAMA_TEXT_MODEL", "llama3.2:3b")))
    p = getattr(cfg, "narration_provider", "auto")
    if p not in ("auto", "none", None):
        chain.sort(key=lambda t: 0 if t[0] == p else 1)
    return chain


_LLM_RATE_RE = re.compile(
    r"429|rate.?limit|quota|resource_exhausted|too many requests|"
    r"\b50[0-9]\b|overloaded|unavailable|timeout|timed out|connection", re.IGNORECASE)


def _llm_chat(cfg, messages, temperature: float = 0.4, max_tokens: Optional[int] = None,
              timeout: int = 90, purpose: str = "llm"):
    """Run one chat completion, walking the provider chain until one answers.
    A rate-limit / quota / 5xx / timeout jumps straight to the next provider;
    a transient error gets one local retry first. Returns (text, provider) or
    (None, None) — callers keep their existing 'None -> verbatim' fallback."""
    from openai import OpenAI
    chain = _llm_provider_chain(cfg)
    if not chain:
        return None, None
    last_err = "no provider"
    for (prov, key, base, model) in chain:
        for attempt in (1, 2):
            try:
                client = OpenAI(api_key=key, base_url=base) if base else OpenAI(api_key=key)
                kw = dict(model=model, messages=messages, temperature=temperature, timeout=timeout)
                if max_tokens:
                    kw["max_tokens"] = max_tokens
                r = client.chat.completions.create(**kw)
                _m = r.choices[0].message
                txt = (_m.content or "").strip()
                # some Groq "reasoning" models (gpt-oss) put the answer in a
                # separate field; others (qwen3.6) leak a <think> block.
                if not txt:
                    txt = (getattr(_m, "reasoning", "") or "").strip()
                txt = re.sub(r"<think>.*?</think>", "", txt, flags=re.DOTALL).strip()
                txt = re.sub(r"^<think>.*$", "", txt, flags=re.DOTALL).strip()
                if txt:
                    if prov != chain[0][0]:
                        log.info("[%s] LLM via fallback %s/%s", purpose, prov, model)
                    return txt, prov
                last_err = f"{prov}: empty response"
            except Exception as e:
                last_err = f"{prov}: {e}"
                if _LLM_RATE_RE.search(str(e)):
                    break  # this provider is out — next one
                if attempt == 1:
                    time.sleep(0.6)
    log.warning("[%s] all %d LLM provider(s) failed (%s)", purpose, len(chain), last_err)
    return None, None


def _resolve_llm_client(cfg: "PipelineConfig"):
    """Return (client, model, provider) for one-off LLM calls (intro synopsis),
    reusing the same provider precedence as rephrase_text. (None, None, 'none')
    if nothing is available."""
    from openai import OpenAI
    provider = cfg.narration_provider
    openai_key = cfg.openai_api_key or os.environ.get("OPENAI_API_KEY")
    if provider in ("auto", "none"):
        if openai_key:
            provider = "openai"
        elif cfg.groq_api_key:
            provider = "groq"
        elif os.environ.get("OLLAMA_BASE_URL") or shutil.which("ollama"):
            provider = "ollama"
        else:
            return None, None, "none"
    try:
        if provider == "ollama":
            base = os.environ.get("OLLAMA_BASE_URL", "http://localhost:11434") + "/v1"
            return OpenAI(api_key="ollama", base_url=base), \
                   cfg.narration_model or os.environ.get("OLLAMA_TEXT_MODEL", "llama3.2:3b"), "ollama"
        if provider == "openai":
            return OpenAI(api_key=openai_key), cfg.narration_model or cfg.openai_model, "openai"
        if provider == "groq":
            return OpenAI(api_key=cfg.groq_api_key, base_url=GROQ_BASE_URL), \
                   cfg.narration_model or cfg.groq_model, "groq"
    except Exception as e:
        log.warning("intro LLM client init failed (%s)", e)
    return None, None, "none"


def _make_title_card(cfg: "PipelineConfig", chapters: "List[Chapter]", title: str) -> Path:
    """Blurred first-page art + darkening + big series title + chapter range."""
    from PIL import Image, ImageFilter, ImageDraw, ImageFont
    out = cfg.work_dir / "intro_card.jpg"
    # Pick the most colourful available page for the backdrop (page 1 of a
    # webtoon is often a dark title splash); fall back to the first page.
    pages = [p for ch in chapters for p in ch.panel_paths if p.exists()]
    bg_src = None
    if pages:
        best_sat = -1.0
        for p in pages[: min(len(pages), 8)]:
            try:
                with Image.open(p) as t:
                    sm = t.convert("HSV").resize((64, 64))
                    sat = float(np.array(sm)[:, :, 1].mean())
                if sat > best_sat:
                    best_sat, bg_src = sat, p
            except Exception:
                continue
        bg_src = bg_src or pages[0]
    if bg_src is not None:
        with Image.open(bg_src) as im:
            im = im.convert("RGB")
            sc = max(CANVAS_W / im.width, CANVAS_H / im.height)
            im = im.resize((int(im.width * sc), int(im.height * sc)), Image.LANCZOS)
            x = max(0, (im.width - CANVAS_W) // 2)
            y = max(0, (im.height - CANVAS_H) // 2)
            bg = im.crop((x, y, x + CANVAS_W, y + CANVAS_H)).filter(ImageFilter.GaussianBlur(26))
        bg = Image.eval(bg, lambda p: int(p * 0.52)).convert("RGB")
    else:
        bg = Image.new("RGB", (CANVAS_W, CANVAS_H), (12, 14, 22))

    draw = ImageDraw.Draw(bg)

    def _font(size: int):
        for p in ("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
                  "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf"):
            if os.path.exists(p):
                return ImageFont.truetype(p, size)
        return ImageFont.load_default()

    # word-wrap the title to <= ~18 chars/line at a large size
    words, lines, cur = title.split(), [], ""
    for w in words:
        if len((cur + " " + w).strip()) <= 22:
            cur = (cur + " " + w).strip()
        else:
            lines.append(cur); cur = w
    if cur:
        lines.append(cur)
    tf = _font(96)
    total_h = sum(draw.textbbox((0, 0), ln, font=tf)[3] + 16 for ln in lines)
    y = (CANVAS_H - total_h) // 2 - 40
    for ln in lines:
        bb = draw.textbbox((0, 0), ln, font=tf)
        tw = bb[2] - bb[0]
        px = (CANVAS_W - tw) // 2
        for dx, dy in ((-3, -3), (3, -3), (-3, 3), (3, 3)):
            draw.text((px + dx, y + dy), ln, font=tf, fill=(0, 0, 0))
        draw.text((px, y), ln, font=tf, fill=(255, 255, 255))
        y += (bb[3] - bb[1]) + 28

    sub = "Chapter " + (chapters[0].name.split("_")[-1] if chapters else "1")
    n = len(chapters)
    if n > 1:
        sub = f"Chapters {chapters[0].name.split('_')[-1]}–{chapters[-1].name.split('_')[-1]}"
    sf = _font(56)
    bb = draw.textbbox((0, 0), sub, font=sf)
    px = (CANVAS_W - (bb[2] - bb[0])) // 2
    draw.text((px + 2, y + 22), sub, font=sf, fill=(0, 0, 0))
    draw.text((px, y + 20), sub, font=sf, fill=(255, 210, 90))

    bg.save(out, quality=92)
    return out


INTRO_MAX_SECONDS = 10.0


def build_intro_video(cfg: "PipelineConfig", chapters: "List[Chapter]") -> Optional[Path]:
    """Short spoken title drop over a title card (<= INTRO_MAX_SECONDS),
    prepended to the recap. Template-based — no LLM, no translation."""
    out_path = cfg.temp_chapters_dir / "chap_000_intro.mp4"
    if out_path.exists():
        log.info("intro video already built — reusing")
        return out_path

    title = cfg.recap_title or cfg.input_dir.name.replace("_", " ").replace("-", " ").strip().title()
    if chapters:
        first_n = chapters[0].name.split("_")[-1].lstrip("0") or "1"
        last_n = chapters[-1].name.split("_")[-1].lstrip("0") or "1"
        span = f"chapter {first_n}" if len(chapters) == 1 else f"chapters {first_n} to {last_n}"
    else:
        span = "chapter 1"
    channel = (cfg.watermark or "").strip()
    lead = f"Welcome to {channel}. " if channel else ""
    script = f"{lead}This is {title}, {span}. Let's get into it."
    (cfg.temp_scripts_dir / "chap_000_intro.txt").write_text(script, encoding="utf-8")
    log.info("intro line: %r", script)

    # TTS (Piper) -> loudnorm stereo
    raw_wav = cfg.temp_audio_dir / "intro_raw.wav"
    audio_wav = cfg.temp_audio_dir / "intro.wav"
    try:
        _synthesize_with_piper(script, raw_wav)
    except Exception as e:
        log.warning("intro TTS failed (%s) — skipping intro", e)
        return None
    try:
        run_ffmpeg([
            "ffmpeg", "-y", "-i", str(raw_wav),
            "-af", f"loudnorm=I={TARGET_LOUDNESS_LUFS}:TP=-1.5:LRA=11",
            "-ar", str(AUDIO_SAMPLE_RATE), "-ac", "2", str(audio_wav),
        ])
    except RuntimeError:
        run_ffmpeg(["ffmpeg", "-y", "-i", str(raw_wav), "-ar", str(AUDIO_SAMPLE_RATE), "-ac", "2", str(audio_wav)])
    dur = get_audio_duration(audio_wav)
    if dur < 1.5:
        log.warning("intro audio unexpectedly short (%.1fs) — skipping intro", dur)
        return None
    if dur > INTRO_MAX_SECONDS:
        trimmed = cfg.temp_audio_dir / "intro_trim.wav"
        run_ffmpeg(["ffmpeg", "-y", "-i", str(audio_wav), "-t", f"{INTRO_MAX_SECONDS:.2f}",
                    "-ar", str(AUDIO_SAMPLE_RATE), "-ac", "2", str(trimmed)])
        audio_wav, dur = trimmed, INTRO_MAX_SECONDS

    card = _make_title_card(cfg, chapters, title)
    tmp = cfg.temp_chapters_dir / "chap_000_intro.mp4.tmp"
    tmp.unlink(missing_ok=True)
    vf = f"scale={CANVAS_W}:{CANVAS_H},format=yuv420p,fps={FPS}"
    if getattr(cfg, "watermark", None):
        wm = str(cfg.watermark).replace("\\", "").replace("'", "").replace(":", " ")
        vf += (f",drawtext=text='{wm}':fontcolor=white@0.55:fontsize=34:"
               f"shadowcolor=black@0.6:shadowx=2:shadowy=2:x=w-tw-32:y=h-th-28")
    run_ffmpeg([
        "ffmpeg", "-y",
        "-loop", "1", "-framerate", str(FPS), "-i", str(card),
        "-i", str(audio_wav),
        "-vf", vf,
        "-c:v", "libx264", "-preset", "veryfast", "-tune", "stillimage", "-crf", "20",
        "-c:a", "aac", "-b:a", AUDIO_BITRATE, "-ar", str(AUDIO_SAMPLE_RATE), "-ac", "2",
        "-shortest", "-t", f"{dur + 0.4:.3f}",
        "-f", "mp4", str(tmp),
    ])
    atomic_promote(tmp, out_path)
    log.info("intro video built (%.1fs) -> %s", dur, out_path.name)
    return out_path


def merge_chapters(cfg: PipelineConfig, chapter_videos: List[Path]) -> Path:
    """Zero-reencode concat of all chapter mp4s via ffmpeg's concat demuxer."""
    valid_videos: List[Path] = []
    for idx, cv in enumerate(chapter_videos, start=1):
        if cv and cv.exists() and cv.stat().st_size > 1024:
            valid_videos.append(cv)
        else:
            log.warning("Chapter video %s missing or corrupt during merge — substituting placeholder", cv)
            placeholder = generate_black_placeholder_chapter(
                cfg,
                f"chap_{idx:03d}_missing",
                SILENT_FRAME_DURATION,
                f"Chapter {idx} unavailable",
            )
            valid_videos.append(placeholder)

    chapter_videos = valid_videos

    concat_list = cfg.work_dir / "concat_list.txt"
    with concat_list.open("w", encoding="utf-8") as f:
        for cv in chapter_videos:
            f.write(f"file '{cv.resolve().as_posix()}'\n")

    merged_path = cfg.work_dir / "master_merged.mp4"
    if merged_path.exists():
        log.info("Merged master file already exists — skipping merge step (resume)")
        return merged_path

    # Individual chapters are already QA-validated on their own, but the
    # concat step itself (stream copy across N files) can still fail
    # partway through or get killed mid-write — write to a tmp path and
    # only promote to `merged_path` (the resume-checked path above) after
    # the merged file passes QA, for the same reason as render_chapter.
    tmp_path = cfg.work_dir / "master_merged.mp4.tmp"
    tmp_path.unlink(missing_ok=True)

    log.info("Merging %d chapter videos via ffmpeg stream copy...", len(chapter_videos))
    run_ffmpeg(
        [
            "ffmpeg", "-y", "-f", "concat", "-safe", "0",
            "-i", str(concat_list),
            "-c", "copy",
            # Same fix as render_chapter: force the output muxer instead of
            # relying on tmp_path's extension (".mp4.tmp" -> ffmpeg would
            # otherwise see ".tmp" and fail with "Unable to find a
            # suitable output format").
            "-f", "mp4",
            str(tmp_path),
        ]
    )

    qa = video_qa(tmp_path, audio_expected=True)
    if not qa.ok:
        quarantine_dir = cfg.work_dir / "quarantine"
        quarantine_dir.mkdir(exist_ok=True)
        bad_path = quarantine_dir / f"master_merged.{int(time.time())}.{qa.reason}.bad"
        try:
            tmp_path.rename(bad_path)
        except OSError:
            tmp_path.unlink(missing_ok=True)
        raise RuntimeError(f"merged master video failed QA ({qa.reason}) — see {bad_path}")

    atomic_promote(tmp_path, merged_path)
    log.info("Merge complete + QA-validated -> %s", merged_path.name)

    # Chapter markers for the player scrubber: cumulative start time of each
    # chapter video (the intro, if present, is chapter_videos[0]).
    try:
        marks, offset = [], 0.0
        for i, cv in enumerate(chapter_videos):
            name = cv.stem
            if name.startswith("intro") or "intro" in name:
                label = "Intro"
            else:
                m = re.search(r"(\d+)", name)
                label = f"Chapter {int(m.group(1))}" if m else name
            marks.append({"index": i, "title": label, "start": round(offset, 2)})
            offset += max(0.0, get_audio_duration(cv))
        out_dir = cfg.output_path.parent
        out_dir.mkdir(parents=True, exist_ok=True)
        (out_dir / "chapters.json").write_text(
            json.dumps({"chapters": marks, "total": round(offset, 2)}, indent=2),
            encoding="utf-8",
        )
    except Exception as e:  # pragma: no cover
        log.debug("chapter-marker generation skipped (%s)", e)

    return merged_path


def finalize_output(cfg: PipelineConfig, merged_path: Path) -> Path:
    """Copy the merged video to the final output path, mixing in background
    music (sidechain-ducked under narration) when cfg.bgm_path is set.

    `merged_path` was already QA-validated by merge_chapters, but the tmp
    path + re-check + atomic rename dance below still applies either way: a
    crash or a full disk mid-copy/mid-encode can leave a truncated file
    sitting at cfg.output_path — the one path anything downstream (upload,
    YouTube metadata step, the person opening the file) actually trusts as
    "the finished video." That path must never be observably partial.
    """
    cfg.output_path.parent.mkdir(parents=True, exist_ok=True)
    tmp_path = cfg.output_path.with_suffix(cfg.output_path.suffix + ".tmp")
    tmp_path.unlink(missing_ok=True)

    if cfg.bgm_path and cfg.bgm_path.exists():
        log.info("Mixing background music (%s) into final output...", cfg.bgm_path.name)
        try:
            # -stream_loop -1 loops the BGM indefinitely; `-shortest` on the
            # output then trims everything to the (unchanged) video length,
            # so this works regardless of whether the track is shorter or
            # longer than the recap. sidechaincompress ducks the BGM
            # whenever narration is present, keyed off the narration track
            # itself; amix folds the ducked BGM back under the voice.
            # Video stream is copied untouched — only audio is re-encoded.
            duck_ratio = 8  # higher = more aggressive ducking under voice
            filter_complex = (
                f"[1:a]volume=0.35[bgm];"
                f"[bgm][0:a]sidechaincompress=threshold=0.05:ratio={duck_ratio}:"
                f"attack=20:release=400:makeup=1[ducked];"
                f"[0:a][ducked]amix=inputs=2:duration=first:dropout_transition=2:weights=1 1[aout]"
            )
            run_ffmpeg([
                "ffmpeg", "-y",
                "-i", str(merged_path),
                "-stream_loop", "-1", "-i", str(cfg.bgm_path),
                "-filter_complex", filter_complex,
                "-map", "0:v", "-map", "[aout]",
                "-c:v", "copy",
                "-c:a", "aac", "-b:a", AUDIO_BITRATE, "-ar", str(AUDIO_SAMPLE_RATE),
                "-shortest",
                "-f", "mp4",
                str(tmp_path),
            ])
        except RuntimeError as e:
            # BGM mixing is a nice-to-have, not worth failing a multi-hour
            # unattended job over — fall back to the clean narration-only cut.
            log.error("BGM mix failed (%s) — falling back to narration-only output", e)
            tmp_path.unlink(missing_ok=True)
            shutil.copy2(merged_path, tmp_path)
    else:
        log.info("Copying merged video to final output (no BGM configured)...")
        shutil.copy2(merged_path, tmp_path)

    qa = video_qa(tmp_path, audio_expected=True)
    if not qa.ok:
        tmp_path.unlink(missing_ok=True)
        raise RuntimeError(
            f"final output failed QA ({qa.reason}) — refusing to mark the job complete"
        )

    atomic_promote(tmp_path, cfg.output_path)
    log.info("Final master video written + QA-validated -> %s", cfg.output_path)
    return cfg.output_path


# ---------------------------------------------------------------------------
# CLEANUP
# ---------------------------------------------------------------------------

def cleanup_temp(cfg: PipelineConfig) -> None:
    if cfg.keep_temp:
        log.info("--keep-temp set: leaving working directory at %s", cfg.work_dir)
        return
    log.info("Cleaning up temporary working directory: %s", cfg.work_dir)
    shutil.rmtree(cfg.work_dir, ignore_errors=True)


# ---------------------------------------------------------------------------
# ORCHESTRATION
# ---------------------------------------------------------------------------

def run_pipeline(cfg: PipelineConfig) -> None:
    start = time.time()
    cfg.ensure_dirs()
    # Ensure the output directory exists.
    cfg.output_path.parent.mkdir(parents=True, exist_ok=True)

    # Fail fast rather than start a doomed multi-day batch: on an Oracle
    # free-tier instance, running out of disk mid-encode is a much worse
    # failure mode than never starting (a partially-full disk from an
    # earlier crashed run, temp files from a different job, etc. are all
    # realistic on a small always-on box). This is a pre-flight check
    # only — the per-chapter check inside the loop below is what catches
    # resource pressure that builds up DURING a long run.
    # SQLiteStateStore gives every chapter's stage/state/error/retry history
    # a queryable, durable record (survives process restarts, unlike the
    # JSON progress file which the Node service just polls for the current
    # snapshot) — this is what turns "filesystem existence checks" into the
    # kind of real state tracking a multi-day unattended batch needs to be
    # debuggable after the fact.
    state_store = SQLiteStateStore(cfg.work_dir / "pipeline_state.sqlite3")
    state_store.record(cfg.job_id, Stage.JOB, State.RUNNING)

    resource_guard = ResourceGuard(
        min_free_disk_bytes=int(cfg.min_free_disk_gb * 1_000_000_000),
        min_available_ram_bytes=int(cfg.min_available_ram_mb * 1_000_000),
        state=state_store,
    )
    preflight = resource_guard.wait_for_resources(cfg.work_dir, job_id=cfg.job_id, stage=Stage.JOB, check_interval_sec=15, max_wait_sec=120, logger=log)
    if not preflight.ok:
        log.warning(
            f"Resource threshold not met at preflight: {preflight.reason} (free disk: "
            f"{preflight.free_disk_bytes / 1e9:.2f}GB, available RAM: "
            f"{preflight.available_ram_bytes / 1e6:.0f}MB, load avg: {preflight.load1:.1f} "
            f"on {os.cpu_count() or '?'} cores). Proceeding best-effort."
        )
    elif preflight.load1 and os.cpu_count() and preflight.load1 > os.cpu_count() * 2:
        # ResourceGuard deliberately does NOT gate/wait on load average the
        # way it does disk and RAM (see production.py) — on a small
        # always-on box the load here is mostly the pipeline's OWN work
        # (ffmpeg + PaddleOCR + concurrent TTS), not a competing external
        # process, so "pause until it drops" would just stall every
        # chapter for the full max_wait_sec with nothing ever recovering.
        # Just surface it: sustained load this high (observed 5.5-5.9 on a
        # 2-vCPU box during a 100-chapter run) is the most likely cause of
        # edge-tts's "No audio was received" failures (event-loop/socket
        # servicing starved past its own timeout) -- see the retry added in
        # synthesize_segment_audio, which is the actual mitigation.
        log.warning(
            f"Sustained high CPU load at preflight: {preflight.load1:.1f} avg on "
            f"{os.cpu_count()} cores -- expect more edge-tts timeouts than usual "
            f"(auto-retried, falls back to Piper ONNX)."
        )

    chapters = discover_chapters(cfg)
    total = len(chapters)
    chapter_videos: List[Path] = []
    # Chapters that rendering genuinely failed for, where a black
    # "unavailable" placeholder was substituted so the merged video still
    # has a slot for every chapter instead of jump-cutting. Tracked
    # SEPARATELY from chapter_videos (which now includes placeholders) so
    # the end-of-run success/UNCERTAIN decision below can't be fooled by a
    # placeholder padding chapter_videos up to `total` and looking like a
    # clean run.
    placeholder_chapters: List[str] = []
    prev_tail = ""

    cfg.write_progress("render", 0, total, f"Starting pipeline over {total} chapters")

    for chapter in chapters:
        t0 = time.time()
        log.info("=== Chapter %d/%d (%s) ===", chapter.index, total, chapter.name)
        cfg.write_progress("render", chapter.index - 1, total, f"Chapter {chapter.index}/{total}: {chapter.name}")

        # Resource pressure on a long batch typically builds up over time
        # (temp files accumulating, other processes on the same small
        # instance) rather than being present at startup — wait for
        # resources before each chapter's ffmpeg/TTS/OCR work.
        resource_status = resource_guard.wait_for_resources(
            cfg.work_dir, job_id=cfg.job_id, stage=Stage.CHAPTER, check_interval_sec=60, max_wait_sec=600, logger=log
        )
        if not resource_status.ok:
            log.warning(
                "[%s] resource guard threshold still not met after pause: %s (free disk: %.2fGB, "
                "available RAM: %.0fMB) — attempting chapter best-effort",
                chapter.tag, resource_status.reason,
                resource_status.free_disk_bytes / 1e9, resource_status.available_ram_bytes / 1e6,
            )
            cfg.write_progress(
                "render", chapter.index - 1, total,
                f"Resource warning: {resource_status.reason}", status="warning",
            )

        existing_video = cfg.temp_chapters_dir / f"{chapter.tag}.mp4"
        if existing_video.exists():
            log.info("[%s] fully rendered already — resuming past this chapter", chapter.tag)
            chapter_videos.append(existing_video)
            state_store.record(cfg.job_id, Stage.CHAPTER, State.COMPLETE, chapter_id=chapter.tag, artifact_path=existing_video)
            # Keep narrative continuity even when resuming: pull tail from cached script.
            script_cache = cfg.temp_scripts_dir / f"{chapter.tag}.txt"
            if script_cache.exists():
                prev_tail = last_sentences(script_cache.read_text(encoding="utf-8"))
            continue

        state_store.record(cfg.job_id, Stage.CHAPTER, State.RUNNING, chapter_id=chapter.tag)
        try:
            # NOTE: stage is "render" here, not "slice" — in the render phase this
            # is just a fast manifest re-verify (slices already exist from the
            # --slice-only pass). Reporting "slice" would drop the progress bar
            # back into the 10-45% band mid-render.
            cfg.write_progress("render", chapter.index - 1, total,
                               f"Chapter {chapter.index}/{total}: preparing panels…",
                               frac=0.02, substage="frame")
            frame_data = slice_chapter_panels(cfg, chapter)

            manifest_path = cfg.temp_slices_dir / chapter.tag / "manifest.json"
            manifest = load_or_migrate_manifest(manifest_path, chapter=chapter, job_id=cfg.job_id)
            if manifest and manifest.frames:
                frame_paths = [Path(f.path) if Path(f.path).exists() else cfg.temp_slices_dir / chapter.tag / f.filename for f in manifest.frames]
                frame_sources = [f.source_index for f in manifest.frames]
            else:
                frame_paths = [fp for fp, _ in frame_data]
                frame_sources = [si for _, si in frame_data]

            # OPTIONAL: honour a manual-review exclusion list (work/excluded_frames.json,
            # written by the "Review panels" step). Entries are "chap_XXX/frame_NNNNN.jpg".
            # Drop those frames + their narration so they never reach the render.
            _excluded = _load_excluded_frames(cfg)
            if _excluded:
                _keep = [i for i, fp in enumerate(frame_paths)
                         if f"{chapter.tag}/{fp.name}" not in _excluded]
                if len(_keep) < len(frame_paths):
                    dropped = len(frame_paths) - len(_keep)
                    frame_paths = [frame_paths[i] for i in _keep]
                    frame_sources = [frame_sources[i] for i in _keep]
                    if manifest and manifest.frames:
                        manifest.frames = [manifest.frames[i] for i in _keep if i < len(manifest.frames)]
                    log.info("[%s] manual review: dropped %d panel(s), rendering %d",
                             chapter.tag, dropped, len(frame_paths))
                    cfg.write_progress("render", chapter.index - 1, total,
                                       f"Chapter {chapter.index}/{total}: dropped {dropped} reviewed panel(s)",
                                       frac=0.03, substage="frame")

            if not frame_paths:
                log.warning("[%s] every panel was excluded in review — skipping chapter", chapter.tag)
                continue

            # F3: drop a leading/trailing frame that is a scanlator credits /
            # studio / chapter-title card — otherwise it renders as 1-2 s of
            # silent filler at every chapter boundary. Signal: OCR *did* read
            # text from it, but `_clean_source_text` strips the whole thing as
            # scanlation noise (studio name, URL, "Chapter N"). A genuine
            # silent establishing shot has NO OCR text at all, so it's safe —
            # this only fires on frames that are literally all-watermark.
            if (os.environ.get("RECAP_DROP_BOUNDARY_CREDITS", "1").lower() not in ("0", "false", "no")
                    and len(frame_paths) > 3 and chapter.image_narrations):
                def _boundary_credits(i: int) -> bool:
                    fp = frame_paths[i]
                    fe = manifest.frames[i] if (manifest and i < len(manifest.frames)) else None
                    if fe:
                        ne = (chapter.image_narrations.get(fe.frame_id)
                              or chapter.image_narrations.get(fe.filename)
                              or chapter.image_narrations.get(fp.name))
                    else:
                        ne = chapter.image_narrations.get(fp.name)
                    raw = parse_narration_item(ne)["text"].strip()
                    if not raw or len(re.sub(r"[^A-Za-z]", "", raw)) < 4:
                        return False  # no real OCR text → could be a silent panel, keep
                    if _clean_source_text(raw).strip():
                        return False  # real narratable text survives cleaning → keep
                    # OCR read a card's worth of text and it ALL cleaned away as
                    # credits / studio / "CHAPTER N …" front-matter. In the tight
                    # first/last-few window that's card enough to drop; the
                    # visual check is a tie-breaker for the borderline case of a
                    # story panel whose only text is a stamped watermark.
                    if _is_credits_blob(raw) or re.match(
                            r"^\W*(?:(?:season\s*\d+\s*)?(?:chapter|episode)\s*\d+|prologue|epilogue)\b",
                            raw, re.IGNORECASE):
                        return True
                    try:
                        from PIL import Image as _PILImage
                        arr = np.array(_PILImage.open(fp).convert("RGB"))
                        return _looks_like_credits_panel(arr) or _looks_like_scanlator_card(arr)
                    except Exception:
                        return True

                # scan the first few and last few frames — the studio/title
                # card usually sits behind a cold-open panel or two, and the
                # end-of-chapter credits card behind the final story beat.
                _drop = set()
                _n = len(frame_paths)
                _window = min(4, _n // 3)
                for i in list(range(_window)) + list(range(_n - _window, _n)):
                    if 0 <= i < _n and i not in _drop and _boundary_credits(i):
                        _drop.add(i)
                if _drop:
                    _keep = [i for i in range(len(frame_paths)) if i not in _drop]
                    frame_paths = [frame_paths[i] for i in _keep]
                    frame_sources = [frame_sources[i] for i in _keep]
                    if manifest and manifest.frames:
                        manifest.frames = [manifest.frames[i] for i in _keep if i < len(manifest.frames)]
                    log.info("[%s] dropped %d boundary credits/title frame(s)", chapter.tag, len(_drop))

            # Near-duplicate drop: webtoons repeat panels ("previously on…"
            # strips, flashbacks). Keep the FIRST occurrence, drop repeats.
            # In-chapter always; cross-chapter (flashbacks) only when
            # RECAP_DEDUP_CROSS=1 and with a tighter threshold. Never drops
            # below a 55%%-of-frames floor.
            if (os.environ.get("RECAP_DEDUP_FRAMES", "1").lower() not in ("0", "false", "no")
                    and len(frame_paths) > 6):
                _in_dist = int(os.environ.get("RECAP_DEDUP_DIST", "26"))   # of 512 bits (~95%)
                _x_dist = int(os.environ.get("RECAP_DEDUP_CROSS_DIST", "16"))
                _cross = os.environ.get("RECAP_DEDUP_CROSS", "0").lower() in ("1", "true", "yes")
                _hashes = [_frame_dhash(p) for p in frame_paths]
                _kept_h: List[int] = []
                _keep, _ddrop = [], 0
                _floor = max(6, int(0.55 * len(frame_paths)))
                for i, h in enumerate(_hashes):
                    if h is None:
                        _keep.append(i); continue
                    dup = any(_ham64(h, kh) <= _in_dist for kh in _kept_h)
                    if not dup and _cross:
                        dup = any(_ham64(h, sh) <= _x_dist for sh in _RECAP_SEEN_HASHES)
                    if dup and (len(_keep) + (len(_hashes) - i - 1)) > _floor:
                        _ddrop += 1
                        continue
                    _keep.append(i)
                    _kept_h.append(h)
                if _ddrop:
                    frame_paths = [frame_paths[i] for i in _keep]
                    frame_sources = [frame_sources[i] for i in _keep]
                    if manifest and manifest.frames:
                        manifest.frames = [manifest.frames[i] for i in _keep if i < len(manifest.frames)]
                    log.info("[%s] dropped %d near-duplicate frame(s) (%d -> %d)",
                             chapter.tag, _ddrop, len(_keep) + _ddrop, len(_keep))
                _RECAP_SEEN_HASHES.extend(h for h in _kept_h if h is not None)

            log.info("[%s] %d canonical frames from %d source pages", chapter.tag, len(frame_paths), len(chapter.panel_paths))
            cfg.write_progress("render", chapter.index - 1, total,
                               f"Chapter {chapter.index}/{total}: {len(frame_paths)} panels ready",
                               frac=0.05, substage="tts")

            # Build an ordered list of (tag, text, frame_positions) "segments" —
            # each one gets exactly ONE continuous edge-tts synthesis call, then
            # real word timestamps from that single clip drive per-frame timing.
            segments: List[tuple] = []  # (tag, text, positions)

            if chapter.image_narrations:
                frame_keyed = any(
                    k.startswith("frame_") or (manifest and k in [f.frame_id for f in manifest.frames])
                    for k in chapter.image_narrations.keys()
                )

                if frame_keyed:
                    log.info("[%s] per-frame narration mode: %d frames (canonical frame transcriptions)",
                             chapter.tag, len(frame_paths))

                    # One segment per frame, EXCEPT scroll_frame siblings
                    # (the panning sub-frames sliced from one tall UI card)
                    # which share a scroll_group and are collapsed into ONE
                    # segment. OCR'ing/narrating each panning window on its
                    # own would chop one card's text at arbitrary pixel
                    # boundaries into several disjoint, garbled clips.
                    position_groups: List[List[int]] = []
                    pos = 0
                    while pos < len(frame_paths):
                        f_entry = manifest.frames[pos] if (manifest and pos < len(manifest.frames)) else None
                        group_key = f_entry.scroll_group if f_entry else None
                        if group_key:
                            group = [pos]
                            pos += 1
                            while pos < len(frame_paths):
                                next_entry = manifest.frames[pos] if (manifest and pos < len(manifest.frames)) else None
                                if next_entry and next_entry.scroll_group == group_key:
                                    group.append(pos)
                                    pos += 1
                                else:
                                    break
                            position_groups.append(group)
                        else:
                            position_groups.append([pos])
                            pos += 1

                    for positions in position_groups:
                        fragments: List[str] = []
                        statuses: List[str] = []
                        for gpos in positions:
                            fp = frame_paths[gpos]
                            f_entry = manifest.frames[gpos] if (manifest and gpos < len(manifest.frames)) else None
                            raw_narr_entry = None
                            if f_entry:
                                raw_narr_entry = (
                                    chapter.image_narrations.get(f_entry.frame_id)
                                    or chapter.image_narrations.get(f_entry.filename)
                                    or chapter.image_narrations.get(fp.name)
                                )
                            else:
                                raw_narr_entry = chapter.image_narrations.get(fp.name)

                            parsed = parse_narration_item(raw_narr_entry)
                            raw_text, ocr_status = parsed["text"], parsed["status"]
                            if f_entry:
                                f_entry.ocr_status = ocr_status
                                f_entry.ocr_text = raw_text
                            if raw_text.strip():
                                fragments.append(raw_text.strip())
                            statuses.append(ocr_status)

                        img_tag = f"{chapter.tag}_frm{positions[0] + 1:04d}"
                        frame_names = [frame_paths[p].name for p in positions]

                        if not fragments:
                            if statuses and all(s == OcrStatus.FAILED for s in statuses):
                                log.warning("[%s] [%s] OCR FAILED for frame(s) %s — retaining FAILED status, producing silent frame(s)",
                                            chapter.tag, img_tag, frame_names)
                                segments.append((f"frm{positions[0] + 1:04d}", "", positions, OcrStatus.FAILED))
                            else:
                                log.info("[%s] [%s] NO_TEXT confirmed for frame(s) %s", chapter.tag, img_tag, frame_names)
                                segments.append((f"frm{positions[0] + 1:04d}", "", positions, OcrStatus.NO_TEXT))
                        else:
                            combined_text = _join_scroll_fragments(fragments) if len(positions) > 1 else fragments[0]
                            overall_status = OcrStatus.UNCERTAIN if OcrStatus.UNCERTAIN in statuses else OcrStatus.SUCCESS
                            if overall_status == OcrStatus.UNCERTAIN:
                                log.warning("[%s] [%s] OCR UNCERTAIN for frame(s) %s — using available text", chapter.tag, img_tag, frame_names)
                            translated = translate_text(cfg, combined_text, img_tag)
                            rephrased = rephrase_text(cfg, translated, img_tag, prev_tail)
                            if rephrased:
                                prev_tail = last_sentences(rephrased)
                            segments.append((f"frm{positions[0] + 1:04d}", rephrased, positions, overall_status))
                else:
                    log.info("[%s] per-image narration mode: %d source images, %d frames",
                             chapter.tag, len(chapter.panel_paths), len(frame_paths))
                    # Legacy: translate + rephrase each source image's narration.
                    panel_narrations: dict = {}  # panel_index -> (rephrased_text, status)
                    for idx, panel_path in enumerate(chapter.panel_paths):
                        parsed = parse_narration_item(chapter.image_narrations.get(panel_path.name))
                        raw_text, ocr_status = parsed["text"], parsed["status"]
                        img_tag = f"{chapter.tag}_img{idx + 1:03d}"

                        if ocr_status == OcrStatus.FAILED:
                            log.warning("[%s] [%s] OCR FAILED for source panel %s", chapter.tag, img_tag, panel_path.name)
                            panel_narrations[idx] = ("", OcrStatus.FAILED)
                        elif ocr_status == OcrStatus.NO_TEXT:
                            panel_narrations[idx] = ("", OcrStatus.NO_TEXT)
                        elif ocr_status == OcrStatus.UNCERTAIN:
                            log.warning("[%s] [%s] OCR UNCERTAIN for source panel %s (confidence=%.2f)", chapter.tag, img_tag, panel_path.name, parsed["confidence"])
                            translated = translate_text(cfg, raw_text, img_tag)
                            rephrased = rephrase_text(cfg, translated, img_tag, prev_tail)
                            if rephrased:
                                prev_tail = last_sentences(rephrased)
                            panel_narrations[idx] = (rephrased, OcrStatus.UNCERTAIN)
                        else:
                            translated = translate_text(cfg, raw_text, img_tag)
                            rephrased = rephrase_text(cfg, translated, img_tag, prev_tail)
                            if rephrased:
                                prev_tail = last_sentences(rephrased)
                            panel_narrations[idx] = (rephrased, OcrStatus.SUCCESS)

                    # Group frame positions by source panel (preserving timeline order).
                    from collections import defaultdict as _dd
                    panel_frame_positions = _dd(list)  # panel_index -> [frame_positions]
                    for pos, si in enumerate(frame_sources):
                        panel_frame_positions[si].append(pos)

                    for si, positions in panel_frame_positions.items():
                        narr, st = panel_narrations.get(si, ("", OcrStatus.NO_TEXT))
                        segments.append((f"img{si + 1:03d}", narr, positions, st))
            else:
                # No narration.json — all frames are silent (no text to narrate).
                log.warning("[%s] no narration.json — producing silent video for this chapter", chapter.tag)
                for pos in range(len(frame_paths)):
                    segments.append((f"frm{pos + 1:04d}", "", [pos], OcrStatus.NO_TEXT))

            # Pre-synthesize every segment's audio CONCURRENTLY into the
            # per-segment cache. TTS is dominated by the edge-tts network
            # round-trip (~1s each) which is pure I/O — running them in a
            # small thread pool turns ~40s of sequential waiting into ~5s.
            # The sequential loop below then hits each cached {tag}.wav
            # instantly, so its stateful timing math is untouched.
            _prewarm_segment_audio(cfg, chapter, segments)

            # Synthesize one continuous clip per segment and derive per-frame timing.
            # No whisper transcription — timing is derived purely from proportional
            # word-count splits, with a MIN_FRAME_DURATION floor so panels don't flash by.
            frame_timing = [None] * len(frame_paths)  # position -> (start, end) clip-local to its segment
            segment_audio_paths: List[Path] = []
            chapter_offset = 0.0
            tts_attempted = 0   # segments that HAD text (i.e. were supposed to produce real speech)
            tts_failed = 0      # of those, how many fell back to silence due to a real failure

            consecutive_silent = 0
            for seg_idx, seg_item in enumerate(segments):
                tag, text, positions = seg_item[0], seg_item[1], seg_item[2]
                ocr_st = seg_item[3] if len(seg_item) > 3 else (OcrStatus.SUCCESS if text.strip() else OcrStatus.NO_TEXT)

                cfg.write_progress("render", chapter.index - 1, total,
                                   f"Chapter {chapter.index}/{total}: TTS {seg_idx+1}/{len(segments)}",
                                   frac=0.05 + 0.50 * ((seg_idx + 1) / max(1, len(segments))),
                                   substage="tts")

                is_silent_segment = not text.strip() or ocr_st in (OcrStatus.NO_TEXT, OcrStatus.FAILED)
                if not is_silent_segment:
                    consecutive_silent = 0
                    tts_attempted += 1
                else:
                    consecutive_silent += 1

                audio_path_seg, seg_tts_failed, word_boundaries = synthesize_segment_audio(cfg, chapter, tag, text)
                if not is_silent_segment and seg_tts_failed:
                    tts_failed += 1

                duration = get_audio_duration(audio_path_seg)

                if is_silent_segment:
                    # Pacing safeguard: apply shortened duration for silent frames, and compress if consecutive > 2
                    base_silent_dur = 1.0 if consecutive_silent > 2 else SILENT_FRAME_DURATION
                    target_dur = max(0.5, len(positions) * base_silent_dur)
                    if abs(duration - target_dur) > 0.05:
                        audio_path_seg = cfg.temp_audio_dir / chapter.tag / f"{tag}_silent_paced.wav"
                        _generate_silence(audio_path_seg, target_dur)
                        duration = target_dur
                else:
                    min_total = len(positions) * MIN_FRAME_DURATION
                    if duration < min_total:
                        audio_path_seg = pad_audio_with_silence(audio_path_seg, min_total)
                        duration = min_total

                timings = split_frame_timings(text, positions, duration, is_silent=is_silent_segment, word_boundaries=word_boundaries)
                for pos in positions:
                    frame_timing[pos] = timings[pos]
                # The frame timings now include FRAME_HOLD_PADDING (0.5s per frame)
                # so the total visual duration is longer than the raw audio. Pad the
                # audio with trailing silence so the audio track matches the video.
                last_end = max((timings[p][1] for p in positions), default=duration)
                if last_end > duration:
                    audio_path_seg = pad_audio_with_silence(audio_path_seg, last_end)
                    duration = last_end
                segment_audio_paths.append(audio_path_seg)
                chapter_offset += duration

            # If most/all segments that HAD real dialogue to speak ended up
            # falling back to silence, this isn't "a quiet chapter" — it's a
            # broken TTS pipeline (most commonly: edge-tts's endpoint,
            # speech.platform.bing.com, is unreachable from this network —
            # firewall/security-list egress rules on cloud hosts are a common
            # cause). Every prior signal along the way (translation, rephrase,
            # loudnorm, mux) looks completely normal even when this has happened,
            # because each stage just sees "silence" as valid audio input and
            # passes it through without error. Surface it loudly here instead of
            # letting the job report success with a genuinely silent video.
            if tts_attempted > 0:
                tts_fail_ratio = tts_failed / tts_attempted
                if tts_fail_ratio >= 0.9:
                    log.error(
                        "[%s] TTS FAILED for %d/%d narrated segments (%.0f%%) — "
                        "edge-tts is not producing audio. Check network access to "
                        "speech.platform.bing.com from this host (firewall/security-"
                        "list egress rules are a common cause on cloud VMs). The "
                        "output video for this chapter will be SILENT.",
                        chapter.tag, tts_failed, tts_attempted, tts_fail_ratio * 100,
                    )
                elif tts_fail_ratio > 0.2:
                    log.warning(
                        "[%s] TTS failed for %d/%d narrated segments (%.0f%%) — "
                        "partial audio dropout, check edge-tts connectivity",
                        chapter.tag, tts_failed, tts_attempted, tts_fail_ratio * 100,
                    )

            # Build final per-frame durations from the timings.
            # Guard against None entries (can happen if a segment had no positions
            # or an error left a frame_timing slot unpopulated). Default to
            # MIN_FRAME_DURATION so the video never has a zero-duration frame.
            frame_durations = []
            for t in frame_timing:
                if t is not None:
                    frame_durations.append(t[1] - t[0])
                else:
                    frame_durations.append(MIN_FRAME_DURATION)
                    log.warning("[%s] frame_timing had None entry — using MIN_FRAME_DURATION (%.1fs)", chapter.tag, MIN_FRAME_DURATION)

            if manifest and manifest.frames:
                for pos, f_entry in enumerate(manifest.frames):
                    if pos < len(frame_durations):
                        f_entry.duration = frame_durations[pos]
                # Map each frame to ITS segment's narration text via the
                # segment's own `positions` list. `segments` is one entry per
                # source panel / scroll-group (~12), NOT one per frame (~40),
                # so the previous `segments[pos]` indexing silently pulled the
                # wrong panel's text onto every frame past the first dozen and
                # left the rest blank — a manifest-metadata desync (it does
                # not affect the rendered A/V, which is driven by
                # frame_durations + the assembled audio track).
                for seg in segments:
                    seg_text = seg[1] if len(seg) > 1 else ""
                    for sp in (seg[2] if len(seg) > 2 else []):
                        if 0 <= sp < len(manifest.frames):
                            manifest.frames[sp].narration_text = seg_text
                manifest.save(manifest_path)

            cfg.write_progress("render", chapter.index - 1, total,
                               f"Chapter {chapter.index}/{total}: building audio track",
                               frac=0.62, substage="audio")
            audio_path = build_chapter_audio_track(
                cfg, chapter, segment_audio_paths, narration_expected=tts_attempted > 0,
            ) if segment_audio_paths else None

            # The video timeline (frame_durations) was built to match the RAW,
            # pre-loudnorm segment audio exactly. But build_chapter_audio_track's
            # loudnorm pass (a single-pass/dynamic normalization, not two-pass
            # "measured" mode) can shift the final audio's duration by a small
            # but real amount due to its internal lookahead/limiter buffering.
            # render_chapter muxes with `-shortest`, so if the post-loudnorm
            # audio ends up LONGER than the video timeline, the tail of the
            # narration gets silently cut off mid-sentence. Re-probe the actual
            # final audio duration here and extend the last frame's hold time
            # to cover it, so narration is never truncated.
            if audio_path and audio_path.exists():
                try:
                    final_audio_duration = get_audio_duration(audio_path)
                    video_duration = sum(frame_durations)
                    if final_audio_duration > video_duration + 0.05 and frame_durations:
                        shortfall = final_audio_duration - video_duration
                        frame_durations[-1] += shortfall
                        log.info(
                            "[%s] extended last frame by %.3fs to cover loudnorm "
                            "duration drift (audio %.3fs vs video %.3fs) — "
                            "prevents narration from being cut off",
                            chapter.tag, shortfall, final_audio_duration, video_duration,
                        )
                except RuntimeError as e:
                    log.warning("[%s] could not verify final audio duration: %s", chapter.tag, e)

            cfg.write_progress("render", chapter.index - 1, total,
                               f"Chapter {chapter.index}/{total}: rendering {len(frame_paths)} frames",
                               frac=0.72, substage="encode")
            video_path = render_chapter_with_retry(cfg, chapter, frame_paths, frame_durations, audio_path)

            if not video_path:
                log.warning("[%s] rendering failed after retries — substituting silent black placeholder video", chapter.tag)
                expected_chap_dur = sum(frame_durations) if frame_durations else SILENT_FRAME_DURATION
                video_path = generate_black_placeholder_chapter(
                    cfg,
                    chapter.tag,
                    expected_chap_dur,
                    f"Chapter {chapter.index} unavailable",
                )
                placeholder_chapters.append(chapter.tag)
                state_store.record(
                    cfg.job_id, Stage.CHAPTER, State.RETRYABLE, chapter_id=chapter.tag,
                    error_code="RENDER_FAILED_PLACEHOLDER_USED", retry_category=classify_retry("render failed, placeholder used"),
                )
            else:
                state_store.record(
                    cfg.job_id, Stage.CHAPTER, State.COMPLETE, chapter_id=chapter.tag,
                    artifact_path=video_path, duration=time.time() - t0,
                )

            chapter_videos.append(video_path)

            log.info("[%s] done in %.1fs", chapter.tag, time.time() - t0)
            cfg.write_progress("render", chapter.index, total, f"Chapter {chapter.index}/{total} rendered")
        except Exception as e:
            # One chapter failing (TTS totally unavailable, a corrupt
            # source image, an OCR/ffmpeg crash, etc.) must not take
            # down the rest of a multi-day batch. Log it loudly, skip
            # this chapter (it's naturally retried on the next resumed
            # run since it never wrote a completed chapter video), and
            # keep processing the remaining chapters.
            log.error(
                "[%s] chapter FAILED and will be skipped this run: %s",
                chapter.tag, e, exc_info=True,
            )
            state_store.record(cfg.job_id, Stage.CHAPTER, State.RETRYABLE, chapter_id=chapter.tag,
                                error_message=str(e)[:500], retry_category=classify_retry(e))
            cfg.write_progress(
                "render", chapter.index, total,
                f"Chapter {chapter.index}/{total} FAILED: {e}", status="warning",
            )
            continue

    if not chapter_videos:
        state_store.record(cfg.job_id, Stage.JOB, State.FAILED, error_code="NO_CHAPTERS")
        cfg.write_progress("render", total, total, "No chapter videos produced", status="error")
        raise RuntimeError("No chapter videos were produced — nothing to merge.")

    dropped_chapters = total - len(chapter_videos)
    if dropped_chapters > 0:
        log.warning(
            "%d/%d chapters were skipped this run due to failures — job will "
            "complete with a video MISSING that content. Check pipeline_state.sqlite3 "
            "for RETRYABLE chapters and rerun the same --work-dir to fill them in.",
            dropped_chapters, total,
        )
    if placeholder_chapters:
        log.warning(
            "%d/%d chapters rendered as black \"unavailable\" placeholders "
            "after render retries failed (%s) — job will complete but is NOT "
            "a clean success. Check pipeline_state.sqlite3 for RETRYABLE "
            "chapters and rerun the same --work-dir to fill them in.",
            len(placeholder_chapters), total, ", ".join(placeholder_chapters),
        )

    if cfg.intro:
        try:
            cfg.write_progress("merge", total, total, "Building intro")
            intro_video = build_intro_video(cfg, chapters)
            if intro_video and intro_video.exists():
                chapter_videos = [intro_video, *chapter_videos]
        except Exception as e:
            log.warning("intro build failed (%s) — continuing without it", e)

    cfg.write_progress("merge", total, total, "Merging chapter videos")
    state_store.record(cfg.job_id, Stage.MERGE, State.RUNNING)
    try:
        merged = merge_chapters(cfg, chapter_videos)
        state_store.record(cfg.job_id, Stage.MERGE, State.COMPLETE, artifact_path=merged)
    except Exception as e:
        state_store.record(cfg.job_id, Stage.MERGE, State.FAILED, error_message=str(e)[:500],
                            retry_category=classify_retry(e))
        state_store.record(cfg.job_id, Stage.JOB, State.FAILED, error_code="MERGE_FAILED")
        raise

    cfg.write_progress("bgm", total, total, "Finalizing output")
    state_store.record(cfg.job_id, Stage.FINAL_QA, State.RUNNING)
    try:
        finalize_output(cfg, merged)
        state_store.record(cfg.job_id, Stage.FINAL_QA, State.COMPLETE, artifact_path=cfg.output_path)
    except Exception as e:
        state_store.record(cfg.job_id, Stage.FINAL_QA, State.FAILED, error_message=str(e)[:500],
                            retry_category=classify_retry(e))
        state_store.record(cfg.job_id, Stage.JOB, State.FAILED, error_code="FINAL_QA_FAILED")
        raise

    elapsed = time.time() - start
    # A placeholder chapter pads chapter_videos up to `total`, so
    # dropped_chapters alone would read as 0 for a run that actually has a
    # black "unavailable" screen standing in for real content — check both,
    # or a placeholder-only run would be misreported as a clean COMPLETE.
    final_state = State.UNCERTAIN if (dropped_chapters > 0 or placeholder_chapters) else State.COMPLETE
    state_store.record(cfg.job_id, Stage.JOB, final_state,
                        duration=elapsed, artifact_path=cfg.output_path,
                        metadata={
                            "chapters_total": total,
                            "chapters_dropped": dropped_chapters,
                            "chapters_placeholder": len(placeholder_chapters),
                        })

    # cleanup_temp() deletes cfg.work_dir, which is also where
    # pipeline_state.sqlite3 lives (see `state_store` above) — it must run
    # LAST, after every state_store.record() call, or the final JOB-COMPLETE
    # write above hits "unable to open database file" on its own now-deleted
    # directory and the process exits as if a fully successful render had
    # crashed (cfg.output_path itself lives outside work_dir and is already
    # safely written by this point either way).
    cleanup_temp(cfg)

    cfg.write_progress("done", total, total, f"Pipeline complete in {elapsed/60:.1f} min", status="done")
    log.info("PIPELINE COMPLETE in %.1f minutes. Output: %s", elapsed / 60, cfg.output_path)
    if dropped_chapters > 0 or placeholder_chapters:
        log.warning(
            "Job marked UNCERTAIN (not COMPLETE): %d/%d chapters missing, "
            "%d/%d chapters are black \"unavailable\" placeholders. This is "
            "not a silent success.",
            dropped_chapters, total, len(placeholder_chapters), total,
        )


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def parse_args(argv: Optional[List[str]] = None) -> PipelineConfig:
    parser = argparse.ArgumentParser(
        description="Convert local webtoon/manhwa chapter folders into a single master recap video."
    )
    parser.add_argument(
        "--input-dir", required=True, type=Path,
        help="Root dataset folder containing chapter_001/, chapter_002/, ... subfolders.",
    )
    parser.add_argument(
        "--total-chapters", type=int, default=None,
        help="Limit processing to the first N chapters (default: process all found).",
    )
    parser.add_argument(
        "--bgm", type=Path, default=None,
        help="Path to a background_music.mp3 file to loop under the narration at -20dB.",
    )
    parser.add_argument(
        "--output", type=Path, default=Path("master_recap.mp4"),
        help="Final output video path (default: ./master_recap.mp4).",
    )
    parser.add_argument(
        "--work-dir", type=Path, default=Path("./_pipeline_work"),
        help="Working directory for temp files (default: ./_pipeline_work). Reuse the same "
             "path across runs to resume an interrupted pipeline.",
    )
    parser.add_argument(
        "--voice", default="en-US-ChristopherNeural",
        help="edge-tts voice name (default: en-US-ChristopherNeural).",
    )
    parser.add_argument(
        "--openai-model", default="gpt-4o-mini",
        help="OpenAI model for narrative rewriting (default: gpt-4o-mini).",
    )
    parser.add_argument(
        "--openai-api-key", default=os.environ.get("OPENAI_API_KEY"),
        help="OpenAI API key for narrative rewriting (or set OPENAI_API_KEY env var).",
    )
    parser.add_argument(
        "--narration-provider", default="auto", choices=["auto", "openai", "groq", "ollama", "none"],
        help="LLM provider for narrative rewriting (default: auto = prefer OpenAI > Groq > Ollama > none).",
    )
    parser.add_argument(
        "--narration-model", default=None,
        help="Override the narration model name (default: openai_model or groq_model depending on provider).",
    )
    parser.add_argument(
        "--narration-style", default="verbatim", choices=["verbatim", "cleanup", "recap"],
        help="verbatim (default): the OCR's own words in order, no LLM, no translation. "
             "cleanup: same words, LLM fixes reading order + OCR splits only. "
             "recap: first-person retell (LLM).",
    )
    parser.add_argument(
        "--observer", action="store_true",
        help="verbatim only: let a tiny local LLM (ollama llama3.2:3b) repair garbled "
             "OCR words in place. Hard-guarded to spelling fixes — cannot reword or add.",
    )
    parser.add_argument(
        "--describe-visuals", action="store_true",
        help="OPTIONAL: caption each panel's visual action with a vision model and "
             "fold it into the narration (so action panels aren't silent). Off by default.",
    )
    parser.add_argument(
        "--visual-provider", default="auto",
        choices=["auto", "ollama", "smolvlm", "groq", "gemini", "openrouter", "none"],
        help="Vision engine for --describe-visuals (default: auto = cloud key if set, "
             "else off). 'smolvlm' = local SmolVLM2-500M, ~3.5s/panel on CPU, no key.",
    )
    parser.add_argument(
        "--visual-model", default=None,
        help="Override the vision model name (e.g. 'moondream', 'llava:7b', 'llama-3.2-90b-vision-preview').",
    )
    parser.add_argument(
        "--gemini-api-key", default=os.environ.get("GEMINI_API_KEY"),
        help="Google Gemini API key (free tier) — used for --describe-visuals / narration if set.",
    )
    parser.add_argument(
        "--openrouter-api-key", default=os.environ.get("OPENROUTER_API_KEY"),
        help="OpenRouter API key — used for --describe-visuals / narration if set.",
    )
    parser.add_argument(
        "--motion", default="none", choices=["none", "kenburns"],
        help="none (default): fast static slideshow. kenburns: subtle slow camera drift over each panel.",
    )
    parser.add_argument(
        "--progress-file", type=Path, default=None,
        help="JSON file path to write progress updates to (polled by the Node orchestrator).",
    )
    parser.add_argument(
        "--groq-api-key", default=os.environ.get("GROQ_API_KEY"),
        help="Groq API key used to translate non-English chapter text to English "
             "before narration rewriting (or set GROQ_API_KEY env var). "
             "If omitted, translation is skipped and raw text is used as-is.",
    )
    parser.add_argument(
        "--groq-model", default=os.environ.get("GROQ_TEXT_MODEL", "qwen/qwen3.8-27b"),
        help="Groq model used for translation (default: llama-3.3-70b-versatile).",
    )
    parser.add_argument(
        "--no-translate", action="store_true",
        help="Disable the translation step even if a Groq key is available.",
    )
    parser.add_argument(
        "--keep-temp", action="store_true",
        help="Do not delete the working directory after a successful run.",
    )
    parser.add_argument(
        "-v", "--verbose", action="store_true", help="Enable debug logging.",
    )
    parser.add_argument("--production-mode", action="store_true", help="Use local-only production mode: no edge-tts/OpenAI dependency checks or runtime installs.")
    parser.add_argument("--job-id", default="local", help="Stable job id for production state/recovery records.")
    parser.add_argument(
        "--min-free-disk-gb", type=float, default=2.0,
        help="Abort (or pause between chapters) if free disk on the work-dir's "
             "filesystem drops below this many GB (default: 2.0). A multi-day "
             "unattended batch on a small free-tier disk is exactly the "
             "scenario this guards against — better to fail loudly here than "
             "have ffmpeg or Piper fail unpredictably mid-write from a full disk.",
    )
    parser.add_argument(
        "--min-available-ram-mb", type=float, default=300.0,
        help="Pause between chapters if available RAM drops below this many MB "
             "(default: 300). Checked before each chapter, not just at startup, "
             "since memory pressure on a small instance tends to build up over "
             "a long batch rather than being present on day one.",
    )
    parser.add_argument("--recap-title", default=None,
                        help="Series title shown on the intro card (default: input-dir name).")
    parser.add_argument("--no-intro", action="store_true",
                        help="Skip the spoken intro + title card.")
    parser.add_argument("--watermark", default=os.environ.get("RECAP_WATERMARK"),
                        help="Small watermark text drawn on every frame (e.g. a channel name).")
    parser.add_argument(
        "--slice-only", action="store_true",
        help="Only run the panel-slicing stage for all chapters, then exit. "
             "Writes frame_NNNNN.jpg files + manifest.json under work/temp_slices/chapter_XXX/. "
             "Used by the Node orchestrator so the VLM can transcribe each individual sliced panel "
             "before the full render pipeline runs (improves narration accuracy).",
    )

    args = parser.parse_args(argv)
    if args.verbose:
        log.setLevel(logging.DEBUG)

    if args.bgm and not args.bgm.exists():
        parser.error(f"--bgm file not found: {args.bgm}")

    return PipelineConfig(
        input_dir=args.input_dir,
        output_path=args.output,
        total_chapters=args.total_chapters,
        bgm_path=args.bgm,
        work_dir=args.work_dir,
        voice=args.voice,
        openai_model=args.openai_model,
        openai_api_key=args.openai_api_key,
        keep_temp=args.keep_temp,
        groq_api_key=args.groq_api_key,
        groq_model=args.groq_model,
        translate=not args.no_translate,
        narration_provider=args.narration_provider,
        narration_model=args.narration_model,
        narration_style=args.narration_style,
        observer=args.observer,
        describe_visuals=args.describe_visuals,
        visual_provider=args.visual_provider,
        visual_model=args.visual_model,
        gemini_api_key=args.gemini_api_key,
        openrouter_api_key=args.openrouter_api_key,
        motion=args.motion,
        progress_file=args.progress_file,
        slice_only=args.slice_only,
        production_mode=args.production_mode,
        job_id=args.job_id,
        recap_title=args.recap_title,
        intro=not args.no_intro,
        watermark=args.watermark,
        min_free_disk_gb=args.min_free_disk_gb,
        min_available_ram_mb=args.min_available_ram_mb,
    )


def check_dependencies(cfg: Optional[PipelineConfig] = None) -> None:
    """Fail fast with a clear message if required tools are missing.

    In --slice-only mode, edge-tts is not needed (slicing only uses cv2/PIL/numpy),
    so we skip that check to allow pre-slicing even if TTS deps aren't installed yet.

    AUTO-INSTALL: if edge-tts is missing, attempt to install it via pip before
    failing. This handles the case where the Python venv gets reset.
    """
    if shutil.which("ffmpeg") is None:
        log.error("ffmpeg not found on PATH. Install it (e.g. `apt install ffmpeg` / `brew install ffmpeg`).")
        sys.exit(1)
    if cfg is not None and (getattr(cfg, "slice_only", False) or getattr(cfg, "production_mode", False)):
        return
    try:
        import edge_tts  # noqa: F401
    except ImportError:
        log.error("edge-tts missing. Install pipeline dev dependencies or run --production-mode for local Piper/eSpeak TTS.")
        sys.exit(1)


def run_slice_only(cfg: PipelineConfig) -> None:
    """Run ONLY the panel-slicing stage for all chapters, then exit.

    This produces work/temp_slices/chapter_XXX/frame_NNNNN.jpg + manifest.json
    for every chapter, so the Node orchestrator can run the VLM on each
    individual sliced panel (much more accurate than reading a full page with
    multiple panels at once). The full render pipeline reuses these slices
    via manifest resume support.
    """
    start = time.time()
    cfg.ensure_dirs()
    chapters = discover_chapters(cfg)
    total = len(chapters)
    if total == 0:
        log.error("No chapters found under %s", cfg.input_dir)
        return
    log.info("=== SLICE-ONLY MODE: %d chapter(s) ===", total)
    cfg.write_progress("slice", 0, total, f"Preparing {total} chapter(s)…", substage="frame")
    total_frames = 0
    _SUB_LABEL = {"frame": "Slicing panels", "ocr": "Reading panel text",
                  "visual": "Describing panels"}
    for _idx, chapter in enumerate(chapters):
        t0 = time.time()
        log.info("--- Chapter %d/%d (%s) ---", chapter.index, total, chapter.name)

        def _cb(sub, frac, _ci=_idx, _cn=chapter.index):
            cfg.write_progress(
                "slice", _ci, total,
                f"Chapter {_cn}/{total}: {_SUB_LABEL.get(sub, sub)}…",
                frac=frac, substage=sub,
            )

        _cb("frame", 0.0)
        frame_data = slice_chapter_panels(cfg, chapter, phase_cb=_cb)
        n = len(frame_data)
        total_frames += n
        dt = time.time() - t0
        log.info("[%s] %d frames from %d source panels (%.1fs)",
                 chapter.tag, n, len(chapter.panel_paths), dt)
        cfg.write_progress("slice", _idx, total,
                           f"Chapter {chapter.index}/{total}: {n} panels ready",
                           frac=1.0, substage="ocr")
    log.info("=== SLICE-ONLY DONE: %d chapters, %d total frames in %.1fs ===",
             total, total_frames, time.time() - start)
    cfg.write_progress("done", total, total,
                       f"Slicing complete: {total_frames} frames across {total} chapter(s).")


def main() -> int:
    cfg = parse_args()
    check_dependencies(cfg)
    try:
        if cfg.slice_only:
            run_slice_only(cfg)
        else:
            run_pipeline(cfg)
        return 0
    except SystemExit:
        raise
    except Exception as e:
        log.error("Pipeline failed: %s", e)
        log.info(
            "Progress is saved under %s — rerun the same command to resume "
            "from the last completed chapter.",
            cfg.work_dir,
        )
        return 1

if __name__ == "__main__":
    sys.exit(main())
